window.BASAIR_QUESTIONS=window.BASAIR_QUESTIONS.concat([{"id":"s19-32","number":32,"surah":19,"verses":[20],"verseLabel":"مريم: 20","question":"ما دلالة قولها: ﴿وَلَمْ أَكُ بَغِيًّا﴾ بعد نفي مساس البشر؟","answer":"نفت الطريقين: الزواج المشروع والفاحشة، فاستحال الحمل بحسب الأسباب المعتادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص66–71.","url":""}]},{"id":"s19-33","number":33,"surah":19,"verses":[21],"verseLabel":"مريم: 21","question":"ما سرّ التعبير بـ﴿وَلِنَجْعَلَهُ آيَةً لِلنَّاسِ وَرَحْمَةً مِنَّا﴾؟","answer":"ميلاده دليل قدرة للناس، ورسالته رحمة تهديهم؛ فجمع البرهان والثمرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص74–80.","url":""}]},{"id":"s19-34","number":34,"surah":19,"verses":[21],"verseLabel":"مريم: 21","question":"لماذا ختم بـ﴿وَكَانَ أَمْرًا مَقْضِيًّا﴾؟","answer":"قطع بوقوع ما استعظمته؛ إذا قضى الله أمرًا تجاوز استبعاد الأسباب.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص80–82.","url":""}]},{"id":"s19-35","number":35,"surah":19,"verses":[22],"verseLabel":"مريم: 22","question":"لماذا انتبذت بالحمل ﴿مَكَانًا قَصِيًّا﴾؟","answer":"ابتعدت اتقاء أعين الناس وكلامهم، فزاد المكان البعيد إحساس وحدتها وكربها.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص84–89.","url":""}]},{"id":"s19-36","number":36,"surah":19,"verses":[23],"verseLabel":"مريم: 23","question":"لماذا ألجأها المخاض إلى ﴿جِذْعِ النَّخْلَةِ﴾؟","answer":"ألجأها المخاض إلى جذع النخلة لتستند إليه عند شدة الولادة، ثم خُص الجذع تمهيدًا للكرامة التي ظهرت بتساقط الرطب.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص92–94.","url":""}]},{"id":"s19-37","number":37,"surah":19,"verses":[23],"verseLabel":"مريم: 23","question":"ما دلالة قول مريم ﴿يَا لَيْتَنِي مِتُّ قَبْلَ هَذَا وَكُنْتُ نَسْيًا مَنْسِيًّا﴾؟","answer":"بلغ بها خوف التهمة مبلغ تمني الغياب التام من الوجود والذاكرة، لا اعتراضًا على قضاء الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص95–97.","url":""}]},{"id":"s19-38","number":38,"surah":19,"verses":[24],"verseLabel":"مريم: 24","question":"لماذا نوديت ﴿مِنْ تَحْتِهَا﴾؟","answer":"حدد ﴿من تحتها﴾ جهة النداء القريبة منها، ودل على انفصال المولود عنها، فكان في النداء العاجل تسلية وطمأنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص100–103.","url":""}]},{"id":"s19-39","number":39,"surah":19,"verses":[24],"verseLabel":"مريم: 24","question":"ما المراد بـ﴿سَرِيًّا﴾ ولماذا اختير؟","answer":"السري قيل: جدول الماء الجاري تحتها، وقيل: عيسى، أي السيد الشريف؛ والقول الأول هو قول جمهور المفسرين في الموضع.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص98–104.","url":""}]},{"id":"s19-40","number":40,"surah":19,"verses":[25],"verseLabel":"مريم: 25","question":"لماذا أُمرت أن تهز جذع النخلة مع ضعفها؟","answer":"تعليم للأخذ بالسبب ولو كان ضعيف الأثر ظاهرًا؛ فالرزق من الله لكن العبد يتحرك إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص107–108.","url":""}]},{"id":"s19-41","number":41,"surah":19,"verses":[25],"verseLabel":"مريم: 25","question":"ما سرّ وصف الرطب بـ﴿جَنِيًّا﴾؟","answer":"أي طريًا قد حان قطافه، فجاءها الغذاء كامل النضج في غير أوانه المعتاد.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص110–111.","url":""}]},{"id":"s19-42","number":42,"surah":19,"verses":[26],"verseLabel":"مريم: 26","question":"لماذا جمع لها ﴿فَكُلِي وَاشْرَبِي وَقَرِّي عَيْنًا﴾؟","answer":"جمع لها الطعام والشراب وقرار العين، فشمل الإحسان بدنها وروحها ظاهرًا وباطنًا، وتدرج في تسليتها من دفع الجوع والعطش إلى طمأنينة النفس.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص115–116.","url":""}]},{"id":"s19-43","number":43,"surah":19,"verses":[26],"verseLabel":"مريم: 26","question":"كيف يكون الصوم ﴿فَلَنْ أُكَلِّمَ الْيَوْمَ إِنْسِيًّا﴾؟","answer":"كان الصمت عن مخاطبة الناس عبادة مشروعة في شريعتهم، وتولى المولود الدفاع عنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص117–121.","url":""}]},{"id":"s19-44","number":44,"surah":19,"verses":[27],"verseLabel":"مريم: 27","question":"ما سرّ التعبير بـ﴿فَأَتَتْ بِهِ قَوْمَهَا تَحْمِلُهُ﴾؟","answer":"التصريح بحمله يرسم شجاعتها في مواجهة القوم بالآية نفسها بدل إخفائها.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص125–128.","url":""}]},{"id":"s19-45","number":45,"surah":19,"verses":[27],"verseLabel":"مريم: 27","question":"ما دلالة وصف قوم مريم ما رأوه بـ﴿شَيْئًا فَرِيًّا﴾؟","answer":"الفري الأمر العظيم البديع أو المفتَرى؛ عبّر عن صدمتهم وحكمهم قبل سماع الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص129–130.","url":""}]},{"id":"s19-46","number":46,"surah":19,"verses":[28],"verseLabel":"مريم: 28","question":"لماذا نادوها ﴿يَا أُخْتَ هَارُونَ﴾؟","answer":"نسبوها إلى هارون؛ فقيل هو رجل صالح من قومها، وقيل أخوها، وقيل المراد الانتساب إلى بيت صلاح، واستدعوا بذلك المقارنة بين صلاح أهلها وما توهموه منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص134–138.","url":""}]},{"id":"s19-47","number":47,"surah":19,"verses":[29],"verseLabel":"مريم: 29","question":"لماذا اكتفت مريم بالإشارة إلى عيسى؟","answer":"وفاء بنذر الصمت، وتسليم للآية أن تدافع عن نفسها بكلام المولود الذي لا يمكن اتهامه بالتواطؤ.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص142–143.","url":""}]},{"id":"s19-48","number":48,"surah":19,"verses":[30],"verseLabel":"مريم: 30","question":"لماذا كانت أول كلمة لعيسى ﴿إِنِّي عَبْدُ اللَّهِ﴾؟","answer":"بدأ بـ﴿إني عبد الله﴾ لإثبات عبوديته لله من أول كلامه، وفي ذلك ردّ على من غلا فيه وادعى له الألوهية.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص148–150.","url":""}]},{"id":"s19-49","number":49,"surah":19,"verses":[30],"verseLabel":"مريم: 30","question":"ما سرّ التعبير بـ﴿آتَانِيَ الْكِتَابَ وَجَعَلَنِي نَبِيًّا﴾ بصيغة الماضي؟","answer":"لتحقق الوعد في علم الله حتى عُبر عن المستقبل كأنه وقع.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص150–151.","url":""}]},{"id":"s19-50","number":50,"surah":19,"verses":[31],"verseLabel":"مريم: 31","question":"ما سرّ التعبير بـ﴿مُبَارَكًا أَيْنَ مَا كُنْتُ﴾؟","answer":"عمّم نفعه في كل مكان وحال؛ فالبركة ليست مرتبطة ببقعة أو زمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص152–155.","url":""}]},{"id":"s19-51","number":51,"surah":19,"verses":[31],"verseLabel":"مريم: 31","question":"لماذا قيد الصلاة والزكاة بـ﴿مَا دُمْتُ حَيًّا﴾؟","answer":"ليبين استمرار العبودية والتكليف طوال الحياة، فلا ترفعه النبوة عن العبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص156.","url":""}]},{"id":"s19-52","number":52,"surah":19,"verses":[32],"verseLabel":"مريم: 32","question":"ما سرّ وصف عيسى بـ﴿جَبَّارًا شَقِيًّا﴾؟","answer":"نفي الجبروت يلائم بره بأمه، ونفي الشقاء يبرئه من رضا ما سيقوله الغالون فيه، ويقرر أنه مطيع لله غير خارج عن رحمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص158–161.","url":""}]},{"id":"s19-53","number":53,"surah":19,"verses":[33],"verseLabel":"مريم: 33","question":"ما سرّ تعبير عيسى بـ﴿وَالسَّلَامُ عَلَيَّ﴾؟","answer":"حكى عيسى ما جعله الله له من السلام والأمان في مواطن الولادة والموت والبعث، وجاء التعريف لاستغراق جنس السلام أو للعهد بسلام يحيى السابق.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص163–164.","url":""}]},{"id":"s19-54","number":54,"surah":19,"verses":[34],"verseLabel":"مريم: 34","question":"ما سرّ التعبير بـ﴿ذَلِكَ عِيسَى ابْنُ مَرْيَمَ﴾ بعد كلامه؟","answer":"عينه اسم الإشارة تمييزًا لحقيقته وردًا على اختلاف اليهود والنصارى، وأضافه إلى مريم لتأكيد بشريته ونسبه إليها وأنه لا والد له.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص165–167.","url":""}]},{"id":"s19-55","number":55,"surah":19,"verses":[34],"verseLabel":"مريم: 34","question":"ما سرّ وصف خبره بـ﴿قَوْلَ الْحَقِّ﴾؟","answer":"إضافة القول إلى الحق تؤكد صدقه وثبوته من كل جانب، في مقابلة امتراء المختلفين في عيسى ونسبهم إليه ما ليس من صفته.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص168–170.","url":""}]},{"id":"s19-56","number":56,"surah":19,"verses":[35],"verseLabel":"مريم: 35","question":"ما سرّ التعبير بـ﴿مَا كَانَ لِلَّهِ أَنْ يَتَّخِذَ مِنْ وَلَدٍ﴾؟","answer":"صيغة ﴿ما كان لله﴾ تنفي اتخاذ الولد نفيًا بالغًا في جميع الأزمنة، و﴿من﴾ تؤكد نفي الواحد والجماعة؛ لأن اتخاذ الولد لا يليق بكمال الله وتنزهه.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص171–175.","url":""}]},{"id":"s19-57","number":57,"surah":19,"verses":[35],"verseLabel":"مريم: 35","question":"لماذا عقب نفي الولد بـ﴿إِذَا قَضَى أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُنْ فَيَكُونُ﴾؟","answer":"ميلاد عيسى بلا أب أثر لكلمة القدرة، لا دليل بنوة؛ فالخالق لا يحتاج إلى التوالد.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص175–177.","url":""}]},{"id":"s19-58","number":58,"surah":19,"verses":[36],"verseLabel":"مريم: 36","question":"ما سرّ التعبير بـ﴿هَذَا صِرَاطٌ مُسْتَقِيمٌ﴾ بعد الأمر بالعبادة؟","answer":"أشير بـ﴿هذا﴾ إلى توحيد الله وعبادته المذكورين قبله، وجُعلا صراطًا واضحًا مستقيمًا يوصل سالكه إلى الحق بلا اعوجاج.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص179–183.","url":""}]},{"id":"s19-59","number":59,"surah":19,"verses":[37],"verseLabel":"مريم: 37","question":"ما سرّ التعبير هنا بـ﴿فَوَيْلٌ لِلَّذِينَ كَفَرُوا﴾، وفي الزخرف ﴿فَوَيْلٌ لِلَّذِينَ ظَلَمُوا﴾؟","answer":"فُصّلت قصة عيسى في مريم، وذُكرت فيها مقالة نسبة الولد إلى الله، فناسب وصف أصحابها بالكفر؛ وأُجملت في الزخرف فجيء بوصف الظلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص184–190.","url":""}]},{"id":"s19-60","number":60,"surah":19,"verses":[39],"verseLabel":"مريم: 39","question":"لماذا سمي يوم القيامة ﴿يَوْمَ الْحَسْرَةِ﴾؟","answer":"لأن الحقائق تنكشف بعد انقطاع زمن العمل، فتبلغ الحسرة غايتها ولا يمكن التدارك.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص197–206.","url":""}]},{"id":"s19-61","number":61,"surah":19,"verses":[40],"verseLabel":"مريم: 40","question":"ما سرّ التعبير بـ﴿إِنَّا نَحْنُ نَرِثُ الْأَرْضَ وَمَنْ عَلَيْهَا﴾؟","answer":"المؤكدات تقرر زوال كل مالك وبقاء الملك لله وحده، فيبطل الاغترار بالدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص207–213.","url":""}]},{"id":"s19-62","number":62,"surah":19,"verses":[41],"verseLabel":"مريم: 41","question":"ما سرّ وصف إبراهيم بـ﴿صِدِّيقًا نَبِيًّا﴾؟","answer":"﴿صديقًا﴾ صيغة مبالغة تثبت رسوخ صدقه وتصديقه، ثم ذُكرت النبوة التي اصطفاه الله لها؛ فاجتمع كمال الصدق وشرف الرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص214–218.","url":""}]},{"id":"s19-63","number":63,"surah":19,"verses":[42,43,44,45],"verseLabel":"مريم: 42-45","question":"لماذا كرر إبراهيم نداء ﴿يَا أَبَتِ﴾ في كل حجة؟","answer":"ليغلف التصحيح العقدي بالبر واللطف، فلا يحول إنكار الباطل إلى قسوة على الوالد.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص219–248.","url":""}]},{"id":"s19-64","number":64,"surah":19,"verses":[42],"verseLabel":"مريم: 42","question":"ما سرّ التعبير بـ﴿لِمَ تَعْبُدُ مَا لَا يَسْمَعُ وَلَا يُبْصِرُ﴾؟","answer":"بدأ بأوضح تناقض حسي: المعبود العاجز عن الإدراك والنفع لا يستحق العبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص219–225.","url":""}]},{"id":"s19-65","number":65,"surah":19,"verses":[43],"verseLabel":"مريم: 43","question":"ما سرّ التعبير بـ﴿قَدْ جَاءَنِي مِنَ الْعِلْمِ مَا لَمْ يَأْتِكَ﴾؟","answer":"لم يدع إحاطة العلم، بل ذكر القدر الذي خصه الله به، فجمع الحجة والتواضع.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص226–231.","url":""}]},{"id":"s19-66","number":66,"surah":19,"verses":[43],"verseLabel":"مريم: 43","question":"ما سرّ وصف الطريق بـ﴿صِرَاطًا سَوِيًّا﴾؟","answer":"السوي مستوٍ لا عوج فيه، يناسب عرض الابن طريقًا مأمونًا لأبيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص226–231.","url":""}]},{"id":"s19-67","number":67,"surah":19,"verses":[44],"verseLabel":"مريم: 44","question":"ما سرّ التعبير بـ﴿لَا تَعْبُدِ الشَّيْطَانَ﴾ مع أن أباه يعبد الأصنام؟","answer":"طاعة الشيطان في الشرك عبادة له من جهة الانقياد، فكشف المحرك الخفي وراء الصنم.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص232–238.","url":""}]},{"id":"s19-68","number":68,"surah":19,"verses":[45],"verseLabel":"مريم: 45","question":"ما سرّ التعبير بـ﴿أَنْ يَمَسَّكَ عَذَابٌ مِنَ الرَّحْمَنِ﴾؟","answer":"اختير ﴿يمسّك﴾ تلطفًا في الإنذار وإشعارًا بأدنى إصابة من العذاب، وذُكر اسم الرحمن لتغليظ عصيان من عمته الرحمة وإبقاء باب الرجاء ظاهرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص239–248.","url":""}]},{"id":"s19-69","number":69,"surah":19,"verses":[46],"verseLabel":"مريم: 46","question":"لماذا قابل الأب لطف إبراهيم بقوله ﴿لَأَرْجُمَنَّكَ وَاهْجُرْنِي مَلِيًّا﴾؟","answer":"قابل الأب حجج إبراهيم اللطيفة بالإنكار والتهديد بالرجم، ثم أمره بالهجر زمنًا طويلًا؛ فبرزت شدة الجفاء في مقابلة رفق الابن.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص249–259.","url":""}]},{"id":"s19-70","number":70,"surah":19,"verses":[47],"verseLabel":"مريم: 47","question":"لماذا أجابه إبراهيم ﴿سَلَامٌ عَلَيْكَ﴾؟","answer":"قابل الوعيد بالأمان وترك الجدال، فجمع البر والثبات على الاعتزال.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص260–265.","url":""}]},{"id":"s19-71","number":71,"surah":19,"verses":[48],"verseLabel":"مريم: 48","question":"ما سرّ التعبير بـ﴿عَسَى أَلَّا أَكُونَ بِدُعَاءِ رَبِّي شَقِيًّا﴾؟","answer":"قابل خيبة عبادة الأصنام برجاء الدعاء لله الذي لا يشقي من أخلص له.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص266–273.","url":""}]},{"id":"s19-72","number":72,"surah":19,"verses":[49],"verseLabel":"مريم: 49","question":"ما سرّ التعبير بـ﴿وَكُلًّا جَعَلْنَا نَبِيًّا﴾ بعد ذكر إسحاق ويعقوب؟","answer":"أكد أن الهبة لم تكن ذرية فحسب، بل امتداد نبوة ورسالة بعد الاعتزال لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص274–281.","url":""}]},{"id":"s19-73","number":73,"surah":19,"verses":[50],"verseLabel":"مريم: 50","question":"ما سرّ التعبير بـ﴿وَجَعَلْنَا لَهُمْ لِسَانَ صِدْقٍ عَلِيًّا﴾؟","answer":"استعار اللسان للذكر الجميل الباقي، ووصفه بالعلو لانتشاره وشرفه بين الأمم.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص282–288.","url":""}]},{"id":"s19-74","number":74,"surah":19,"verses":[51],"verseLabel":"مريم: 51","question":"ما سرّ وصف موسى بـ﴿مُخْلَصًا﴾ ثم ﴿رَسُولًا نَبِيًّا﴾؟","answer":"دل وصف موسى بـ﴿مخلصًا/مخلِصًا﴾ على اصطفائه وإخلاصه، و﴿رسولًا نبيًا﴾ جمع له تلقي الوحي وإبلاغ الرسالة؛ فالرسول أخص من النبي من جهة التبليغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص289–295.","url":""}]},{"id":"s19-75","number":75,"surah":19,"verses":[52],"verseLabel":"مريم: 52","question":"ما سرّ التعبير بـ﴿وَقَرَّبْنَاهُ نَجِيًّا﴾؟","answer":"النجِي من يناجى سرًا؛ فصور تشريف موسى بالقرب وسماع الخطاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص296–308.","url":""}]},{"id":"s19-76","number":76,"surah":19,"verses":[53],"verseLabel":"مريم: 53","question":"ما سرّ التعبير بـ﴿وَوَهَبْنَا لَهُ مِنْ رَحْمَتِنَا أَخَاهُ هَارُونَ نَبِيًّا﴾؟","answer":"جعل أخوة المعونة والنبوة هبة رحمة استجابة لدعاء موسى، لا حقًا عائليًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص296–308.","url":""}]},{"id":"s19-77","number":77,"surah":19,"verses":[54],"verseLabel":"مريم: 54","question":"ما سرّ وصف إسماعيل بـ﴿صَادِقَ الْوَعْدِ﴾؟","answer":"خص خصلة تمس معاملات الناس، فصدق المواعيد شاهد عملي على صدق النبوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص309–321.","url":""}]},{"id":"s19-78","number":78,"surah":19,"verses":[55],"verseLabel":"مريم: 55","question":"ما سرّ التعبير بـ﴿وَكَانَ يَأْمُرُ أَهْلَهُ بِالصَّلَاةِ وَالزَّكَاةِ﴾؟","answer":"بدأ الإصلاح بمن تحت مسؤوليته، وجمع عبادة البدن وحق المال.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص309–321.","url":""}]},{"id":"s19-79","number":79,"surah":19,"verses":[57],"verseLabel":"مريم: 57","question":"لماذا رفع إدريس ﴿مَكَانًا عَلِيًّا﴾؟","answer":"ورد في رفع إدريس قولان مشهوران: رفع المنزلة والذكر، ورفع المكان حقيقة؛ فإطلاق ﴿مكانًا عليًا﴾ يحتمل رفعة القدر ورفعة المكان.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص322–329.","url":""}]},{"id":"s19-80","number":80,"surah":19,"verses":[58],"verseLabel":"مريم: 58","question":"ما سرّ التعبير بـ﴿خَرُّوا سُجَّدًا وَبُكِيًّا﴾؟","answer":"جمع خضوع الجسد وانفعال القلب؛ فالآيات لم تبق معرفة عقلية بل حركت الكيان كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص330–346.","url":""}]},{"id":"s19-81","number":81,"surah":19,"verses":[59],"verseLabel":"مريم: 59","question":"لماذا قابل إضاعة الصلاة باتباع الشهوات؟","answer":"جاء اتباع الشهوات عقب إضاعة الصلاة؛ لأن تضييع أعظم الصلات بالله يفتح طريق الانقياد للشهوات، فجمع النص أصل التفريط وأثره.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص347–362.","url":""}]},{"id":"s19-82","number":82,"surah":19,"verses":[59],"verseLabel":"مريم: 59","question":"ما سرّ التعبير بـ﴿فَسَوْفَ يَلْقَوْنَ غَيًّا﴾؟","answer":"الغي ضلال ووادٍ من العذاب؛ فالعاقبة من جنس الطريق الذي اختاروه.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص347–362.","url":""}]},{"id":"s19-83","number":83,"surah":19,"verses":[60],"verseLabel":"مريم: 60","question":"ما سرّ التعبير هنا بـ﴿وَعَمِلَ صَالِحًا﴾، وفي الفرقان ﴿وَعَمِلَ عَمَلًا صَالِحًا﴾؟","answer":"سياق مريم أوجز في ذكر المعاصي فأوجز في التوبة، وسياق الفرقان فصّل فناسبه التصريح بالمفعول.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص347–362.","url":""}]},{"id":"s19-84","number":84,"surah":19,"verses":[61],"verseLabel":"مريم: 61","question":"ما سرّ وصف الجنة بـموعودة ﴿بِالْغَيْبِ﴾؟","answer":"الإيمان بها قبل رؤيتها هو موضع الاختبار، ووعد الرحمن يحقق الغائب كأنه مشهود.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص363–383.","url":""}]},{"id":"s19-85","number":85,"surah":19,"verses":[61],"verseLabel":"مريم: 61","question":"ما سرّ التعبير بـ﴿إِنَّهُ كَانَ وَعْدُهُ مَأْتِيًّا﴾ لا «آتيا»؟","answer":"صوّر الوعد كأنه مقصد يأتيه أهله ويصلون إليه، مبالغة في تحقق الوقوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص363–383.","url":""}]},{"id":"s19-86","number":86,"surah":19,"verses":[62],"verseLabel":"مريم: 62","question":"لماذا لا يسمعون في الجنة لغوًا ﴿إِلَّا سَلَامًا﴾؟","answer":"الاستثناء منقطع أو من جنس الكلام؛ لا يصل آذانهم إلا ما يمنح الأمن والكرامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص363–383.","url":""}]},{"id":"s19-87","number":87,"surah":19,"verses":[63],"verseLabel":"مريم: 63","question":"ما سرّ التعبير بـ﴿تِلْكَ الْجَنَّةُ الَّتِي نُورِثُ مِنْ عِبَادِنَا﴾؟","answer":"اسم الإشارة يفخم شأن الجنة ويقرب صورتها، والتعبير بالإرث يدل على تمليكها لعباد الله المتقين تمليكًا ثابتًا بعد زوال ملك الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص363–383.","url":""}]},{"id":"s19-88","number":88,"surah":19,"verses":[64],"verseLabel":"مريم: 64","question":"ما دلالة قولها: الملائكة ﴿وَمَا نَتَنَزَّلُ إِلَّا بِأَمْرِ رَبِّكَ﴾؟","answer":"تنفي استقلالها بالنزول وترد تأخر الوحي أو مجيئه إلى تدبير الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص384–394.","url":""}]},{"id":"s19-89","number":89,"surah":19,"verses":[65],"verseLabel":"مريم: 65","question":"ما سرّ التعبير بـ﴿هَلْ تَعْلَمُ لَهُ سَمِيًّا﴾؟","answer":"استفهام إنكاري ينفي أن يماثله أحد في اسمه الكامل وصفاته واستحقاق العبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص395–402.","url":""}]},{"id":"s19-90","number":90,"surah":19,"verses":[66],"verseLabel":"مريم: 66","question":"لماذا حكى قول الإنسان ﴿أَإِذَا مَا مِتُّ لَسَوْفَ أُخْرَجُ حَيًّا﴾؟","answer":"جمع أداة الشرط والتوكيد ليصور شدة استبعاده للبعث وسخريته منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص403–413.","url":""}]},{"id":"s19-91","number":91,"surah":19,"verses":[67],"verseLabel":"مريم: 67","question":"لماذا احتج عليه بأنه خُلق من قبل ﴿وَلَمْ يَكُ شَيْئًا﴾؟","answer":"الإيجاد من العدم أبلغ في القدرة من إعادة مادة كانت موجودة.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص403–413.","url":""}]},{"id":"s19-92","number":92,"surah":19,"verses":[68],"verseLabel":"مريم: 68","question":"لماذا جمع الكافرين مع الشياطين في الحشر؟","answer":"يُحشر المتبوع والتابع معًا لتنكشف حقيقة الولاية التي جمعتهم في الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص414–419.","url":""}]},{"id":"s19-93","number":93,"surah":19,"verses":[68],"verseLabel":"مريم: 68","question":"ما سرّ التعبير بـ﴿ثُمَّ لَنُحْضِرَنَّهُمْ حَوْلَ جَهَنَّمَ جِثِيًّا﴾؟","answer":"«جثيا» على الركب تصور ذلهم وعجزهم وهم ينتظرون الحكم حول النار.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص414–419.","url":""}]},{"id":"s19-94","number":94,"surah":19,"verses":[69],"verseLabel":"مريم: 69","question":"ما سرّ التعبير بـ﴿أَيُّهُمْ أَشَدُّ عَلَى الرَّحْمَنِ عِتِيًّا﴾؟","answer":"يبدأ بأعتاهم لأنهم قادة التمرد، واسم الرحمن يشدد قبح العتو على واسع الرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص420–427.","url":""}]},{"id":"s19-95","number":95,"surah":19,"verses":[71],"verseLabel":"مريم: 71","question":"ما سرّ التعبير بـ﴿وَإِنْ مِنْكُمْ إِلَّا وَارِدُهَا﴾؟","answer":"تقرير حتمي لمشهد المرور أو الورود يملأ القلب خوفًا، ثم يميز الله المتقين بالنجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص432–438.","url":""}]},{"id":"s19-96","number":96,"surah":19,"verses":[72],"verseLabel":"مريم: 72","question":"ما سرّ التعبير بـ﴿وَنَذَرُ الظَّالِمِينَ فِيهَا جِثِيًّا﴾؟","answer":"بعد النجاة يبقون مطروحين على ركبهم، فلا خروج ولا قدرة على الوقوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص439–444.","url":""}]},{"id":"s19-97","number":97,"surah":19,"verses":[73],"verseLabel":"مريم: 73","question":"لماذا تفاخر الكافرون بـ﴿خَيْرٌ مَقَامًا وَأَحْسَنُ نَدِيًّا﴾؟","answer":"قاسوا الحق بزينة المجلس والمكانة الاجتماعية، مع أن ذلك متاع لا دليل رضا.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص445–451.","url":""}]},{"id":"s19-98","number":98,"surah":19,"verses":[74],"verseLabel":"مريم: 74","question":"ما سرّ التعبير بـ﴿أَحْسَنُ أَثَاثًا وَرِئْيًا﴾؟","answer":"جمع كثرة المتاع وحسن المنظر الذي يغري العين، ثم ذكّر بأمم كانت أجمل وأهلكت.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص452–459.","url":""}]},{"id":"s19-99","number":99,"surah":19,"verses":[75],"verseLabel":"مريم: 75","question":"ما سرّ التعبير بـ﴿فَلْيَمْدُدْ لَهُ الرَّحْمَنُ مَدًّا﴾؟","answer":"أمر تهديد: يمهله الرحمن في ضلاله حتى تنكشف له فجأة حقيقة ما وُعد.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص460–469.","url":""}]},{"id":"s19-100","number":100,"surah":19,"verses":[76],"verseLabel":"مريم: 76","question":"لماذا كانت الباقيات الصالحات ﴿خَيْرٌ ثَوَابًا وَخَيْرٌ مَرَدًّا﴾؟","answer":"هي خير فيما يعود على العامل الآن، وخير مرجعًا وعاقبة حين تزول الزينة.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص470–477.","url":""}]},{"id":"s19-101","number":101,"surah":19,"verses":[77],"verseLabel":"مريم: 77","question":"ما سرّ التعبير بـ﴿أَفَرَأَيْتَ الَّذِي كَفَرَ بِآيَاتِنَا﴾؟","answer":"الاستفهام يعجب من جرأته على الجمع بين الكفر والقطع بأنه سيؤتى مالًا وولدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص478–505.","url":""}]},{"id":"s19-102","number":102,"surah":19,"verses":[78],"verseLabel":"مريم: 78","question":"لماذا سأل ﴿أَطَّلَعَ الْغَيْبَ أَمِ اتَّخَذَ عِنْدَ الرَّحْمَنِ عَهْدًا﴾؟","answer":"حصر مستند دعواه في علم الغيب أو عهد من الله، وكلاهما معدوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص478–505.","url":""}]},{"id":"s19-103","number":103,"surah":19,"verses":[79],"verseLabel":"مريم: 79","question":"ما سرّ التعبير بـ﴿سَنَكْتُبُ مَا يَقُولُ﴾؟","answer":"يهدده بأن الكلمة العابرة محفوظة في سجل الجزاء، ثم يزيد له العذاب بدل المال.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص478–505.","url":""}]},{"id":"s19-104","number":104,"surah":19,"verses":[80],"verseLabel":"مريم: 80","question":"ما سرّ التعبير بـ﴿وَنَرِثُهُ مَا يَقُولُ﴾؟","answer":"ما ادعى ملكه يزول عنه ويبقى لله، ويأتي يوم القيامة منفردًا بلا مال ولا نصير.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص478–505.","url":""}]},{"id":"s19-105","number":105,"surah":19,"verses":[81,82],"verseLabel":"مريم: 81-82","question":"لماذا طلبوا من الآلهة ﴿عِزًّا﴾ ثم صارت عليهم ﴿ضِدًّا﴾؟","answer":"انقلب المأمول إلى نقيضه؛ تتبرأ المعبودات من عبادتهم وتخاصمهم بدل أن تنصرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص506–520.","url":""}]},{"id":"s19-106","number":106,"surah":19,"verses":[83],"verseLabel":"مريم: 83","question":"ما سرّ التعبير بـ﴿تَؤُزُّهُمْ أَزًّا﴾؟","answer":"الأز إزعاج وتحريك شديد؛ صور الشياطين تدفعهم إلى الشر دفعًا متتابعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص521–551.","url":""}]},{"id":"s19-107","number":107,"surah":19,"verses":[84],"verseLabel":"مريم: 84","question":"ما سرّ التعبير بـ﴿إِنَّمَا نَعُدُّ لَهُمْ عَدًّا﴾؟","answer":"كل يوم ونفس وخطوة محسوبة، فالإمهال المحدود ليس إهمالًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص521–551.","url":""}]},{"id":"s19-108","number":108,"surah":19,"verses":[85,86],"verseLabel":"مريم: 85-86","question":"لماذا يُحشر المتقون ﴿وَفْدًا﴾ والمجرمون ﴿وِرْدًا﴾؟","answer":"الوفد ضيوف مكرمون راكبون، والورد قطيع عطاش يساق إلى الماء؛ مقابلة تصور الكرامة والمهانة.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص521–551.","url":""}]},{"id":"s19-109","number":109,"surah":19,"verses":[87],"verseLabel":"مريم: 87","question":"لماذا قيد الشفاعة باتخاذ ﴿عِنْدَ الرَّحْمَنِ عَهْدًا﴾؟","answer":"قيدت الشفاعة بالعهد عند الرحمن؛ أي بالإيمان والتوحيد وما يأذن الله به، فنفى أن تملكها الآلهة أو تنال بمجرد الدعوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص521–551.","url":""}]},{"id":"s19-110","number":110,"surah":19,"verses":[88],"verseLabel":"مريم: 88","question":"لماذا عاد قولهم ﴿اتَّخَذَ الرَّحْمَنُ وَلَدًا﴾ بعد القصص؟","answer":"بعد بيان عبودية عيسى وسائر الأنبياء جاء الحكم الجامع الذي يهدم أصل دعوى البنوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص552–571.","url":""}]},{"id":"s19-111","number":111,"surah":19,"verses":[89],"verseLabel":"مريم: 89","question":"ما سرّ وصف قولهم بالولد بـ﴿شَيْئًا إِدًّا﴾؟","answer":"الإد الأمر الفظيع المنكر الذي يثقل سماعه، فناسب أثره الكوني في الآيات التالية.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص552–571.","url":""}]},{"id":"s19-112","number":112,"surah":19,"verses":[90],"verseLabel":"مريم: 90","question":"لماذا تكاد السماوات تتفطر والأرض تنشق والجبال تخر؟","answer":"جعل الكون كله يرتج من فظاعة نسبة الولد إلى الله، بينما يقوله الإنسان هينًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص552–571.","url":""}]},{"id":"s19-113","number":113,"surah":19,"verses":[92],"verseLabel":"مريم: 92","question":"ما سرّ التعبير بـ﴿وَمَا يَنْبَغِي لِلرَّحْمَنِ أَنْ يَتَّخِذَ وَلَدًا﴾؟","answer":"ينفي مجرد الملاءمة والإمكان اللائق بكماله؛ فالولد علامة حاجة ومماثلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص572–583.","url":""}]},{"id":"s19-114","number":114,"surah":19,"verses":[93],"verseLabel":"مريم: 93","question":"ما سرّ التعبير بـ﴿إِلَّا آتِي الرَّحْمَنِ عَبْدًا﴾؟","answer":"كل من في الكون يأتي مجردًا من دعاوى الملك والبنوة، ولا يبقى له إلا وصف العبودية.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص572–583.","url":""}]},{"id":"s19-115","number":115,"surah":19,"verses":[94],"verseLabel":"مريم: 94","question":"لماذا جمع ﴿أَحْصَاهُمْ وَعَدَّهُمْ عَدًّا﴾؟","answer":"الإحصاء إحاطة بأحوالهم، والعد ضبط لأفرادهم؛ فلا يغيب شخص ولا وصف.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص572–583.","url":""}]},{"id":"s19-116","number":116,"surah":19,"verses":[95],"verseLabel":"مريم: 95","question":"ما سرّ التعبير بـ﴿وَكُلُّهُمْ آتِيهِ يَوْمَ الْقِيَامَةِ فَرْدًا﴾؟","answer":"تسقط الروابط والجموع التي اغتر بها الإنسان ويقف كل واحد مسؤولًا وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص572–583.","url":""}]},{"id":"s19-117","number":117,"surah":19,"verses":[96],"verseLabel":"مريم: 96","question":"ما سرّ التعبير بـ﴿سَيَجْعَلُ لَهُمُ الرَّحْمَنُ وُدًّا﴾؟","answer":"الود محبة مستقرة يجعلها الله لهم في القلوب، جزاء الإيمان والعمل لا صناعة الدعاية.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص584–591.","url":""}]},{"id":"s19-118","number":118,"surah":19,"verses":[97],"verseLabel":"مريم: 97","question":"ما سرّ التعبير بـ﴿فَإِنَّمَا يَسَّرْنَاهُ بِلِسَانِكَ﴾؟","answer":"سهولة العربية على لسان الرسول وسيلة للبشارة والإنذار، فلا عذر في غموض البيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص592–601.","url":""}]},{"id":"s19-119","number":119,"surah":19,"verses":[98],"verseLabel":"مريم: 98","question":"لماذا ختمت السورة بـ﴿هَلْ تُحِسُّ مِنْهُمْ مِنْ أَحَدٍ أَوْ تَسْمَعُ لَهُمْ رِكْزًا﴾؟","answer":"حوّل الأمم المتجبرة إلى غياب كامل: لا شخص يُرى ولا أخفض صوت يُسمع.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص602–612.","url":""}]},{"id":"s20-1","number":1,"surah":20,"verses":[1],"verseLabel":"طه: 1","question":"لماذا افتتحت السورة بـ﴿طه﴾؟","answer":"﴿طه﴾ من الحروف المقطعة التي تعددت فيها الأقوال، ويُفوَّض مرادها التفصيلي إلى الله؛ ومن أشهر حكمها التنبيه إلى إعجاز القرآن المؤلف من حروف العرب.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص625–636.","url":""}]},{"id":"s20-2","number":2,"surah":20,"verses":[2],"verseLabel":"طه: 2","question":"ما سرّ التعبير بـ﴿مَا أَنْزَلْنَا عَلَيْكَ الْقُرْآنَ لِتَشْقَى﴾؟","answer":"نفى أن تكون ثمرة الوحي العنت؛ نزل للهداية والطمأنينة وإن احتاج حمله إلى مجاهدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص625–636.","url":""}]},{"id":"s20-3","number":3,"surah":20,"verses":[3],"verseLabel":"طه: 3","question":"ما سرّ التعبير بـ﴿إِلَّا تَذْكِرَةً لِمَنْ يَخْشَى﴾؟","answer":"الحصر يبين غايته، وخص من يخشى لأنه الذي تفتح الخشية قلبه للانتفاع.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص625–636.","url":""}]},{"id":"s20-4","number":4,"surah":20,"verses":[4],"verseLabel":"طه: 4","question":"ما دلالة وصف الله بـ﴿خَلَقَ الْأَرْضَ وَالسَّمَاوَاتِ الْعُلَا﴾؟","answer":"صل القرآن بخالق الكون ليعظم مصدره، وجمع الأرض الواحدة والسماوات المتعددة العالية.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص637–646.","url":""}]},{"id":"s20-5","number":5,"surah":20,"verses":[5],"verseLabel":"طه: 5","question":"ما سرّ التعبير بـ﴿الرَّحْمَنُ عَلَى الْعَرْشِ اسْتَوَى﴾؟","answer":"جمع اسم الرحمة بأعظم مظاهر الملك، فالسلطان المطلق جارٍ على الحكمة والرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص637–646.","url":""}]},{"id":"s20-6","number":6,"surah":20,"verses":[6],"verseLabel":"طه: 6","question":"لماذا جمع ﴿مَا فِي السَّمَاوَاتِ... وَمَا تَحْتَ الثَّرَى﴾؟","answer":"استوعب العلو والسفل وما بينهما وما خفي تحت التراب، فثبت عموم الملك.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص647–652.","url":""}]},{"id":"s20-7","number":7,"surah":20,"verses":[7],"verseLabel":"طه: 7","question":"لماذا يعلم الله ﴿السِّرَّ وَأَخْفَى﴾؟","answer":"ذُكرت في ﴿السر وأخفى﴾ أقوال؛ فالسر ما أخفاه العبد، والأخفى ما لم يحدث به نفسه بعد أو ما هو أخفى من السر، والمقصود إحاطة علم الله بدرجات الخفاء كلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص653–660.","url":""}]},{"id":"s20-8","number":8,"surah":20,"verses":[8],"verseLabel":"طه: 8","question":"ما سرّ التعبير بـ﴿لَهُ الْأَسْمَاءُ الْحُسْنَى﴾؟","answer":"تقديم «له» للاختصاص، والحسنى تدل أن أسماءه بلغت الغاية في الكمال.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص661–666.","url":""}]},{"id":"s20-9","number":9,"surah":20,"verses":[9],"verseLabel":"طه: 9","question":"لماذا انتقل بقوله ﴿وَهَلْ أَتَاكَ حَدِيثُ مُوسَى﴾؟","answer":"الاستفهام في ﴿وهل أتاك﴾ للتشويق والتنبيه إلى عظم الخبر، وفي سوق قصة موسى تسلية للنبي وتثبيت له بما آل إليه أمر الرسول مع الطاغية.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص667–684.","url":""}]},{"id":"s20-10","number":10,"surah":20,"verses":[10],"verseLabel":"طه: 10","question":"ما سرّ التعبير في قول موسى بـ﴿آنَسْتُ نَارًا﴾ لا «رأيت»؟","answer":"الإيناس رؤية مع طمأنينة؛ وجد في النار أمل الدفء والدلالة بعد وحشة الطريق.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص667–684.","url":""}]},{"id":"s20-11","number":11,"surah":20,"verses":[10],"verseLabel":"طه: 10","question":"ما سرّ التعبير في طه بـ﴿لَعَلِّي آتِيكُمْ مِنْهَا بِقَبَسٍ أَوْ أَجِدُ عَلَى النَّارِ هُدًى﴾، واختلف اللفظ في النمل والقصص؟","answer":"طه فصلت مشهد الرؤية والمكث، والنمل أجملته، والقصص زادت سياق السفر؛ فاختار كل موضع قدر القصة وغرضها.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص667–684.","url":""}]},{"id":"s20-12","number":12,"surah":20,"verses":[11],"verseLabel":"طه: 11","question":"ما سرّ التعبير بـ﴿فَلَمَّا أَتَاهَا نُودِيَ يَا مُوسَى﴾؟","answer":"الفاء تجعل بلوغه النار بابًا فوريًا إلى النداء الذي غيّر مسار حياته.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص685–692.","url":""}]},{"id":"s20-13","number":13,"surah":20,"verses":[12],"verseLabel":"طه: 12","question":"لماذا أُمر بخلع نعليه في الوادي المقدس؟","answer":"الأمر بخلع النعلين لتعظيم الوادي المقدس والتأهب للمناجاة وإظهار التواضع في مقام الاصطفاء؛ وقد ذكرت في مادته أقوال أخرى لا يثبت بها تعليل واحد حصرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص685–692.","url":""}]},{"id":"s20-14","number":14,"surah":20,"verses":[12],"verseLabel":"طه: 12","question":"لماذا سمي الوادي ﴿طُوًى﴾ و﴿الْمُقَدَّسِ﴾؟","answer":"ذكر الاسم يثبت المكان، ووصف القداسة يبين سبب الأدب والأمر بخلع النعلين.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص685–692.","url":""}]},{"id":"s20-15","number":15,"surah":20,"verses":[13],"verseLabel":"طه: 13","question":"ما سرّ التعبير بـ﴿وَأَنَا اخْتَرْتُكَ فَاسْتَمِعْ لِمَا يُوحَى﴾؟","answer":"الاختيار يسبق التكليف ويمنحه اليقين، والفاء تجعل الإصغاء أول مقتضيات الاصطفاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص693–700.","url":""}]},{"id":"s20-16","number":16,"surah":20,"verses":[14],"verseLabel":"طه: 14","question":"لماذا اجتمع ﴿إِنَّنِي أَنَا اللَّهُ لَا إِلَهَ إِلَّا أَنَا﴾ بهذه المؤكدات؟","answer":"ليكون أول الوحي يقينًا قاطعًا بهوية المتكلم ووحدانيته، قبل الأمر بالعبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص701–712.","url":""}]},{"id":"s20-17","number":17,"surah":20,"verses":[14],"verseLabel":"طه: 14","question":"ما سرّ التعبير بـ﴿وَأَقِمِ الصَّلَاةَ لِذِكْرِي﴾؟","answer":"الصلاة أخص صورة عملية لاستدامة ذكر الله، فلا يبقى التوحيد معرفة مجردة.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص701–712.","url":""}]},{"id":"s20-18","number":18,"surah":20,"verses":[15],"verseLabel":"طه: 15","question":"ما سرّ التعبير عن الساعة بـ﴿أَكَادُ أُخْفِيهَا﴾؟","answer":"بالغ التعبير في ستر وقت الساعة حتى جرى على أسلوب العرب في قولهم: أخفيت السر من نفسي؛ والمقصود غاية الإخفاء ليظل التكليف والاستعداد قائمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص713–723.","url":""}]},{"id":"s20-19","number":19,"surah":20,"verses":[16],"verseLabel":"طه: 16","question":"ما سرّ التعبير بـ﴿فَلَا يَصُدَّنَّكَ عَنْهَا مَنْ لَا يُؤْمِنُ بِهَا﴾؟","answer":"نهى عن أثر ضغط المنكرين وإن كان موسى مؤمنًا؛ فالثبات يحتاج حذرًا من بيئة الغفلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص724–732.","url":""}]},{"id":"s20-20","number":20,"surah":20,"verses":[17],"verseLabel":"طه: 17","question":"لماذا سأل الله موسى ﴿وَمَا تِلْكَ بِيَمِينِكَ﴾ وهو يعلم؟","answer":"ليؤنسه بالمحادثة، ويلفت نظره إلى عصاه المألوفة قبل أن يريه انقلابها آية.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص733–744.","url":""}]},{"id":"s20-21","number":21,"surah":20,"verses":[18],"verseLabel":"طه: 18","question":"لماذا أطال موسى جواب العصا؟","answer":"زاد موسى في الجواب على تسمية العصا فذكر منافعها؛ إيناسًا بالمناجاة واغتنامًا لمقام الخطاب، ولإظهار كونها عصًا مألوفة قبل انقلابها آية.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص733–744.","url":""}]},{"id":"s20-22","number":22,"surah":20,"verses":[18],"verseLabel":"طه: 18","question":"ما معنى ﴿وَأَهُشُّ بِهَا عَلَى غَنَمِي﴾؟","answer":"أضرب بها ورق الشجر ليسقط للغنم؛ صورة لحياة الراعي الهادئة قبل الرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص733–744.","url":""}]},{"id":"s20-23","number":23,"surah":20,"verses":[20],"verseLabel":"طه: 20","question":"لماذا صارت العصا ﴿حَيَّةً تَسْعَى﴾؟","answer":"جاءت ﴿حية تسعى﴾ لإثبات الحياة والحركة المشاهدة، لا مجرد صورة الحية؛ فظهر انقلاب العصا انقلابًا حقيقيًا بقدرة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص745–757.","url":""}]},{"id":"s20-24","number":24,"surah":20,"verses":[21],"verseLabel":"طه: 21","question":"ما سرّ التعبير بـ﴿سَنُعِيدُهَا سِيرَتَهَا الْأُولَى﴾؟","answer":"طمأنه بأن انقلابها لا يخرجها عن سلطان الله؛ تعود إلى هيئتها المألوفة فورًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص745–757.","url":""}]},{"id":"s20-25","number":25,"surah":20,"verses":[22],"verseLabel":"طه: 22","question":"ما سرّ وصف اليد بأنها تخرج ﴿بَيْضَاءَ مِنْ غَيْرِ سُوءٍ﴾؟","answer":"دفع توهم البرص والمرض؛ البياض نور معجز لا عيب جسدي.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص758–769.","url":""}]},{"id":"s20-26","number":26,"surah":20,"verses":[23],"verseLabel":"طه: 23","question":"ما سرّ التعبير بـ﴿لِنُرِيَكَ مِنْ آيَاتِنَا الْكُبْرَى﴾؟","answer":"تفيد ﴿من﴾ أن العصا واليد بعض آيات الله الكبرى، وأن المقصود إراءة موسى نماذج عظيمة من دلائل القدرة قبل إرساله إلى فرعون.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص758–769.","url":""}]},{"id":"s20-27","number":27,"surah":20,"verses":[24],"verseLabel":"طه: 24","question":"لماذا اختصر مهمة موسى في ﴿اذْهَبْ إِلَى فِرْعَوْنَ إِنَّهُ طَغَى﴾؟","answer":"سمّى الهدف وعلته في جملة حاسمة؛ الطغيان بلغ حدًا يستدعي الرسالة والمواجهة.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص770–774.","url":""}]},{"id":"s20-28","number":28,"surah":20,"verses":[25],"verseLabel":"طه: 25","question":"لماذا بدأ موسى دعاءه بـ﴿رَبِّ اشْرَحْ لِي صَدْرِي﴾؟","answer":"طلب سعة القلب قبل فصاحة اللسان؛ حمل الرسالة يبدأ بطمأنينة الداخل.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص775–785.","url":""}]},{"id":"s20-29","number":29,"surah":20,"verses":[26],"verseLabel":"طه: 26","question":"ما سرّ التعبير بـ﴿وَيَسِّرْ لِي أَمْرِي﴾ ولم يطلب زوال فرعون؟","answer":"سأل تيسير أمر الرسالة وتسهيل ما كُلّف به؛ اعترافًا بأن المهمة لا تتم إلا بمعونة الله، لا طلبًا لإسقاط التكليف.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص775–785.","url":""}]},{"id":"s20-30","number":30,"surah":20,"verses":[27,28],"verseLabel":"طه: 27-28","question":"ما سرّ التعبير بـ﴿وَاحْلُلْ عُقْدَةً مِنْ لِسَانِي يَفْقَهُوا قَوْلِي﴾؟","answer":"لم يطلب البلاغة للزينة، بل القدر الذي يحقق فهم الرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص775–785.","url":""}]},{"id":"s20-31","number":31,"surah":20,"verses":[29,30,31,32],"verseLabel":"طه: 29-32","question":"لماذا طلب هارون وزيرًا من أهله؟","answer":"طلب هارون وزيرًا من أهله ليقوي به ظهره ويشاركه أمر الدعوة؛ وخص الأخ لأن قرابته ونصحه يجعلان مؤازرته أوثق.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص786–795.","url":""}]},{"id":"s20-32","number":32,"surah":20,"verses":[33,34],"verseLabel":"طه: 33-34","question":"لماذا جعل غاية المعونة ﴿كَيْ نُسَبِّحَكَ كَثِيرًا وَنَذْكُرَكَ كَثِيرًا﴾؟","answer":"جعل ثمرة المعونة كثرة التسبيح والذكر؛ فبالمشاركة يقويان على العبادة وأداء الرسالة، وكرر ﴿كثيرًا﴾ تعظيمًا لاستمرار الذكر وتجددِه.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص796–799.","url":""}]},{"id":"s20-33","number":33,"surah":20,"verses":[35],"verseLabel":"طه: 35","question":"ما سرّ التعبير بـ﴿إِنَّكَ كُنْتَ بِنَا بَصِيرًا﴾ وقدم ﴿بنا﴾؟","answer":"قُدم ﴿بنا﴾ للاهتمام والعناية بحالهما، ودل ﴿كنت﴾ على دوام علم الله وإحاطة بصره بأفعالهما؛ وجاء ﴿بصيرًا﴾ مناسبًا لمقام المراقبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص799–801.","url":""}]},{"id":"s20-34","number":34,"surah":20,"verses":[36],"verseLabel":"طه: 36","question":"لماذا جاء الجواب ﴿قَدْ أُوتِيتَ سُؤْلَكَ يَا مُوسَى﴾ لا «أوتيت ما سألت»؟","answer":"عُدل عن «أوتيت ما سألت» إلى ﴿أوتيت سؤلك﴾ لتجتمع مطالبه في اسم واحد دال على تمام الإجابة، وجاء الماضي و﴿قد﴾ لتحقيق حصولها.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص11–13.","url":""}]},{"id":"s20-35","number":35,"surah":20,"verses":[37],"verseLabel":"طه: 37","question":"لماذا ذكّره الله بمنته عليه ﴿مَرَّةً أُخْرَى﴾؟","answer":"ذكّره بالمنة السابقة إجمالًا ثم فصّلها؛ ليقوى يقينه بأن من حفظه ورباه من قبل سيعينه في الرسالة إلى فرعون.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص14–16.","url":""}]},{"id":"s20-36","number":36,"surah":20,"verses":[38],"verseLabel":"طه: 38","question":"لماذا سمي الإلهام لأم موسى ﴿وَحْيًا﴾؟","answer":"لأنه إعلام خفي سريع ألقي في قلبها يقينًا، لا وحي نبوة وتشريع.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص19–26.","url":""}]},{"id":"s20-37","number":37,"surah":20,"verses":[39],"verseLabel":"طه: 39","question":"لماذا جُمعت الأوامر المتضادة: ﴿اقْذِفِيهِ فِي التَّابُوتِ فَاقْذِفِيهِ فِي الْيَمِّ﴾؟","answer":"تكرر فعل القذف في مرحلتين: وضع موسى في التابوت، ثم إلقاء التابوت في اليم؛ ودلت الفاء على سرعة الترتيب، واختيار القذف على قوة الفعل مع تسليم الأمر لعناية الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص30–34.","url":""}]},{"id":"s20-38","number":38,"surah":20,"verses":[39],"verseLabel":"طه: 39","question":"ما سرّ التعبير بـ﴿وَأَلْقَيْتُ عَلَيْكَ مَحَبَّةً مِنِّي﴾؟","answer":"جعل في القلوب قبولًا له يحميه داخل بيت عدوه، وهي محبة منشؤها الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص27–50.","url":""}]},{"id":"s20-39","number":39,"surah":20,"verses":[40],"verseLabel":"طه: 40","question":"ما سرّ التعبير بـ﴿فَرَجَعْنَاكَ إِلَى أُمِّكَ كَيْ تَقَرَّ عَيْنُهَا﴾؟","answer":"نسب الرجوع إلى تدبيره وأظهر غايته النفسية؛ لم يحفظ الطفل فقط بل جبر قلب الأم.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص51–82.","url":""}]},{"id":"s20-40","number":40,"surah":20,"verses":[41],"verseLabel":"طه: 41","question":"ما سرّ التعبير بـ﴿وَاصْطَنَعْتُكَ لِنَفْسِي﴾؟","answer":"الاصطناع إعداد متدرج بعناية لمهمة خاصة، و«لنفسي» غاية التشريف والإخلاص.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص83–86.","url":""}]},{"id":"s20-41","number":41,"surah":20,"verses":[42],"verseLabel":"طه: 42","question":"ما سرّ التعبير بـ﴿وَلَا تَنِيَا فِي ذِكْرِي﴾؟","answer":"الوني الفتور؛ فنهاهما عن ضعف الذكر لأن مواجهة الطغيان تستمد قوتها منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص87–93.","url":""}]},{"id":"s20-42","number":42,"surah":20,"verses":[43,44],"verseLabel":"طه: 43-44","question":"لماذا أُمر موسى وهارون بالقول اللين لفرعون؟","answer":"لإقامة الحجة بأحسن أسلوب، وإثبات أن شدة باطله لا تبرر فظاظة الدعوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص94–99.","url":""}]},{"id":"s20-43","number":43,"surah":20,"verses":[44],"verseLabel":"طه: 44","question":"ما سرّ التعبير بـ﴿لَعَلَّهُ يَتَذَكَّرُ أَوْ يَخْشَى﴾؟","answer":"الترجي في ﴿لعله﴾ راجع إلى ما يظهر للمخاطَبَيْن من رجاء انتفاع فرعون بالتذكير أو الخشية، لا إلى تردد في علم الله؛ وفيه إبقاء باب الدعوة مفتوحًا مع الطاغية.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص100–108.","url":""}]},{"id":"s20-44","number":44,"surah":20,"verses":[45],"verseLabel":"طه: 45","question":"ما سرّ التعبير في قولهما ﴿إِنَّنَا نَخَافُ أَنْ يَفْرُطَ عَلَيْنَا أَوْ أَنْ يَطْغَى﴾؟","answer":"أظهرا الخوف البشري الطبيعي من المبادرة بالأذى أو الزيادة فيه، فكان الجواب بالمعية.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص109–114.","url":""}]},{"id":"s20-45","number":45,"surah":20,"verses":[46],"verseLabel":"طه: 46","question":"ما سرّ التعبير بـ﴿إِنَّنِي مَعَكُمَا أَسْمَعُ وَأَرَى﴾؟","answer":"خص السمع لأقوال المواجهة والبصر لأفعالها، والمعية تمنحهما الحفظ والثبات.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص115–120.","url":""}]},{"id":"s20-46","number":46,"surah":20,"verses":[47],"verseLabel":"طه: 47","question":"ما سرّ التعبير في قولهما لفرعون ﴿وَالسَّلَامُ عَلَى مَنِ اتَّبَعَ الْهُدَى﴾؟","answer":"سلام مشروط بالهداية، لا تحية ولاء للطاغية؛ يجمع اللين والوضوح.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص121–140.","url":""}]},{"id":"s20-47","number":47,"surah":20,"verses":[49],"verseLabel":"طه: 49","question":"لماذا سأل فرعون ﴿فَمَنْ رَبُّكُمَا يَا مُوسَى﴾ وأفرد الخطاب في النداء؟","answer":"سأل فرعون بـ﴿فمن ربكما﴾ سؤال إنكار واستهزاء، معرضًا عن مضمون الرسالة إلى الاستفهام عن المرسِل؛ فأجابه موسى بتعريف الرب من طريق الخلق والهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص147–151.","url":""}]},{"id":"s20-48","number":48,"surah":20,"verses":[50],"verseLabel":"طه: 50","question":"لماذا عرّف موسى ربه بأنه ﴿أَعْطَى كُلَّ شَيْءٍ خَلْقَهُ ثُمَّ هَدَى﴾؟","answer":"جمع إتقان التكوين وهداية كل مخلوق لوظيفته؛ تعريف بالآثار التي لا يستطيع فرعون ادعاءها.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص152–160.","url":""}]},{"id":"s20-49","number":49,"surah":20,"verses":[51],"verseLabel":"طه: 51","question":"لماذا نقل فرعون الحوار إلى ﴿فَمَا بَالُ الْقُرُونِ الْأُولَى﴾؟","answer":"رد موسى العلم التفصيلي بأحوال القرون إلى الله، ولم ينجرّ إلى صرف المقام عن إقامة الدليل على ربوبية الله؛ فجمع الجواب الأدب والاقتصار على ما يفيد الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص161–165.","url":""}]},{"id":"s20-50","number":50,"surah":20,"verses":[52],"verseLabel":"طه: 52","question":"ما سرّ التعبير في قول موسى ﴿عِلْمُهَا عِنْدَ رَبِّي فِي كِتَابٍ﴾؟","answer":"فوّض تفاصيل حسابهم إلى علم محفوظ، ثم عاد إلى أصل الدعوة دون استطراد.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص166–175.","url":""}]},{"id":"s20-51","number":51,"surah":20,"verses":[52],"verseLabel":"طه: 52","question":"لماذا جمع ﴿لَا يَضِلُّ رَبِّي وَلَا يَنْسَى﴾؟","answer":"نفى خطأ العلم ابتداءً وذهاب المعلوم بعد حصوله، فاستوعب كمال الحفظ.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص166–175.","url":""}]},{"id":"s20-52","number":52,"surah":20,"verses":[53],"verseLabel":"طه: 53","question":"ما سرّ وصف الأرض بـ﴿مَهْدًا﴾؟","answer":"شبّهها بمهد الطفل المهيأ للسكون والحياة، فاستحضر نعمة التهيئة لا مجرد الخلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص176–190.","url":""}]},{"id":"s20-53","number":53,"surah":20,"verses":[54],"verseLabel":"طه: 54","question":"لماذا ختم دلائل النبات بـ﴿لِأُولِي النُّهَى﴾؟","answer":"النهى عقول تنهى أصحابها عن الباطل؛ فالمشهد يحتاج عقلًا ينتقل من النعمة إلى المنعم.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص191–197.","url":""}]},{"id":"s20-54","number":54,"surah":20,"verses":[55],"verseLabel":"طه: 55","question":"لماذا جمع ﴿مِنْهَا خَلَقْنَاكُمْ وَفِيهَا نُعِيدُكُمْ وَمِنْهَا نُخْرِجُكُمْ﴾؟","answer":"دورة واحدة من الأرض وإليها ومنها، تجعل البعث امتدادًا للخلق لا أمرًا مستبعدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص198–203.","url":""}]},{"id":"s20-55","number":55,"surah":20,"verses":[56],"verseLabel":"طه: 56","question":"ما سرّ التعبير بـ﴿وَلَقَدْ أَرَيْنَاهُ آيَاتِنَا كُلَّهَا﴾؟","answer":"المقصود أنه أُري الحجج والآيات التي أقام الله بها الحجة عليه في هذا المقام، فجمعها النص بـ﴿آياتنا كلها﴾ دلالة على استيفاء البيان، لا على أن فرعون شاهد كل آية لله على الإطلاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص204–212.","url":""}]},{"id":"s20-56","number":56,"surah":20,"verses":[57],"verseLabel":"طه: 57","question":"ما سرّ تعبير فرعون عن إخراجهم من مصر بـ﴿بِسِحْرِكَ﴾؟","answer":"حوّل قضية الربوبية إلى تهديد سياسي للأرض، ليحشد الجمهور بالخوف على المصالح.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص213–227.","url":""}]},{"id":"s20-57","number":57,"surah":20,"verses":[58],"verseLabel":"طه: 58","question":"ما سرّ التعبير بـ﴿فَاجْعَلْ بَيْنَنَا وَبَيْنَكَ مَوْعِدًا﴾؟","answer":"طلب فرعون موعدًا معلومًا لا يخلفه واحد من الفريقين، ومكانًا مستويًا أو متوسطًا ظاهرًا؛ ليقع اللقاء على علم ومشاهدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص213–227.","url":""}]},{"id":"s20-58","number":58,"surah":20,"verses":[59],"verseLabel":"طه: 59","question":"لماذا اختار موسى ﴿يَوْمُ الزِّينَةِ وَأَنْ يُحْشَرَ النَّاسُ ضُحًى﴾؟","answer":"اختار موسى يوم الزينة لأنه يوم اجتماع الناس، وحدد وقت الضحى لظهور الأمر ووضوح المشاهدة؛ فتقوم الحجة علنًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص228–235.","url":""}]},{"id":"s20-59","number":59,"surah":20,"verses":[60],"verseLabel":"طه: 60","question":"ما سرّ التعبير بـ﴿فَتَوَلَّى فِرْعَوْنُ فَجَمَعَ كَيْدَهُ ثُمَّ أَتَى﴾؟","answer":"اختصر كل إعداد السلطة والسحرة في «كيده»، ثم صوّر مجيئه بعد الاستنفار الكامل.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص236–246.","url":""}]},{"id":"s20-60","number":60,"surah":20,"verses":[61],"verseLabel":"طه: 61","question":"لماذا بدأ موسى السحرة بقوله ﴿وَيْلَكُمْ لَا تَفْتَرُوا عَلَى اللَّهِ كَذِبًا﴾؟","answer":"حذرهم أخلاقيًا قبل المنافسة، فالمعركة ليست مهارة سحر بل نسبة الباطل إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص236–246.","url":""}]},{"id":"s20-61","number":61,"surah":20,"verses":[62],"verseLabel":"طه: 62","question":"لماذا تنازع السحرة أمرهم ﴿وَأَسَرُّوا النَّجْوَى﴾؟","answer":"دل التنازع على اختلاف السحرة وتشاورهم في أمر موسى، و﴿أسروا النجوى﴾ على إخفاء ما تداولوه؛ فجمع السياق اضطراب الرأي وكتمان الحديث.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص247–253.","url":""}]},{"id":"s20-62","number":62,"surah":20,"verses":[63],"verseLabel":"طه: 63","question":"ما سرّ قولهم ﴿إِنْ هَذَانِ لَسَاحِرَانِ﴾؟","answer":"﴿إن هذان لساحران﴾ قراءة متواترة لا مطعن فيها، ووجّهها علماء العربية بوجوه معتبرة، منها إجراء المثنى بالألف في الأحوال كلها، ومنها تخريجات نحوية أخرى؛ فلا يصح حصرها في وجه واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص254–267.","url":""}]},{"id":"s20-63","number":63,"surah":20,"verses":[64],"verseLabel":"طه: 64","question":"ما سرّ التعبير بـ﴿فَأَجْمِعُوا كَيْدَكُمْ ثُمَّ ائْتُوا صَفًّا﴾؟","answer":"أمروا بتوحيد الخطة والظهور كتلة واحدة؛ صورة للقوة المصنوعة قبل انهيارها.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص254–267.","url":""}]},{"id":"s20-64","number":64,"surah":20,"verses":[65],"verseLabel":"طه: 65","question":"لماذا خيّروا موسى بين أن يلقي أو يكونوا أول من ألقى؟","answer":"أظهروا ثقة المتحدي، فاختار أن يري الناس أقصى ما عندهم قبل ظهور الآية.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص268–280.","url":""}]},{"id":"s20-65","number":65,"surah":20,"verses":[66],"verseLabel":"طه: 66","question":"لماذا خُيّل إليه أن حبالهم وعصيهم ﴿تَسْعَى﴾؟","answer":"جاء ﴿يخيل إليه﴾ مبنيًا للمجهول لأن المقصود تصوير أثر السحر الواقع في الإدراك، لا إثبات انقلاب حقيقي للحبال والعصي؛ ثم صرح بقوله ﴿من سحرهم﴾ بسبب هذا التخييل.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص268–280.","url":""}]},{"id":"s20-66","number":66,"surah":20,"verses":[67],"verseLabel":"طه: 67","question":"لماذا أوجس موسى ﴿فِي نَفْسِهِ خِيفَةً﴾؟","answer":"كانت خيفة موسى خيفة بشرية عارضة مما ظهر من السحر، وقيل: خاف أن يلتبس الأمر على الناس؛ فأعقبتها الطمأنة الإلهية فورًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص281–292.","url":""}]},{"id":"s20-67","number":67,"surah":20,"verses":[68],"verseLabel":"طه: 68","question":"لماذا كان التثبيت ﴿إِنَّكَ أَنْتَ الْأَعْلَى﴾؟","answer":"ضمير الفصل والتعريف يحصران العلو الحقيقي فيه في ذلك الموقف مهما بدا السحر ضخمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص281–292.","url":""}]},{"id":"s20-68","number":68,"surah":20,"verses":[69],"verseLabel":"طه: 69","question":"ما سرّ التعبير بـ﴿تَلْقَفْ مَا صَنَعُوا﴾ لا «عصيهم»؟","answer":"عبّر بـ﴿ما صنعوا﴾ لأن المراد إبطال حاصل صناعتهم السحرية وكيدهم، لا مجرد ابتلاع أعيان الحبال والعصي؛ ثم بيّن أنه كيد ساحر.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص293–303.","url":""}]},{"id":"s20-69","number":69,"surah":20,"verses":[69],"verseLabel":"طه: 69","question":"ما سرّ التعبير بـ﴿وَلَا يُفْلِحُ السَّاحِرُ حَيْثُ أَتَى﴾؟","answer":"عمم نفي الفلاح في كل طريق ومكان، فالنصر الظاهر لا ينقلب فلاحًا حقيقيًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص293–303.","url":""}]},{"id":"s20-70","number":70,"surah":20,"verses":[70],"verseLabel":"طه: 70","question":"ما سرّ التعبير بـ﴿فَأُلْقِيَ السَّحَرَةُ سُجَّدًا﴾ لا «فسجدوا»؟","answer":"صور سرعة سقوطهم وقوة الحق كأن قوة ألقتهم إلى الأرض بلا تردد.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص304–311.","url":""}]},{"id":"s20-71","number":71,"surah":20,"verses":[71],"verseLabel":"طه: 71","question":"ما سرّ التعبير بـفرعون ﴿إِنَّهُ لَكَبِيرُكُمُ الَّذِي عَلَّمَكُمُ السِّحْرَ﴾؟","answer":"وصف فرعون موسى بأنه ﴿كبيركم﴾ افتراءً؛ ليوهم أن إيمان السحرة مؤامرة مدبرة، فيدفع عن نفسه دلالة المعجزة التي ألزمتهم السجود.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص312–327.","url":""}]},{"id":"s20-72","number":72,"surah":20,"verses":[72],"verseLabel":"طه: 72","question":"ما سرّ التعبير بـالسحرة ﴿لَنْ نُؤْثِرَكَ عَلَى مَا جَاءَنَا مِنَ الْبَيِّنَاتِ﴾؟","answer":"انتقلوا من خدمة فرعون إلى يقين لا يساوم؛ ما شاهدوه أصدق من سلطانه ووعيده.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص328–338.","url":""}]},{"id":"s20-73","number":73,"surah":20,"verses":[72],"verseLabel":"طه: 72","question":"ما سرّ قولهم ﴿فَاقْضِ مَا أَنْتَ قَاضٍ﴾؟","answer":"حصروا قدرته في الدنيا القصيرة، وأظهروا أن حكمه لا يصل إلى إيمان القلب والآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص328–338.","url":""}]},{"id":"s20-74","number":74,"surah":20,"verses":[73],"verseLabel":"طه: 73","question":"ما دلالة تقديمهم المغفرة على الإكراه: ﴿لِيَغْفِرَ لَنَا خَطَايَانَا وَمَا أَكْرَهْتَنَا عَلَيْهِ﴾؟","answer":"قدموا طلب مغفرة الخطايا لأنها عامة، ثم عطفوا ما أكرههم عليه فرعون من السحر لعظم موقعه في ذلك المقام؛ فلا يدل العطف على إسقاط تبعتهم عن سائر أفعالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص339–345.","url":""}]},{"id":"s20-75","number":75,"surah":20,"verses":[73],"verseLabel":"طه: 73","question":"لماذا ختموا بـ﴿وَاللَّهُ خَيْرٌ وَأَبْقَى﴾؟","answer":"قابلوا ثواب الله وسلطانه بملك فرعون العابر؛ الخير الحقيقي ما جمع الكمال والدوام.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص339–345.","url":""}]},{"id":"s20-76","number":76,"surah":20,"verses":[74],"verseLabel":"طه: 74","question":"ما سرّ التعبير بـ﴿لَا يَمُوتُ فِيهَا وَلَا يَحْيَى﴾؟","answer":"ليست راحة الموت ولا حياة ينتفع بها، بل حالة عذاب مستمرة بينهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص346–356.","url":""}]},{"id":"s20-77","number":77,"surah":20,"verses":[75],"verseLabel":"طه: 75","question":"ما سرّ التعبير بـ﴿قَدْ عَمِلَ الصَّالِحَاتِ﴾ بعد الإيمان؟","answer":"الإيمان أصل الدخول، والعمل شاهد صدقه وسبب الدرجات العلى.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص346–356.","url":""}]},{"id":"s20-78","number":78,"surah":20,"verses":[77],"verseLabel":"طه: 77","question":"ما سرّ وصف الطريق في البحر بـ﴿يَبَسًا﴾؟","answer":"وُصف الطريق في البحر بـ﴿يبسًا﴾ ليدل على أنه صار يابسًا صالحًا للسلوك، مع أن موضعه بحر؛ فاجتمعت سلامة الطريق وظهور القدرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص361–388.","url":""}]},{"id":"s20-79","number":79,"surah":20,"verses":[77],"verseLabel":"طه: 77","question":"ما سرّ التعبير بـ﴿لَا تَخَافُ دَرَكًا وَلَا تَخْشَى﴾؟","answer":"﴿لا تخاف دركًا﴾ أمان من أن يلحقهم فرعون من خلفهم، و﴿لا تخشى﴾ أمان من الغرق أو من سائر المخاوف في البحر؛ فجمع نفي ملاحقة العدو ونفي خطر الطريق.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص361–388.","url":""}]},{"id":"s20-80","number":80,"surah":20,"verses":[78],"verseLabel":"طه: 78","question":"ما سرّ التعبير بـ﴿فَغَشِيَهُمْ مِنَ الْيَمِّ مَا غَشِيَهُمْ﴾؟","answer":"الإبهام يهول مقدار ما غمرهم؛ ما وقع أعظم من أن يحتاج إلى تفصيل.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص361–388.","url":""}]},{"id":"s20-81","number":81,"surah":20,"verses":[79],"verseLabel":"طه: 79","question":"ما سرّ التعبير بـ﴿وَأَضَلَّ فِرْعَوْنُ قَوْمَهُ وَمَا هَدَى﴾؟","answer":"جمع إثبات الإضلال ونفي أي هداية، ردًا على قوله لهم إنه يهديهم سبيل الرشاد.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص361–388.","url":""}]},{"id":"s20-82","number":82,"surah":20,"verses":[80],"verseLabel":"طه: 80","question":"ما سرّ التعبير بقوله تعالى: ﴿وَوَاعَدْنَاكُمْ جَانِبَ الطُّورِ الْأَيْمَنَ﴾؟","answer":"ذكّرهم بمكان التكريم والوحي بعد النجاة، تمهيدًا لتقبيح انقلابهم إلى العجل.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص389–413.","url":""}]},{"id":"s20-83","number":83,"surah":20,"verses":[81],"verseLabel":"طه: 81","question":"ما سرّ التعبير بـ﴿وَلَا تَطْغَوْا فِيهِ فَيَحِلَّ عَلَيْكُمْ غَضَبِي﴾؟","answer":"جعل الطغيان في النعمة سببًا لحلول الغضب، فالمنّ لا يحمي من كفرانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص389–413.","url":""}]},{"id":"s20-84","number":84,"surah":20,"verses":[82],"verseLabel":"طه: 82","question":"ما سرّ التعبير بـ﴿وَإِنِّي لَغَفَّارٌ﴾ بصيغة المبالغة؟","answer":"فتح بعد الوعيد بابًا واسعًا لمن جمع التوبة والإيمان والعمل ثم استقام على الهدى.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص389–413.","url":""}]},{"id":"s20-85","number":85,"surah":20,"verses":[83],"verseLabel":"طه: 83","question":"لماذا سأل الله موسى ﴿وَمَا أَعْجَلَكَ عَنْ قَوْمِكَ﴾؟","answer":"الاستفهام في ﴿وما أعجلك عن قومك﴾ للعتاب والتعليم؛ لأن موسى تقدم قومه شوقًا إلى ميقات ربه، فنبّهه إلى ما ترتب في غيبته.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص414–430.","url":""}]},{"id":"s20-86","number":86,"surah":20,"verses":[84],"verseLabel":"طه: 84","question":"ما سرّ التعبير في قول موسى ﴿وَعَجِلْتُ إِلَيْكَ رَبِّ لِتَرْضَى﴾؟","answer":"كشف باعث العجلة الصالح، فكان الخطأ في التقدير لا في القصد.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص414–430.","url":""}]},{"id":"s20-87","number":87,"surah":20,"verses":[85],"verseLabel":"طه: 85","question":"ما سرّ التعبير عن صنع العجل بـ﴿فَتَنَّا قَوْمَكَ﴾؟","answer":"كان اختبارًا كشف ما في القلوب بعد غياب القائد، لا مجرد حادث صناعي.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص414–430.","url":""}]},{"id":"s20-88","number":88,"surah":20,"verses":[86],"verseLabel":"طه: 86","question":"لماذا رجع موسى ﴿غَضْبَانَ أَسِفًا﴾؟","answer":"الغضب للحق، والأسف حزن على سقوط قومه؛ فجمع قوة الإنكار وألم الرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص431–447.","url":""}]},{"id":"s20-89","number":89,"surah":20,"verses":[87],"verseLabel":"طه: 87","question":"ما سرّ قولهم ﴿حُمِّلْنَا أَوْزَارًا مِنْ زِينَةِ الْقَوْمِ﴾؟","answer":"سموا الحلي ﴿أوزارًا﴾ لما فيها من ثقل وتبعة، وعبّروا بـ﴿حُمّلنا﴾ على وجه الاعتذار؛ ثم ذكروا قذفها في النار.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص448–458.","url":""}]},{"id":"s20-90","number":90,"surah":20,"verses":[88],"verseLabel":"طه: 88","question":"ما سرّ التعبير بقوله تعالى: عن العجل ﴿جَسَدًا لَهُ خُوَارٌ﴾؟","answer":"بين أنه جسم له صوت بلا عقل ولا روح، ومع ذلك عبدوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص459–469.","url":""}]},{"id":"s20-91","number":91,"surah":20,"verses":[89],"verseLabel":"طه: 89","question":"ما سرّ التعبير بـ﴿أَلَّا يَرْجِعُ إِلَيْهِمْ قَوْلًا وَلَا يَمْلِكُ لَهُمْ ضَرًّا وَلَا نَفْعًا﴾؟","answer":"جمع عجز التواصل والتصرف؛ لا يجيب عابديه ولا يملك طرفي التأثير.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص470–478.","url":""}]},{"id":"s20-92","number":92,"surah":20,"verses":[90],"verseLabel":"طه: 90","question":"ما سرّ التعبير في قول هارون ﴿إِنَّمَا فُتِنْتُمْ بِهِ وَإِنَّ رَبَّكُمُ الرَّحْمَنُ﴾؟","answer":"سمّى العجل اختبارًا لا إلهًا، وذكّرهم بالرحمن الذي نجاهم ورحمهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص479–488.","url":""}]},{"id":"s20-93","number":93,"surah":20,"verses":[91],"verseLabel":"طه: 91","question":"ما سرّ قولهم ﴿لَنْ نَبْرَحَ عَلَيْهِ عَاكِفِينَ حَتَّى يَرْجِعَ إِلَيْنَا مُوسَى﴾؟","answer":"جمعوا الإصرار بتعليق رجوعهم على القائد، كأن الحق غائب بغيابه رغم بيان هارون.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص489–493.","url":""}]},{"id":"s20-94","number":94,"surah":20,"verses":[92],"verseLabel":"طه: 92","question":"لماذا واجه موسى هارون أولًا: ﴿مَا مَنَعَكَ إِذْ رَأَيْتَهُمْ ضَلُّوا﴾؟","answer":"بدأ موسى بهارون لأنه خليفته في القوم والمكلف بمتابعتهم، فاستفهمه عن سبب عدم اتباع أمره حين رآهم ضلوا؛ ثم سمع عذره قبل الانتقال إلى السامري.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص494–501.","url":""}]},{"id":"s20-95","number":95,"surah":20,"verses":[94],"verseLabel":"طه: 94","question":"ما سرّ التعبير في قول هارون ﴿يَا ابْنَ أُمَّ﴾؟","answer":"استعطفه بأوثق رابطة رحمة في لحظة الغضب، مع أنه أخوه من أب وأم.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص502–510.","url":""}]},{"id":"s20-96","number":96,"surah":20,"verses":[94],"verseLabel":"طه: 94","question":"لماذا خاف هارون أن يقول موسى ﴿فَرَّقْتَ بَيْنَ بَنِي إِسْرَائِيلَ﴾؟","answer":"آثر إبقاء الجماعة حتى يعود موسى على قتال داخلي قد يمزقها، مع إنكاره الشرك.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص502–510.","url":""}]},{"id":"s20-97","number":97,"surah":20,"verses":[95],"verseLabel":"طه: 95","question":"لماذا انتقل موسى بقوله ﴿فَمَا خَطْبُكَ يَا سَامِرِيُّ﴾؟","answer":"بعد سماع عذر هارون اتجه إلى صانع الفتنة، و«الخطب» يعظم شأن فعلته.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص511–515.","url":""}]},{"id":"s20-98","number":98,"surah":20,"verses":[96],"verseLabel":"طه: 96","question":"ما معنى ﴿بَصُرْتُ بِمَا لَمْ يَبْصُرُوا بِهِ﴾؟","answer":"في قوله ﴿بصرت بما لم يبصروا به﴾ أقوال، أشهرها أنه ادعى رؤية الرسول وأخذ قبضة من أثره؛ وقيل المراد إدراك ما لم يدركوه. فلا يجزم النص وحده بتفصيل واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص516–524.","url":""}]},{"id":"s20-99","number":99,"surah":20,"verses":[96],"verseLabel":"طه: 96","question":"ما سرّ التعبير بـ﴿فَنَبَذْتُهَا وَكَذَلِكَ سَوَّلَتْ لِي نَفْسِي﴾؟","answer":"اعترف أن الدافع الأخير تزيين النفس، فسقطت دعوى العلم أمام الهوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص516–524.","url":""}]},{"id":"s20-100","number":100,"surah":20,"verses":[97],"verseLabel":"طه: 97","question":"لماذا كانت عقوبته ﴿لَا مِسَاسَ﴾؟","answer":"من جمع الناس على فتنة العجل عوقب بالعزلة والنفور من المخالطة.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص525–541.","url":""}]},{"id":"s20-101","number":101,"surah":20,"verses":[97],"verseLabel":"طه: 97","question":"لماذا نُسف العجل في اليم نسفًا؟","answer":"لم يُكتف بكسره؛ حُوّل غبارًا وبدد في الماء كي لا تبقى منه بقية تعظّم.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص525–541.","url":""}]},{"id":"s20-102","number":102,"surah":20,"verses":[98],"verseLabel":"طه: 98","question":"لماذا ختمت القصة بـ﴿وَسِعَ كُلَّ شَيْءٍ عِلْمًا﴾؟","answer":"تقابل جهل عابدي العجل وعلم السامري المدعى بعلم الإله الحق المحيط.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص542–547.","url":""}]},{"id":"s20-103","number":103,"surah":20,"verses":[99],"verseLabel":"طه: 99","question":"ما سرّ تسمية القصص الماضي ﴿ذِكْرًا﴾؟","answer":"سمّي القرآن ﴿ذكرًا﴾ لأنه تذكير وموعظة، وقيل لما فيه من الشرف؛ والقصص المذكور بعض هذا الذكر المنزل، لا مجرد حكاية تاريخية.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص548–557.","url":""}]},{"id":"s20-104","number":104,"surah":20,"verses":[100],"verseLabel":"طه: 100","question":"ما سرّ التعبير بـ﴿مَنْ أَعْرَضَ عَنْهُ فَإِنَّهُ يَحْمِلُ يَوْمَ الْقِيَامَةِ وِزْرًا﴾؟","answer":"حوّل الإعراض إلى حمل ثقيل ملازم، فيقابل خفة ترك الذكر بثقل العاقبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص558–563.","url":""}]},{"id":"s20-105","number":105,"surah":20,"verses":[102],"verseLabel":"طه: 102","question":"لماذا يُنفخ في الصور ويحشر المجرمون ﴿زُرْقًا﴾؟","answer":"ذُكرت في ﴿زرقًا﴾ أقوال، منها زرقة العيون أو العمى، ومنها تغيرها لشدة العطش والهول؛ والمتفق عليه أنها هيئة ذل وشدة في الحشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص569–578.","url":""}]},{"id":"s20-106","number":106,"surah":20,"verses":[103,104],"verseLabel":"طه: 103-104","question":"لماذا يتخافتون أن مدة الدنيا لم تتجاوز عشرًا أو يومًا؟","answer":"يصغر مقدار لبث الدنيا في تقديرهم أمام هول القيامة، فيتخافتون بأنه عشر ليال، ويقول أمثلهم طريقة: يومًا؛ والمراد شدة استقصار الزمن لا ضبط مدته حقيقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص569–578.","url":""}]},{"id":"s20-107","number":107,"surah":20,"verses":[105],"verseLabel":"طه: 105","question":"لماذا كان الجواب عن الجبال ﴿فَقُلْ يَنْسِفُهَا رَبِّي نَسْفًا﴾؟","answer":"أكد الإزالة بالمصدر لتنهدم أثبت معالم الأرض تمامًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص585–594.","url":""}]},{"id":"s20-108","number":108,"surah":20,"verses":[107],"verseLabel":"طه: 107","question":"ما سرّ وصف الأرض بـ﴿لَا تَرَى فِيهَا عِوَجًا وَلَا أَمْتًا﴾؟","answer":"نفى الانخفاض والارتفاع، فتصير صفحة مستوية لا مخبأ فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص585–594.","url":""}]},{"id":"s20-109","number":109,"surah":20,"verses":[108],"verseLabel":"طه: 108","question":"لماذا تخشع ﴿الْأَصْوَاتُ لِلرَّحْمَنِ﴾ لا أصحابها؟","answer":"مجاز يصور أثر الخشوع في أخفض مظهر مسموع منهم حتى لا يبقى إلا الهمس.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص595–600.","url":""}]},{"id":"s20-110","number":110,"surah":20,"verses":[109],"verseLabel":"طه: 109","question":"لماذا لا تنفع الشفاعة إلا لمن أذن له الرحمن ورضي له قولًا؟","answer":"قيد الشافع بالإذن والمشفوع له بالرضا، فنفى كل شفاعة مستقلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص601–605.","url":""}]},{"id":"s20-111","number":111,"surah":20,"verses":[110],"verseLabel":"طه: 110","question":"ما سرّ التعبير بـ﴿يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ﴾؟","answer":"دل التركيب على إحاطة علم الله بأحوالهم كلها؛ وفسر ما بين أيديهم وما خلفهم بالمستقبل والماضي، وقيل بما ظهر وخفي، والمقصود عموم العلم في مقابلة قصور علم الخلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص606–609.","url":""}]},{"id":"s20-112","number":112,"surah":20,"verses":[111],"verseLabel":"طه: 111","question":"ما سرّ التعبير بـ﴿وَعَنَتِ الْوُجُوهُ لِلْحَيِّ الْقَيُّومِ﴾؟","answer":"خص الوجوه لأنها عنوان العزة، فخضوعها يظهر استسلام الخلق لمن قامت به الحياة والقيومية.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص610–614.","url":""}]},{"id":"s20-113","number":113,"surah":20,"verses":[112],"verseLabel":"طه: 112","question":"ما سرّ التعبير بـ﴿وَلَا يَخَافُ ظُلْمًا وَلَا هَضْمًا﴾؟","answer":"الظلم تحميل سيئة لم يعملها، والهضم نقص حسنة عملها؛ فنفى جانبي الجور.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص615–619.","url":""}]},{"id":"s20-114","number":114,"surah":20,"verses":[113],"verseLabel":"طه: 113","question":"لماذا صُرّفت في القرآن ﴿مِنَ الْوَعِيدِ﴾؟","answer":"تنوع الإنذار يفتح للقلوب أبوابًا متعددة للتقوى أو تجدد الذكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص620–625.","url":""}]},{"id":"s20-115","number":115,"surah":20,"verses":[114],"verseLabel":"طه: 114","question":"ما سرّ التعبير بـ﴿وَلَا تَعْجَلْ بِالْقُرْآنِ مِنْ قَبْلِ أَنْ يُقْضَى إِلَيْكَ وَحْيُهُ﴾؟","answer":"نهاه عن مبادرة جبريل حرصًا على الحفظ، وعلمه أن التلقي يسبق الترديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص626–641.","url":""}]},{"id":"s20-116","number":116,"surah":20,"verses":[114],"verseLabel":"طه: 114","question":"لماذا كان الدعاء ﴿رَبِّ زِدْنِي عِلْمًا﴾؟","answer":"مع نزول الوحي لا نهاية للتعلم؛ والزيادة المطلوبة من الرب لا من العجلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص626–641.","url":""}]},{"id":"s20-117","number":117,"surah":20,"verses":[115],"verseLabel":"طه: 115","question":"ما سرّ وصف عهد آدم بأنه نسي ولم نجد له عزمًا؟","answer":"أثبتت الآية سبق العهد إلى آدم، ثم وصفت وقوع النسيان وعدم ثبات العزم عند المخالفة؛ وفي ذلك تمهيد لقصة الضعف ثم الاجتباء والتوبة، لا تبرير للمعصية.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص642–653.","url":""}]},{"id":"s20-118","number":118,"surah":20,"verses":[116],"verseLabel":"طه: 116","question":"ما سرّ التعبير بـ﴿أَبَى﴾ في موقف إبليس؟","answer":"الإباء رفض مع استكبار، لا مجرد ترك للسجود أو نسيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص654–663.","url":""}]},{"id":"s20-119","number":119,"surah":20,"verses":[117],"verseLabel":"طه: 117","question":"ما سرّ تسمية إبليس ﴿عَدُوٌّ لَكَ وَلِزَوْجِكَ﴾ قبل الوسوسة؟","answer":"كشف له حقيقة الناصح المزيف مقدمًا، لتقوم الحجة حين يأتيه الإغراء.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص664–673.","url":""}]},{"id":"s20-120","number":120,"surah":20,"verses":[117],"verseLabel":"طه: 117","question":"ما سرّ التعبير بـ﴿فَلَا يُخْرِجَنَّكُمَا مِنَ الْجَنَّةِ فَتَشْقَى﴾ فأفرد الشقاء؟","answer":"أفرد ﴿فتشقى﴾ مع تثنية ﴿يخرجنكما﴾ لأن الخطاب أبرز ما يلحق آدم من تعب المعاش بعد الخروج، وقيل لأن شقاء أحد الزوجين شقاء للآخر؛ فلا يحصر التعليل في وجه واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص664–673.","url":""}]},{"id":"s20-121","number":121,"surah":20,"verses":[118,119],"verseLabel":"طه: 118-119","question":"لماذا فُصل نعيم الجنة في الجوع والعري والعطش والضحى؟","answer":"جمعت الآيتان أصول الحاجة البدنية: الطعام في نفي الجوع، والكسوة في نفي العري، والشراب في نفي الظمأ، والكن أو الظل في نفي الضحى.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص674–683.","url":""}]},{"id":"s20-122","number":122,"surah":20,"verses":[120],"verseLabel":"طه: 120","question":"لماذا سماها الشيطان ﴿شَجَرَةِ الْخُلْدِ وَمُلْكٍ لَا يَبْلَى﴾؟","answer":"أعاد تسمية المحظور باسمين محبوبين يخفيان المعصية: البقاء والسلطان.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص684–694.","url":""}]},{"id":"s20-123","number":123,"surah":20,"verses":[121],"verseLabel":"طه: 121","question":"ما سرّ التعبير بـ﴿فَبَدَتْ لَهُمَا سَوْآتُهُمَا﴾ فور الأكل؟","answer":"جعل انكشاف العورة أثرًا عاجلًا للمعصية، فسقط ستر الأمان مع المخالفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص695–706.","url":""}]},{"id":"s20-124","number":124,"surah":20,"verses":[121],"verseLabel":"طه: 121","question":"لماذا طفقا يخصفان عليهما من ورق الجنة؟","answer":"بادرا إلى الستر بما أمكن، فبقيت الفطرة حية رغم الزلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص695–706.","url":""}]},{"id":"s20-125","number":125,"surah":20,"verses":[122],"verseLabel":"طه: 122","question":"ما سرّ التعبير بـ﴿ثُمَّ اجْتَبَاهُ رَبُّهُ فَتَابَ عَلَيْهِ وَهَدَى﴾؟","answer":"لم تكن الزلة خاتمة آدم؛ اجتباه الرب وقبل توبته وأعاده إلى طريق الهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص695–706.","url":""}]},{"id":"s20-126","number":126,"surah":20,"verses":[123],"verseLabel":"طه: 123","question":"ما سرّ التعبير بـ﴿بَعْضُكُمْ لِبَعْضٍ عَدُوٌّ﴾؟","answer":"انتقلت عداوة إبليس إلى مسرح الأرض، ومعها صراع البشر حين يتبعون وسوسته.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص707–716.","url":""}]},{"id":"s20-127","number":127,"surah":20,"verses":[123],"verseLabel":"طه: 123","question":"ما سرّ التعبير بـ﴿فَمَنِ اتَّبَعَ هُدَايَ فَلَا يَضِلُّ وَلَا يَشْقَى﴾؟","answer":"نفى ضلال الطريق وشقاء العاقبة؛ الهدى يحفظ المعرفة والحياة معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص707–716.","url":""}]},{"id":"s20-128","number":128,"surah":20,"verses":[124],"verseLabel":"طه: 124","question":"لماذا كانت ثمرة الإعراض ﴿مَعِيشَةً ضَنْكًا﴾؟","answer":"﴿معيشة ضنكًا﴾ معيشة ضيقة شديدة بسبب الإعراض عن ذكر الله، ويدخل فيها ضيق القلب ولو اتسع ظاهر الرزق؛ وذُكرت في تفسيرها وجوه دنيوية وأخروية.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص717–723.","url":""}]},{"id":"s20-129","number":129,"surah":20,"verses":[125,126],"verseLabel":"طه: 125-126","question":"ما دلالة قول الأعمى ﴿لِمَ حَشَرْتَنِي أَعْمَى وَقَدْ كُنْتُ بَصِيرًا﴾؟","answer":"نظر إلى بصر الجسد ونسي عماه عن الآيات؛ فجاء الجواب بأن الجزاء من جنس النسيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص717–723.","url":""}]},{"id":"s20-130","number":130,"surah":20,"verses":[127],"verseLabel":"طه: 127","question":"ما سرّ التعبير بـ﴿وَكَذَلِكَ نَجْزِي مَنْ أَسْرَفَ﴾؟","answer":"ربط المصير بسنة عامة: تجاوز حدود الله والتكذيب يؤديان إلى العذاب الأشد والأبقى.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص724–742.","url":""}]},{"id":"s20-131","number":131,"surah":20,"verses":[128],"verseLabel":"طه: 128","question":"لماذا جعل مساكن القرون الهالكة آيات ﴿لِأُولِي النُّهَى﴾؟","answer":"خص الانتفاع بآثار القرون بـ﴿أولي النهى﴾ لأن العقول التي تنهى أصحابها عن الباطل هي التي تعتبر بمصارع المكذبين؛ أما مجرد المرور بالمساكن فلا يحقق الاعتبار.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص743–762.","url":""}]},{"id":"s20-132","number":132,"surah":20,"verses":[129],"verseLabel":"طه: 129","question":"لماذا لولا كلمة سبقت لكان العذاب ﴿لِزَامًا وَأَجَلٌ مُسَمًّى﴾؟","answer":"دلّت الكلمة السابقة والأجل المسمى على أن تأخير العذاب لحكمة وقضاء سابق إلى وقت محدد؛ ولولا ذلك لكان العذاب لازمًا لهم عاجلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص763–771.","url":""}]},{"id":"s20-133","number":133,"surah":20,"verses":[130],"verseLabel":"طه: 130","question":"ما سرّ التعبير بـ﴿فَاصْبِرْ عَلَى مَا يَقُولُونَ وَسَبِّحْ بِحَمْدِ رَبِّكَ﴾؟","answer":"عُطف التسبيح على الصبر لأن ذكر الله والصلاة مما يثبت القلب على أذى أقوال المكذبين، وجاء تفصيل أوقات التسبيح ليحيط بأطراف اليوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص772–789.","url":""}]},{"id":"s20-134","number":134,"surah":20,"verses":[131],"verseLabel":"طه: 131","question":"لماذا نُهي عن مد العينين إلى أزواج من زهرة الدنيا؟","answer":"استعير ﴿لا تمدن عينيك﴾ لإطالة النظر رغبةً في متاعهم، ووصف المتاع بـ﴿زهرة الحياة الدنيا﴾ لجماله العاجل السريع الزوال، ثم بين أنه فتنة وابتلاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص790–805.","url":""}]},{"id":"s20-135","number":135,"surah":20,"verses":[131],"verseLabel":"طه: 131","question":"ما سرّ التعبير بـ﴿وَرِزْقُ رَبِّكَ خَيْرٌ وَأَبْقَى﴾؟","answer":"قوبلت زهرة الدنيا الزائلة برزق الله، فوصف بأنه ﴿خير وأبقى﴾: خير في حقيقته وأدوم في عاقبته.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص790–805.","url":""}]},{"id":"s20-136","number":136,"surah":20,"verses":[132],"verseLabel":"طه: 132","question":"ما سرّ التعبير بـ﴿وَأْمُرْ أَهْلَكَ بِالصَّلَاةِ وَاصْطَبِرْ عَلَيْهَا﴾؟","answer":"أُمر النبي أن يبدأ أهله ومن يتصل به بالصلاة، وأن يداوم عليها ويعالج مشقتها؛ فصيغة ﴿اصطبر﴾ أبلغ من مجرد الصبر في طلب الثبات والمداومة.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص10–20.","url":""}]},{"id":"s20-137","number":137,"surah":20,"verses":[132],"verseLabel":"طه: 132","question":"ما سرّ التعبير بـ﴿لَا نَسْأَلُكَ رِزْقًا نَحْنُ نَرْزُقُكَ﴾؟","answer":"نفى أن يكون الله مطالبًا نبيه برزق، ثم قدم الضمير في ﴿نحن نرزقك﴾ للحصر والتقوية؛ أي الله وحده هو الرازق، وفي ذلك تطمين للقلب عند التفرغ للعبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص10–20.","url":""}]},{"id":"s20-138","number":138,"surah":20,"verses":[133],"verseLabel":"طه: 133","question":"ما سرّ التعبير في قولهم ﴿لَوْلَا يَأْتِينَا بِآيَةٍ مِنْ رَبِّهِ﴾ والقرآن بين أيديهم؟","answer":"أنكروا الرسالة بطلب آية مقترحة، مع أن القرآن نفسه بيّنة جامعة جاءت بما في الصحف الأولى؛ فدل طلبهم على التعنت لا على فقدان الدليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص21–29.","url":""}]},{"id":"s20-139","number":139,"surah":20,"verses":[134],"verseLabel":"طه: 134","question":"ما سرّ التعبير بـ﴿فَنَتَّبِعَ آيَاتِكَ مِنْ قَبْلِ أَنْ نَذِلَّ وَنَخْزَى﴾؟","answer":"حكى النص عذرهم المفترض لو عوقبوا قبل إرسال الرسول، ثم أبطل هذا العذر بوقوع البيان قبل الذل والخزي؛ فتمت الحجة عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص30–40.","url":""}]},{"id":"s20-140","number":140,"surah":20,"verses":[135],"verseLabel":"طه: 135","question":"لماذا ختمت السورة بـ﴿كُلٌّ مُتَرَبِّصٌ فَتَرَبَّصُوا﴾؟","answer":"جاء الختام بالمقابلة في التربص: كل فريق منتظر عاقبة الآخر، ثم توعدهم بأن العاقبة ستكشف أصحاب الصراط السوي ومن اهتدى.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص41–50.","url":""}]},{"id":"s21-1","number":1,"surah":21,"verses":[1],"verseLabel":"الأنبياء: 1","question":"ما سرّ التعبير بـ﴿اقْتَرَبَ لِلنَّاسِ حِسَابُهُمْ﴾ مع مرور قرون؟","answer":"كل آت قريب، والحساب يقترب بانقضاء الزمن واقتراب أجل كل إنسان؛ فمرور القرون لا يناقض فعل ﴿اقترب﴾، بل يزيد الموعود قربًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص53–61.","url":""}]},{"id":"s21-2","number":2,"surah":21,"verses":[1],"verseLabel":"الأنبياء: 1","question":"ما سرّ التعبير بـ﴿فِي غَفْلَةٍ مُعْرِضُونَ﴾؟","answer":"جمع الوصف بين غفلة القلب والإعراض الاختياري؛ فليس عدم انتفاعهم ناشئًا عن الجهل وحده، بل عن صدودهم عما ينبههم.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص53–61.","url":""}]},{"id":"s21-3","number":3,"surah":21,"verses":[2],"verseLabel":"الأنبياء: 2","question":"ما سرّ التعبير هنا بـ﴿مِنْ ذِكْرٍ مِنْ رَبِّهِمْ مُحْدَثٍ﴾، وفي الشعراء ﴿مِنْ ذِكْرٍ مِنَ الرَّحْمَنِ مُحْدَثٍ﴾؟","answer":"اختير ﴿ربهم﴾ هنا لمناسبة مقام إقامة الحجة عليهم بنعم الرب وتدبيره، واختير ﴿الرحمن﴾ في الشعراء لمناسبة سياق الرحمة وخاتمة السورة؛ والمقارنة مقيدة بما قرره مبحث المتشابه.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص53–61.","url":""}]},{"id":"s21-4","number":4,"surah":21,"verses":[2],"verseLabel":"الأنبياء: 2","question":"كيف يستمعون الذكر وهم ﴿يَلْعَبُونَ﴾؟","answer":"آذانهم تسمع لكن القلوب تتلقى الوحي كتسلية، فانتفى أثر الاستماع الجاد.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص53–61.","url":""}]},{"id":"s21-5","number":5,"surah":21,"verses":[3],"verseLabel":"الأنبياء: 3","question":"ما سرّ التعبير بـ﴿لَاهِيَةً قُلُوبُهُمْ﴾؟","answer":"قدم الحال ليكشف أن موضع الداء القلب؛ اللعب الظاهر ثمرة لهو باطني.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص62–77.","url":""}]},{"id":"s21-6","number":6,"surah":21,"verses":[3],"verseLabel":"الأنبياء: 3","question":"لماذا أسرّ الظالمون النجوى مع أن الله نقلها؟","answer":"توهموا أن خفض الصوت يحمي مؤامرتهم، ففضح الوحي ما أخفوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص62–77.","url":""}]},{"id":"s21-7","number":7,"surah":21,"verses":[3],"verseLabel":"الأنبياء: 3","question":"ما سرّ التعبير في قولهم عن الرسول ﴿بَشَرٌ مِثْلُكُمْ﴾؟","answer":"جعلوا بشرية الرسول شبهة في رسالته، مع أن سنة الله جرت بإرسال رجال من البشر ليصح التلقي والاقتداء؛ فالحجة تنقلب عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص62–77.","url":""}]},{"id":"s21-8","number":8,"surah":21,"verses":[4],"verseLabel":"الأنبياء: 4","question":"ما سرّ التعبير بـ﴿رَبِّي يَعْلَمُ الْقَوْلَ فِي السَّمَاءِ وَالْأَرْضِ﴾؟","answer":"عمم العلم بكل قول في الكون؛ فالسر والجهر عنده سواء.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص78–90.","url":""}]},{"id":"s21-9","number":9,"surah":21,"verses":[5],"verseLabel":"الأنبياء: 5","question":"لماذا تنقلوا بين ﴿أَضْغَاثُ أَحْلَامٍ﴾ و﴿افْتَرَاهُ﴾ و﴿شَاعِرٌ﴾؟","answer":"تناقض اتهاماتهم يكشف حيرتهم؛ لو كانت شبهة محكمة لاستقروا على وصف واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص91–97.","url":""}]},{"id":"s21-10","number":10,"surah":21,"verses":[6],"verseLabel":"الأنبياء: 6","question":"ما سرّ التعبير بـ﴿مَا آمَنَتْ قَبْلَهُمْ مِنْ قَرْيَةٍ أَهْلَكْنَاهَا﴾؟","answer":"ذكّرهم أن الأمم المقترحة للآيات كذبت بعدها فاستؤصلت؛ الاقتراح ليس طريق نجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص91–97.","url":""}]},{"id":"s21-11","number":11,"surah":21,"verses":[7,25],"verseLabel":"الأنبياء: 7، 25","question":"ما سرّ مجيء ﴿وَمَا أَرْسَلْنَا قَبْلَكَ﴾ بلا «من» في الآية 7، ومجيء ﴿وَمَا أَرْسَلْنَا مِنْ قَبْلِكَ مِنْ رَسُولٍ﴾ في الآية 25؟","answer":"الأولى اتصلت بسياق إرسال البشر فاستغنت عن زيادة ﴿من﴾، أما الثانية فعممت الحكم في كل رسول، فجاءت ﴿من﴾ الأولى لابتداء الغاية والثانية لاستغراق أفراد الرسل.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص98–110، و232–241.","url":""}]},{"id":"s21-12","number":12,"surah":21,"verses":[7],"verseLabel":"الأنبياء: 7","question":"ما سرّ التعبير بـ﴿فَاسْأَلُوا أَهْلَ الذِّكْرِ﴾؟","answer":"ألزم المنكر بالرجوع إلى أهل العلم حين يجهل، بدل جعل الجهل حجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص98–110.","url":""}]},{"id":"s21-13","number":13,"surah":21,"verses":[8],"verseLabel":"الأنبياء: 8","question":"ما سرّ وصف الرسل بـ﴿وَمَا جَعَلْنَاهُمْ جَسَدًا لَا يَأْكُلُونَ الطَّعَامَ﴾؟","answer":"نفت الآية عن الرسل أن يكونوا أجسادًا لا تأكل، ثم نفت الخلود؛ فقررت بشريتهم وحاجاتهم المعتادة، وردت توهم أن الرسالة تستلزم الخروج عن طبيعة البشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص111–118.","url":""}]},{"id":"s21-14","number":14,"surah":21,"verses":[9],"verseLabel":"الأنبياء: 9","question":"ما سرّ التعبير بـ﴿ثُمَّ صَدَقْنَاهُمُ الْوَعْدَ﴾؟","answer":"نسب الصدق إلى إنجاز الوعد، فنجاة الرسل سنة تتحقق بعد زمن الابتلاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص111–118.","url":""}]},{"id":"s21-15","number":15,"surah":21,"verses":[10],"verseLabel":"الأنبياء: 10","question":"ما سرّ التعبير بـ﴿لَقَدْ أَنْزَلْنَا إِلَيْكُمْ كِتَابًا فِيهِ ذِكْرُكُمْ﴾؟","answer":"فيه شرفهم وموعظتهم وبيان ما يصلحهم؛ إعراضهم عنه إعراض عن خير أنفسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص119–133.","url":""}]},{"id":"s21-16","number":16,"surah":21,"verses":[11],"verseLabel":"الأنبياء: 11","question":"ما سرّ التعبير بـ﴿وَكَمْ قَصَمْنَا مِنْ قَرْيَةٍ﴾ لا «أهلكنا»؟","answer":"القصم كسر شديد لا جبر بعده، يصور انهيار قوة الظالمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص134–152.","url":""}]},{"id":"s21-17","number":17,"surah":21,"verses":[12],"verseLabel":"الأنبياء: 12","question":"ما سرّ التعبير بـ﴿إِذَا هُمْ مِنْهَا يَرْكُضُونَ﴾؟","answer":"«إذا» تفاجئ بسرعة فرارهم، والركض حركة مذعورة بعد غرور الاستقرار.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص134–152.","url":""}]},{"id":"s21-18","number":18,"surah":21,"verses":[13],"verseLabel":"الأنبياء: 13","question":"ما سرّ التعبير بقوله تعالى: لهم ساخرًا ﴿لَا تَرْكُضُوا وَارْجِعُوا إِلَى مَا أُتْرِفْتُمْ فِيهِ﴾؟","answer":"تهكم يقلب نعيمهم الذي احتموا به إلى موضع عقوبتهم وعجزهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص134–152.","url":""}]},{"id":"s21-19","number":19,"surah":21,"verses":[15],"verseLabel":"الأنبياء: 15","question":"ما سرّ التعبير بـ﴿فَمَا زَالَتْ تِلْكَ دَعْوَاهُمْ﴾؟","answer":"لم يبق لهم كلام إلا الاعتراف بالظلم، لكنه جاء بعد فوات التوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص153–161.","url":""}]},{"id":"s21-20","number":20,"surah":21,"verses":[15],"verseLabel":"الأنبياء: 15","question":"ما سر صورة ﴿حَصِيدًا خَامِدِينَ﴾؟","answer":"جمع صورة الزرع المقطوع والنار المنطفئة؛ انقطعت حركتهم وحياتهم تمامًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص153–161.","url":""}]},{"id":"s21-21","number":21,"surah":21,"verses":[16],"verseLabel":"الأنبياء: 16","question":"ما سرّ التعبير بـ﴿وَمَا خَلَقْنَا السَّمَاءَ وَالْأَرْضَ... لَاعِبِينَ﴾؟","answer":"نفي اللعب يثبت أن الخلق ذو غاية وحساب، فيرد غفلتهم التي افتتحت بها السورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص162–176.","url":""}]},{"id":"s21-22","number":22,"surah":21,"verses":[17],"verseLabel":"الأنبياء: 17","question":"ما سرّ التعبير بـ﴿لَوْ أَرَدْنَا أَنْ نَتَّخِذَ لَهْوًا لَاتَّخَذْنَاهُ مِنْ لَدُنَّا﴾؟","answer":"الشرط مسوق على سبيل الفرض الممتنع لإبطال دعواهم؛ فلو أريد لهو ـ تعالى الله عنه ـ لاتخذ من لدنه، لا مما زعموا من صاحبة أو ولد.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص162–176.","url":""}]},{"id":"s21-23","number":23,"surah":21,"verses":[18],"verseLabel":"الأنبياء: 18","question":"ما سرّ التعبير بـ﴿بَلْ نَقْذِفُ بِالْحَقِّ عَلَى الْبَاطِلِ﴾؟","answer":"استعير القذف لإيراد الحق بقوة على الباطل، ثم صُوّر أثره في دمغه وإبطاله؛ فالمقام مقام إزالة للحجة الفاسدة لا مجرد مقابلة هادئة.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص177–185.","url":""}]},{"id":"s21-24","number":24,"surah":21,"verses":[18],"verseLabel":"الأنبياء: 18","question":"ما سرّ التعبير بـ﴿فَيَدْمَغُهُ فَإِذَا هُوَ زَاهِقٌ﴾؟","answer":"الدمغ إصابة الدماغ، و«إذا» تصور زوال الباطل المفاجئ عند لقاء الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص177–185.","url":""}]},{"id":"s21-25","number":25,"surah":21,"verses":[19],"verseLabel":"الأنبياء: 19","question":"ما سرّ وصف الملائكة بـ﴿لَا يَسْتَكْبِرُونَ عَنْ عِبَادَتِهِ وَلَا يَسْتَحْسِرُونَ﴾؟","answer":"نفى عن الملائكة الاستكبار وهو امتناع الإرادة، والاستحسار وهو الإعياء والانقطاع؛ فثبت دوام عبادتهم طوعًا من غير فتور.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص186–196.","url":""}]},{"id":"s21-26","number":26,"surah":21,"verses":[20],"verseLabel":"الأنبياء: 20","question":"ما سرّ التعبير بـ﴿يُسَبِّحُونَ اللَّيْلَ وَالنَّهَارَ لَا يَفْتُرُونَ﴾؟","answer":"جمع الزمن كله ثم نفى أدنى فتور، ليصور دوام العبودية.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص186–196.","url":""}]},{"id":"s21-27","number":27,"surah":21,"verses":[21],"verseLabel":"الأنبياء: 21","question":"ما سرّ التعبير بـ﴿أَمِ اتَّخَذُوا آلِهَةً مِنَ الْأَرْضِ هُمْ يُنْشِرُونَ﴾؟","answer":"اختبر ألوهية أصنام أرضية بأعظم قدرة: هل تحيي الموتى؟ فعجزها ظاهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص197–215.","url":""}]},{"id":"s21-28","number":28,"surah":21,"verses":[22],"verseLabel":"الأنبياء: 22","question":"ما سرّ التعبير بـ﴿لَفَسَدَتَا﴾ لو كان فيهما آلهة؟","answer":"هذا من دليل التمانع: لو تعددت الآلهة المستقلة المدبرة لاختل نظام السماوات والأرض؛ وانتظامهما شاهد على وحدانية المدبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص197–215.","url":""}]},{"id":"s21-29","number":29,"surah":21,"verses":[23],"verseLabel":"الأنبياء: 23","question":"ما سرّ التعبير بـ﴿لَا يُسْأَلُ عَمَّا يَفْعَلُ وَهُمْ يُسْأَلُونَ﴾؟","answer":"لكمال ملكه وحكمته لا يعترض عليه، أما المخلوق فمملوك محدود مسؤول.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص197–215.","url":""}]},{"id":"s21-30","number":30,"surah":21,"verses":[24],"verseLabel":"الأنبياء: 24","question":"ما سرّ التعبير بـ﴿هَاتُوا بُرْهَانَكُمْ﴾؟","answer":"نقل دعوى الشرك من التقليد إلى محكمة الدليل التي لا يملكون فيها شيئًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص216–231.","url":""}]},{"id":"s21-31","number":31,"surah":21,"verses":[25],"verseLabel":"الأنبياء: 25","question":"لماذا لخّص وحي الرسل في ﴿لَا إِلَهَ إِلَّا أَنَا فَاعْبُدُونِ﴾؟","answer":"التوحيد أصل الرسالات كلها، والعبادة أثره العملي المباشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص232–241.","url":""}]},{"id":"s21-32","number":32,"surah":21,"verses":[26],"verseLabel":"الأنبياء: 26","question":"ما سرّ التعبير في قولهم ﴿اتَّخَذَ الرَّحْمَنُ وَلَدًا﴾ ثم رد بـ﴿سُبْحَانَهُ بَلْ عِبَادٌ مُكْرَمُونَ﴾؟","answer":"نزه الله ثم صحح مكانة الملائكة: تكريم العبودية لا بنوة الألوهية.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص242–247.","url":""}]},{"id":"s21-33","number":33,"surah":21,"verses":[27],"verseLabel":"الأنبياء: 27","question":"ما سرّ التعبير بـ﴿لَا يَسْبِقُونَهُ بِالْقَوْلِ﴾؟","answer":"تصوير لأدبهم: لا يبادرون بين يدي أمره برأي أو اقتراح.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص248–254.","url":""}]},{"id":"s21-34","number":34,"surah":21,"verses":[28],"verseLabel":"الأنبياء: 28","question":"لماذا جمع العلم بما بين أيديهم وما خلفهم مع الشفاعة؟","answer":"الشفاعة ليست لإعلام الله بمجهول؛ تقع بإذنه وعلمه المحيط فقط.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص255–263.","url":""}]},{"id":"s21-35","number":35,"surah":21,"verses":[30],"verseLabel":"الأنبياء: 30","question":"ما دلالة صورة ﴿كَانَتَا رَتْقًا فَفَتَقْنَاهُمَا﴾؟","answer":"ذُكر في الرتق والفتق أكثر من وجه: التحام السماوات والأرض ثم فصلهما، أو انغلاق السماء عن المطر والأرض عن النبات ثم فتحهما؛ فلا يحصر النص في تصوير واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص274–286.","url":""}]},{"id":"s21-36","number":36,"surah":21,"verses":[30],"verseLabel":"الأنبياء: 30","question":"ما سرّ التعبير بـ﴿وَجَعَلْنَا مِنَ الْمَاءِ كُلَّ شَيْءٍ حَيٍّ﴾؟","answer":"جعل الماء أصل الحياة المشاهد، ودليلًا قريبًا على قدرة الإحياء.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص274–286.","url":""}]},{"id":"s21-37","number":37,"surah":21,"verses":[31],"verseLabel":"الأنبياء: 31","question":"ما سرّ وصف الجبال بأنها ﴿رَوَاسِيَ﴾؟","answer":"اللفظ يستحضر رسوخها ووظيفتها في تثبيت الأرض كي لا تميد بأهلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص287–296.","url":""}]},{"id":"s21-38","number":38,"surah":21,"verses":[32],"verseLabel":"الأنبياء: 32","question":"ما سرّ التعبير بـ﴿وَجَعَلْنَا السَّمَاءَ سَقْفًا مَحْفُوظًا﴾؟","answer":"شبّهها بسقف يظل الأرض، محفوظ النظام ومحفوظًا من الاختلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص297–305.","url":""}]},{"id":"s21-39","number":39,"surah":21,"verses":[33],"verseLabel":"الأنبياء: 33","question":"ما سرّ التعبير عن الشمس والقمر بـ﴿كُلٌّ فِي فَلَكٍ يَسْبَحُونَ﴾؟","answer":"استعار السباحة لحركتها السلسة المستمرة في مداراتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص306–314.","url":""}]},{"id":"s21-40","number":40,"surah":21,"verses":[34],"verseLabel":"الأنبياء: 34","question":"ما سرّ التعبير للنبي بـ﴿وَمَا جَعَلْنَا لِبَشَرٍ مِنْ قَبْلِكَ الْخُلْدَ﴾؟","answer":"يسليه بأن الموت سنة البشر، ويبطل ترقبهم موته كأنه نهاية الرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص315–323.","url":""}]},{"id":"s21-41","number":41,"surah":21,"verses":[35],"verseLabel":"الأنبياء: 35","question":"ما سرّ مجيء ﴿وَإِلَيْنَا تُرْجَعُونَ﴾ بالواو هنا، و﴿ثُمَّ إِلَيْنَا تُرْجَعُونَ﴾ في العنكبوت؟","answer":"في طه فصل ذكر الابتلاء بين الموت والرجوع، فناسب العطف بالواو، أما العنكبوت فوصل الموت بالرجوع مع إفادة التراخي بـ﴿ثم﴾؛ وهذا من مراعاة نظم كل سياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص324–335.","url":""}]},{"id":"s21-42","number":42,"surah":21,"verses":[35],"verseLabel":"الأنبياء: 35","question":"ما سرّ التعبير بـ﴿وَنَبْلُوكُمْ بِالشَّرِّ وَالْخَيْرِ فِتْنَةً﴾؟","answer":"الضراء والسراء كلاهما اختبار يكشف الصبر والشكر، فلا يدل الخير وحده على الرضا.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص324–335.","url":""}]},{"id":"s21-43","number":43,"surah":21,"verses":[36],"verseLabel":"الأنبياء: 36","question":"ما سرّ إظهار ﴿الَّذِينَ كَفَرُوا﴾ هنا، والاكتفاء بالضمير في ﴿وَإِذَا رَأَوْكَ﴾ في الفرقان؟","answer":"صُرح بـ﴿الذين كفروا﴾ هنا إذ لم يسبق ما يغني عن إظهارهم في السياق القريب، بينما سبق ذكر الكافرين في الفرقان فحسن رد الضمير إليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص336–351.","url":""}]},{"id":"s21-44","number":44,"surah":21,"verses":[37],"verseLabel":"الأنبياء: 37","question":"ما سرّ التعبير بـ﴿خُلِقَ الْإِنْسَانُ مِنْ عَجَلٍ﴾؟","answer":"بالغ في رسوخ العجلة فيه حتى كأنها مادته التي خلق منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص352–360.","url":""}]},{"id":"s21-45","number":45,"surah":21,"verses":[37],"verseLabel":"الأنبياء: 37","question":"ما سرّ التعبير بـ﴿فَلَا تَسْتَعْجِلُونِ﴾ بعد وعد إراءة الآيات؟","answer":"وعد بوقوعها ونهاهم عن طلب تقديمها، فالاستعجال لا يغير وقت الحكمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص352–360.","url":""}]},{"id":"s21-46","number":46,"surah":21,"verses":[39],"verseLabel":"الأنبياء: 39","question":"ما سرّ التعبير بـ﴿لَا يَكُفُّونَ عَنْ وُجُوهِهِمُ النَّارَ وَلَا عَنْ ظُهُورِهِمْ﴾؟","answer":"استوعب جهتي المواجهة والإحاطة، فلا يد تدفع ولا نصير يحمي.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص367–376.","url":""}]},{"id":"s21-47","number":47,"surah":21,"verses":[40],"verseLabel":"الأنبياء: 40","question":"ما سرّ التعبير بـ﴿بَلْ تَأْتِيهِمْ بَغْتَةً فَتَبْهَتُهُمْ﴾؟","answer":"المباغتة تسلبهم الحجة والحركة، والبهت دهشة تشل القدرة على الرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص377–383.","url":""}]},{"id":"s21-48","number":48,"surah":21,"verses":[42],"verseLabel":"الأنبياء: 42","question":"ما سرّ التعبير بـ﴿مَنْ يَكْلَؤُكُمْ بِاللَّيْلِ وَالنَّهَارِ﴾؟","answer":"الكلاءة حراسة مستمرة، والسؤال يكشف أن بقاءهم لحظة نعمة لا يملكها آلهتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص394–408.","url":""}]},{"id":"s21-49","number":49,"surah":21,"verses":[44],"verseLabel":"الأنبياء: 44","question":"ما سرّ التعبير بـ﴿نَأْتِي الْأَرْضَ نَنْقُصُهَا مِنْ أَطْرَافِهَا﴾؟","answer":"نقص الأرض من أطرافها فُسر بظهور الإسلام وفتح البلاد وانتقاص سلطان الكفر، وذُكرت أوجه أخرى؛ فالجواب لا يحصر اللفظ في معنى جغرافي مادي.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص409–421.","url":""}]},{"id":"s21-50","number":50,"surah":21,"verses":[45],"verseLabel":"الأنبياء: 45","question":"ما سرّ التعبير بـ﴿إِنَّمَا أُنْذِرُكُمْ بِالْوَحْيِ﴾؟","answer":"حصر مصدر الإنذار في خبر الله، لا تخمين بشر أو مصلحة شخصية.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص422–434.","url":""}]},{"id":"s21-51","number":51,"surah":21,"verses":[46],"verseLabel":"الأنبياء: 46","question":"ما سرّ التعبير بـ﴿مَسَّتْهُمْ نَفْحَةٌ مِنْ عَذَابِ رَبِّكَ﴾؟","answer":"اجتمعت ألفاظ التقليل في ﴿مستهم نفحة من عذاب ربك﴾: المس والنفحة والتبعيض بـ﴿من﴾؛ فإذا أقروا بالظلم عند اليسير فكيف بالعذاب التام.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص435–447.","url":""}]},{"id":"s21-52","number":52,"surah":21,"verses":[47],"verseLabel":"الأنبياء: 47","question":"ما سرّ التعبير بـ﴿وَنَضَعُ الْمَوَازِينَ الْقِسْطَ﴾ بالجمع؟","answer":"جاء الجمع في ﴿الموازين﴾ لتعدد الموازين أو الموزونات ووجوه الحساب، ووصفها بـ﴿القسط﴾ للمبالغة في العدل؛ وقد أبقي تعدد الأقوال دون جزم بواحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص448–466.","url":""}]},{"id":"s21-53","number":53,"surah":21,"verses":[47],"verseLabel":"الأنبياء: 47","question":"لماذا ذكر وزن ﴿حَبَّةٍ مِنْ خَرْدَلٍ﴾؟","answer":"أصغر ما يتصوره المخاطب من العمل لا يضيع عن الميزان.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص448–466.","url":""}]},{"id":"s21-54","number":54,"surah":21,"verses":[48],"verseLabel":"الأنبياء: 48","question":"ما سرّ تسمية التوراة ﴿الْفُرْقَانَ وَضِيَاءً وَذِكْرًا﴾؟","answer":"تفرق بين الحق والباطل، وتنير الطريق، وتوقظ القلب؛ ثلاث وظائف للكتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص467–477.","url":""}]},{"id":"s21-55","number":55,"surah":21,"verses":[49],"verseLabel":"الأنبياء: 49","question":"ما سرّ التعبير بـ﴿يَخْشَوْنَ رَبَّهُمْ بِالْغَيْبِ﴾؟","answer":"خشيتهم ثابتة حين يغيب نظر الناس وحين يكون العذاب غيبًا لم يشاهدوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص478–488.","url":""}]},{"id":"s21-56","number":56,"surah":21,"verses":[51],"verseLabel":"الأنبياء: 51","question":"ما سرّ التعبير بـ﴿آتَيْنَا إِبْرَاهِيمَ رُشْدَهُ مِنْ قَبْلُ﴾؟","answer":"رشد التوحيد سبق محاجته قومه، ولم يكن موقفًا طارئًا صنعته الخصومة.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص498–506.","url":""}]},{"id":"s21-57","number":57,"surah":21,"verses":[52],"verseLabel":"الأنبياء: 52","question":"ما سرّ التعبير بـ﴿مَا هَذِهِ التَّمَاثِيلُ الَّتِي أَنْتُمْ لَهَا عَاكِفُونَ﴾؟","answer":"سمّاها ﴿التماثيل﴾ تحقيرًا لشأنها ونزعًا لوصف الألوهية عنها، وقدم الجار في ﴿لها عاكفون﴾ للاهتمام ببيان شدة تعلقهم بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص507–517.","url":""}]},{"id":"s21-58","number":58,"surah":21,"verses":[53],"verseLabel":"الأنبياء: 53","question":"ما سرّ مجيء ﴿وَجَدْنَا آبَاءَنَا لَهَا عَابِدِينَ﴾ بلا «بل» هنا، ومجيئها بـ«بل» في الشعراء؟","answer":"في الأنبياء جاء الكلام جوابًا مباشرًا عن سؤال إبراهيم عن التماثيل، أما في الشعراء فـ﴿بل﴾ إضراب عن الاستدلال بنفعها إلى مجرد تقليد الآباء.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص518–523.","url":""}]},{"id":"s21-59","number":59,"surah":21,"verses":[54],"verseLabel":"الأنبياء: 54","question":"لماذا جمع إبراهيم الآباء والأبناء في ﴿ضَلَالٍ مُبِينٍ﴾؟","answer":"أبطل أن يمنح القدمُ الباطلَ شرعية؛ المقلد والأصل سواء أمام الدليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص524–530.","url":""}]},{"id":"s21-60","number":60,"surah":21,"verses":[57],"verseLabel":"الأنبياء: 57","question":"ما سرّ التعبير بـ﴿وَتَاللَّهِ لَأَكِيدَنَّ أَصْنَامَكُمْ﴾؟","answer":"قسم وعزم على خطة تكشف عجزها عمليًا، بعد أن لم تنفع الحجة القولية.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص554–563.","url":""}]},{"id":"s21-61","number":61,"surah":21,"verses":[58],"verseLabel":"الأنبياء: 58","question":"لماذا جعل الأصنام ﴿جُذَاذًا إِلَّا كَبِيرًا لَهُمْ﴾؟","answer":"ترك الكبير ليجعل رجوعهم إليه باب سؤال: لماذا لم يدافع عن نفسه وعن غيره؟","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص564–571.","url":""}]},{"id":"s21-62","number":62,"surah":21,"verses":[60],"verseLabel":"الأنبياء: 60","question":"ما سرّ التعبير في قولهم ﴿فَتًى يَذْكُرُهُمْ يُقَالُ لَهُ إِبْرَاهِيمُ﴾؟","answer":"نكروه بقولهم ﴿فتى﴾ لعدم معرفتهم به أو للتحقير، ثم جاء ﴿يقال له إبراهيم﴾ حكاية لما شاع بينهم من اسمه؛ فلا يحمل التنكير وحده على معنى واحد جازم.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص578–582.","url":""}]},{"id":"s21-63","number":63,"surah":21,"verses":[63],"verseLabel":"الأنبياء: 63","question":"ما سرّ التعبير في قول إبراهيم ﴿بَلْ فَعَلَهُ كَبِيرُهُمْ هَذَا فَاسْأَلُوهُمْ﴾؟","answer":"الكلام إلزام حجاجي على تقدير دعواهم، لا إقرار بأن الصنم فعل؛ ولذلك أعقبه ﴿فاسألوهم إن كانوا ينطقون﴾ ليظهر عجزهم وتناقض عبادتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص592–597.","url":""}]},{"id":"s21-64","number":64,"surah":21,"verses":[64],"verseLabel":"الأنبياء: 64","question":"ما سرّ التعبير بـ﴿فَرَجَعُوا إِلَى أَنْفُسِهِمْ﴾؟","answer":"عادوا لحظة إلى حكم العقل الداخلي واعترفوا بظلمهم قبل أن يغلبهم التقليد.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص598–601.","url":""}]},{"id":"s21-65","number":65,"surah":21,"verses":[65],"verseLabel":"الأنبياء: 65","question":"ما سرّ التعبير بـ﴿ثُمَّ نُكِسُوا عَلَى رُءُوسِهِمْ﴾؟","answer":"صورة انقلاب بعد وضوح الحق؛ رجعوا من اعتراف العقل إلى المكابرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص602–607.","url":""}]},{"id":"s21-66","number":66,"surah":21,"verses":[68],"verseLabel":"الأنبياء: 68","question":"ما سرّ التعبير في قولهم ﴿حَرِّقُوهُ وَانْصُرُوا آلِهَتَكُمْ﴾؟","answer":"حين عجزت الآلهة عن نفسها طلبت نصرة البشر، ففضحت صيحتهم بطلانها.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص621–625.","url":""}]},{"id":"s21-67","number":67,"surah":21,"verses":[69],"verseLabel":"الأنبياء: 69","question":"ما سرّ التعبير بـ﴿يَا نَارُ كُونِي بَرْدًا وَسَلَامًا﴾؟","answer":"قُيد البرد بالسلام لأن شدة البرد قد تؤذي كما تؤذي النار؛ فصار بردًا نافعًا سالمًا على إبراهيم، بأمر الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص626–630.","url":""}]},{"id":"s21-68","number":68,"surah":21,"verses":[70],"verseLabel":"الأنبياء: 70","question":"ما سرّ وصفهم بـ﴿الْأَخْسَرِينَ﴾ هنا، وبـ﴿الْأَسْفَلِينَ﴾ في الصافات؟","answer":"ناسب ﴿الأخسرين﴾ في الأنبياء ذكر الكيد الذي انقلب عليهم بالخسران، وناسب ﴿الأسفلين﴾ في الصافات بناءهم البنيان العالي وإرادتهم إلقاءه منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص631–635.","url":""}]},{"id":"s21-69","number":69,"surah":21,"verses":[71],"verseLabel":"الأنبياء: 71","question":"ما سرّ وصف أرض الشام بأنها ﴿الَّتِي بَارَكْنَا فِيهَا لِلْعَالَمِينَ﴾؟","answer":"عم بركتها الدينية والدنيوية، وجعل نجاة إبراهيم انتقالًا إلى مركز رسالات.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص636–640.","url":""}]},{"id":"s21-70","number":70,"surah":21,"verses":[73],"verseLabel":"الأنبياء: 73","question":"ما سرّ التعبير بـ﴿وَجَعَلْنَاهُمْ أَئِمَّةً يَهْدُونَ بِأَمْرِنَا﴾؟","answer":"الهداية ليست بآرائهم؛ قيادتهم تابعة لوحي الله وأمره.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص648–664.","url":""}]},{"id":"s21-71","number":71,"surah":21,"verses":[74],"verseLabel":"الأنبياء: 74","question":"ما سرّ وصف قوم لوط بأنهم ﴿قَوْمَ سَوْءٍ فَاسِقِينَ﴾؟","answer":"جعل السوء سمت جماعتهم، والفسق خروجهم المتعمد عن الفطرة والحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص665–685.","url":""}]},{"id":"s21-72","number":72,"surah":21,"verses":[76],"verseLabel":"الأنبياء: 76","question":"ما سرّ التعبير في قصة نوح بـ﴿فَاسْتَجَبْنَا لَهُ﴾ بعد ﴿إِذْ نَادَى﴾؟","answer":"الفاء تصل الدعاء بالإجابة وتصور قرب الفرج بعد طول البلاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص686–697.","url":""}]},{"id":"s21-73","number":73,"surah":21,"verses":[78],"verseLabel":"الأنبياء: 78","question":"لماذا خُص داود وسليمان بحكم الحرث؟","answer":"عرضت قصة الحكم لإظهار تفاوت الفهم في الاجتهاد؛ فخص سليمان بالتفهيم، ثم أثبت لداود وسليمان معًا الحكم والعلم حتى لا يفهم من إصابة أحدهما انتقاص الآخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص706–717.","url":""}]},{"id":"s21-74","number":74,"surah":21,"verses":[79],"verseLabel":"الأنبياء: 79","question":"ما سرّ التعبير بـ﴿فَفَهَّمْنَاهَا سُلَيْمَانَ وَكُلًّا آتَيْنَا حُكْمًا وَعِلْمًا﴾؟","answer":"أثبت إصابة سليمان دون انتقاص داود؛ الجميع أوتي علمًا وحكمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص718–730.","url":""}]},{"id":"s21-75","number":75,"surah":21,"verses":[80],"verseLabel":"الأنبياء: 80","question":"لماذا سماها ﴿صَنْعَةَ لَبُوسٍ﴾؟","answer":"«اللبوس» ما يلبس للحماية، والصنعة تعلم دقة تحويل الحديد إلى درع.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص731–741.","url":""}]},{"id":"s21-76","number":76,"surah":21,"verses":[81],"verseLabel":"الأنبياء: 81","question":"لماذا وُصفت الريح بأنها ﴿عَاصِفَةً﴾ وهي تجري بأمر سليمان؟","answer":"قوية سريعة مع انقيادها الدقيق؛ جمع الشدة والطاعة في آية واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص742–753.","url":""}]},{"id":"s21-77","number":77,"surah":21,"verses":[83],"verseLabel":"الأنبياء: 83","question":"ما سرّ التعبير في قول أيوب ﴿مَسَّنِيَ الضُّرُّ﴾؟","answer":"اقتصر أيوب على أن الضر مسه، وهو ألطف من وصف الإحاطة والاستيلاء، ثم أثنى على الله بـ﴿أرحم الراحمين﴾ من غير تصريح بطلب؛ فجمع الأدب والرجاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص763–777.","url":""}]},{"id":"s21-78","number":78,"surah":21,"verses":[84],"verseLabel":"الأنبياء: 84","question":"ما سرّ التعبير بـ﴿رَحْمَةً مِنْ عِنْدِنَا﴾ هنا، وبـ﴿رَحْمَةً مِنَّا﴾ في سورة ص؟","answer":"زيادة ﴿عند﴾ هنا تفيد عناية خاصة بمصدر الرحمة وصدورها من خزائن فضل الله، وناسبت مقام تفصيل الاستجابة؛ أما آية ص فجاءت على الإيجاز بـ﴿منا﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص763–777.","url":""}]},{"id":"s21-79","number":79,"surah":21,"verses":[87],"verseLabel":"الأنبياء: 87","question":"ما سرّ وصف يونس بـ﴿ذَا النُّونِ﴾؟","answer":"نسبه إلى الحوت الذي صار ظرف محنته وآية نجاته، فاستحضر القصة بكلمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص785–802.","url":""}]},{"id":"s21-80","number":80,"surah":21,"verses":[87],"verseLabel":"الأنبياء: 87","question":"ما سرّ التعبير بـ﴿فَظَنَّ أَنْ لَنْ نَقْدِرَ عَلَيْهِ﴾؟","answer":"﴿نقدر﴾ هنا بمعنى نضيق ونقتر، أي ظن ألا نضيق عليه أو نحبسه؛ وليس معناها الشك في قدرة الله، وهو معنى باطل في حق النبي.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص785–802.","url":""}]},{"id":"s21-81","number":81,"surah":21,"verses":[87],"verseLabel":"الأنبياء: 87","question":"لماذا جمع دعاؤه بين التوحيد والتسبيح والاعتراف؟","answer":"جمع الدعاء التوحيد في ﴿لا إله إلا أنت﴾، والتنزيه في ﴿سبحانك﴾، والاعتراف بالتقصير في ﴿إني كنت من الظالمين﴾؛ فكان دعاء توبة وتفويض.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص785–802.","url":""}]},{"id":"s21-82","number":82,"surah":21,"verses":[88],"verseLabel":"الأنبياء: 88","question":"ما سرّ التعبير بـ﴿وَكَذَلِكَ نُنْجِي الْمُؤْمِنِينَ﴾؟","answer":"حوّل نجاة يونس من قصة خاصة إلى وعد عام لمن يصدق ويلجأ إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص785–802.","url":""}]},{"id":"s21-83","number":83,"surah":21,"verses":[89],"verseLabel":"الأنبياء: 89","question":"ما سرّ التعبير في قول زكريا ﴿وَأَنْتَ خَيْرُ الْوَارِثِينَ﴾؟","answer":"طلب الولد مع تفويض العاقبة؛ إن بقي وحيدًا فالله خير من يبقى بعد الجميع.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص10–27.","url":""}]},{"id":"s21-84","number":84,"surah":21,"verses":[90],"verseLabel":"الأنبياء: 90","question":"ما سرّ وصف الأنبياء بأنهم ﴿يُسَارِعُونَ فِي الْخَيْرَاتِ﴾؟","answer":"لا يعملون الخير فقط بل يبادرون إليه قبل الفوات، جامعِين الرجاء والخوف والخشوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص10–27.","url":""}]},{"id":"s21-85","number":85,"surah":21,"verses":[91],"verseLabel":"الأنبياء: 91","question":"ما سرّ التعبير عن مريم وابنها بـ﴿وَجَعَلْنَاهَا وَابْنَهَا آيَةً لِلْعَالَمِينَ﴾ بالإفراد؟","answer":"أفرد ﴿آية﴾ لأن مريم وابنها اشتركا في آية واحدة هي ولادته من غير أب، فكل منهما جزء من دلالة المعجزة الواحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص28–39.","url":""}]},{"id":"s21-86","number":86,"surah":21,"verses":[92],"verseLabel":"الأنبياء: 92","question":"ما سرّ التعبير بـ﴿إِنَّ هَذِهِ أُمَّتُكُمْ أُمَّةً وَاحِدَةً﴾ بعد قصص الأنبياء؟","answer":"تعدد الأشخاص والابتلاءات يعود إلى دين واحد ورب واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص40–50.","url":""}]},{"id":"s21-87","number":87,"surah":21,"verses":[93],"verseLabel":"الأنبياء: 93","question":"ما سرّ التعبير بـ﴿وَتَقَطَّعُوا أَمْرَهُمْ بَيْنَهُمْ﴾؟","answer":"جعل الدين كشيء واحد مزقوه قطعًا، فالتفرق فعلهم لا أصل الرسالات.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص51–78.","url":""}]},{"id":"s21-88","number":88,"surah":21,"verses":[95],"verseLabel":"الأنبياء: 95","question":"ما سرّ التعبير بـ﴿وَحَرَامٌ عَلَى قَرْيَةٍ أَهْلَكْنَاهَا أَنَّهُمْ لَا يَرْجِعُونَ﴾؟","answer":"في الآية قراءتان وتوجيهات: على قراءة الفتح يكون المعنى امتناع رجوع المهلكين إلى الدنيا، وعلى قراءة الكسر أو بعض التخريجات يتأكد رجوعهم للبعث؛ لذلك لا يعتمد جواب واحد دون بيان الخلاف.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص51–78.","url":""}]},{"id":"s21-89","number":89,"surah":21,"verses":[96],"verseLabel":"الأنبياء: 96","question":"ما سرّ التعبير بـ﴿وَهُمْ مِنْ كُلِّ حَدَبٍ يَنْسِلُونَ﴾؟","answer":"الحدب كل مرتفع، والنسلان إسراع؛ يصور كثرة يأجوج ومأجوج وانتشارهم المندفع.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص79–98.","url":""}]},{"id":"s21-90","number":90,"surah":21,"verses":[97],"verseLabel":"الأنبياء: 97","question":"ما سرّ التعبير بـ﴿فَإِذَا هِيَ شَاخِصَةٌ أَبْصَارُ الَّذِينَ كَفَرُوا﴾؟","answer":"«إذا» للمفاجأة، وشخوص البصر ثباته من الهول بلا طرف.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص79–98.","url":""}]},{"id":"s21-91","number":91,"surah":21,"verses":[98],"verseLabel":"الأنبياء: 98","question":"لماذا صارت الأصنام وعابدوها ﴿حَصَبُ جَهَنَّمَ﴾؟","answer":"الحصب ما يلقى في النار وقودًا؛ انقلب المعبود الذي طلبوا قربه مادة لعذابهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص99–115.","url":""}]},{"id":"s21-92","number":92,"surah":21,"verses":[99],"verseLabel":"الأنبياء: 99","question":"لماذا احتج بأن الآلهة لو كانت حقًا ما وردت النار؟","answer":"العاجز عن نجاة نفسه من النار أبعد عن إنقاذ عابديه.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص99–115.","url":""}]},{"id":"s21-93","number":93,"surah":21,"verses":[100],"verseLabel":"الأنبياء: 100","question":"ما سرّ التعبير بـ﴿لَهُمْ فِيهَا زَفِيرٌ وَهُمْ فِيهَا لَا يَسْمَعُونَ﴾؟","answer":"دل الجمع بين الزفير وعدم السماع على شدة عذابهم وانقطاع ما يسرهم؛ وقيل لا يسمعون خطابًا ينفعهم أو لشدة الهول، فلا يجزم بتفسير العزلة الحسية وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص99–115.","url":""}]},{"id":"s21-94","number":94,"surah":21,"verses":[101],"verseLabel":"الأنبياء: 101","question":"ما سرّ التعبير بـ﴿إِنَّ الَّذِينَ سَبَقَتْ لَهُمْ مِنَّا الْحُسْنَى﴾؟","answer":"استثنى عباد الله الصالحين الذين عُبدوا بغير رضاهم؛ وعدهم السابق يحفظهم من النار.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص116–124.","url":""}]},{"id":"s21-95","number":95,"surah":21,"verses":[103],"verseLabel":"الأنبياء: 103","question":"لماذا تتلقاهم الملائكة بقول ﴿هَذَا يَوْمُكُمُ الَّذِي كُنْتُمْ تُوعَدُونَ﴾؟","answer":"تحول الوعد الغائب إلى يوم حاضر مضاف إليهم تكريمًا وطمأنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص132–138.","url":""}]},{"id":"s21-96","number":96,"surah":21,"verses":[104],"verseLabel":"الأنبياء: 104","question":"لماذا شُبه طي السماء بطي السجل للكتب؟","answer":"صورة محسوسة لسهولة جمع هذا الكون الهائل عند القدرة الإلهية.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص139–149.","url":""}]},{"id":"s21-97","number":97,"surah":21,"verses":[104],"verseLabel":"الأنبياء: 104","question":"ما سرّ التعبير بـ﴿كَمَا بَدَأْنَا أَوَّلَ خَلْقٍ نُعِيدُهُ﴾؟","answer":"البدء برهان الإعادة؛ من أنشأ الخلق أولًا يعيده بلا عجز.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص139–149.","url":""}]},{"id":"s21-98","number":98,"surah":21,"verses":[105],"verseLabel":"الأنبياء: 105","question":"ما سرّ التعبير بـ﴿أَنَّ الْأَرْضَ يَرِثُهَا عِبَادِيَ الصَّالِحُونَ﴾؟","answer":"أخبر أن الأرض تكون ميراثًا لعباد الله الصالحين؛ أي إن العاقبة والتمكين الموعود للصلاح، وذُكرت في تعيين الأرض أقوال، فلا يحصر اللفظ في أرض الدنيا وحدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص150–157.","url":""}]},{"id":"s21-99","number":99,"surah":21,"verses":[106],"verseLabel":"الأنبياء: 106","question":"ما سرّ التعبير بـ﴿إِنَّ فِي هَذَا لَبَلَاغًا لِقَوْمٍ عَابِدِينَ﴾؟","answer":"﴿بلاغًا﴾ كفايةً وسببًا موصلًا إلى المقصود، وخص القوم العابدين لأنهم المنتفعون بما تقدم من الوعد والوعيد والدلائل.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص158–162.","url":""}]},{"id":"s21-100","number":100,"surah":21,"verses":[107],"verseLabel":"الأنبياء: 107","question":"ما سرّ التعبير بـ﴿وَمَا أَرْسَلْنَاكَ إِلَّا رَحْمَةً لِلْعَالَمِينَ﴾؟","answer":"جعلت الرسالة نفسها رحمة عامة؛ بهداية من آمن، وقيام الحجة على من كفر، وتأخير الاستئصال، وما جاءت به الشريعة من مصالح العالمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص163–166.","url":""}]},{"id":"s21-101","number":101,"surah":21,"verses":[108],"verseLabel":"الأنبياء: 108","question":"ما سرّ التعبير بـ﴿فَهَلْ أَنْتُمْ مُسْلِمُونَ﴾ بعد إعلان الإله الواحد؟","answer":"جاء الاستفهام بعد حصر الوحي في التوحيد لينقل المخاطبين من سماع الخبر إلى إعلان موقفهم: هل ينقادون لله وحده؟","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص167–172.","url":""}]},{"id":"s21-102","number":102,"surah":21,"verses":[109],"verseLabel":"الأنبياء: 109","question":"ما سرّ التعبير بـ﴿آذَنْتُكُمْ عَلَى سَوَاءٍ﴾؟","answer":"﴿آذنتكم﴾ أعلمتكم، و﴿على سواء﴾ تفيد استواءهم في بلوغ الإنذار أو استواء الفريقين في العلم بانتهاء المسالمة؛ فلا خديعة ولا إخفاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص173–179.","url":""}]},{"id":"s21-103","number":103,"surah":21,"verses":[111],"verseLabel":"الأنبياء: 111","question":"ما سرّ التعبير بـ﴿وَإِنْ أَدْرِي لَعَلَّهُ فِتْنَةٌ لَكُمْ وَمَتَاعٌ إِلَى حِينٍ﴾؟","answer":"جعل تأخير العذاب محتملًا أن يكون اختبارًا لهم ومتاعًا مؤقتًا، فلا يدل الإمهال على الرضا، والنبي لا يعلم ميقاته إلا بوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص185–188.","url":""}]},{"id":"s21-104","number":104,"surah":21,"verses":[112],"verseLabel":"الأنبياء: 112","question":"لماذا ختمت السورة بـ﴿رَبِّ احْكُمْ بِالْحَقِّ﴾؟","answer":"ختم بالدعاء إلى حكم الله بالحق بعد تمام البلاغ، ثم الاستعانة بالرحمن على ما يصفه المكذبون؛ فجمع التفويض وطلب النصر.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص189–200.","url":""}]},{"id":"s21-105","number":105,"surah":21,"verses":[33],"verseLabel":"الأنبياء: 33","question":"ما سرّ التعبير عن الشمس والقمر ﴿كلٌّ في فلك يسبحون﴾ بالجمع، ولم يقل: يسبح؟","answer":"يجوز في ﴿كل﴾ المقطوعة عن الإضافة مراعاة لفظها أو معناها؛ وجاء ﴿يسبحون﴾ جمعًا بالنظر إلى مجموع الأجرام المذكورة، مع كون كل واحد في فلكه.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص306–314.","url":""}]},{"id":"s22-1","number":1,"surah":22,"verses":[1],"verseLabel":"الحج: 1","question":"لماذا افتتحت السورة بنداء ﴿يَا أَيُّهَا النَّاسُ﴾ لا المؤمنين؟","answer":"هول القيامة وحجتها خطاب للإنسانية كلها قبل تفصيل مواقف الإيمان والكفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص209–218.","url":""}]},{"id":"s22-2","number":2,"surah":22,"verses":[1],"verseLabel":"الحج: 1","question":"ما سرّ التعبير بـ﴿إِنَّ زَلْزَلَةَ السَّاعَةِ شَيْءٌ عَظِيمٌ﴾؟","answer":"نكّر «شيء» ثم وصفه بالعظم ليجعلها فوق كل ما يدخل تحت تصور الأشياء.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص209–218.","url":""}]},{"id":"s22-3","number":3,"surah":22,"verses":[2],"verseLabel":"الحج: 2","question":"ما سرّ الانتقال من خطاب الجمع في ﴿تَرَوْنَهَا﴾ إلى خطاب المفرد في ﴿وَتَرَى النَّاسَ سُكَارَى﴾؟","answer":"خوطب الجميع أولًا بمشاهدة الزلزلة، ثم أفرد الخطاب لاستحضار كل سامع مشهد الناس كأنه يراه بنفسه؛ فانتقل من عموم الحضور إلى خصوص المعاينة.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص219–233.","url":""}]},{"id":"s22-4","number":4,"surah":22,"verses":[2],"verseLabel":"الحج: 2","question":"ما سرّ التعبير بـ﴿وَمَا هُمْ بِسُكَارَى﴾ بعد وصفهم بالسكر؟","answer":"نفى سكر الخمر وأثبت هيئة الذهول؛ العذاب أفقدهم التوازن وهم واعون بالهول.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص219–233.","url":""}]},{"id":"s22-5","number":5,"surah":22,"verses":[3],"verseLabel":"الحج: 3","question":"ما سرّ التعبير بـ﴿وَمِنَ النَّاسِ مَنْ يُجَادِلُ فِي اللَّهِ بِغَيْرِ عِلْمٍ﴾؟","answer":"جعل الجدل في أعظم الحقائق قائمًا بلا علم، ثم كشف قائده: كل شيطان مريد.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص234–247.","url":""}]},{"id":"s22-6","number":6,"surah":22,"verses":[4],"verseLabel":"الحج: 4","question":"ما سرّ تسمية إضلال الشيطان هدايةً في ﴿وَيَهْدِيهِ إِلَى عَذَابِ السَّعِيرِ﴾؟","answer":"سمى إيصال الشيطان تابعه إلى السعير هدايةً على سبيل التهكم أو المشاكلة؛ فهو يدله فعلًا، لكن إلى غاية الهلاك لا النجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص234–247.","url":""}]},{"id":"s22-7","number":7,"surah":22,"verses":[5],"verseLabel":"الحج: 5","question":"لماذا فُصلت أطوار خلق الإنسان عند الشك في البعث؟","answer":"تحول الخلق المشاهد من تراب ونطفة إلى إنسان حجة عملية على إمكان الإعادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص248–275.","url":""}]},{"id":"s22-8","number":8,"surah":22,"verses":[5],"verseLabel":"الحج: 5","question":"ما سرّ التعبير بـ﴿مُخَلَّقَةٍ وَغَيْرِ مُخَلَّقَةٍ﴾؟","answer":"ذُكرت في ﴿مخلقة وغير مخلقة﴾ أقوال، منها تامة الخلق وغير تامته، أو المصورة وغير المصورة؛ والمقصود إظهار تصرف القدرة في أطوار الجنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص248–275.","url":""}]},{"id":"s22-9","number":9,"surah":22,"verses":[5],"verseLabel":"الحج: 5","question":"ما سرّ التعبير بـ﴿لِكَيْلَا يَعْلَمَ مِنْ بَعْدِ عِلْمٍ شَيْئًا﴾؟","answer":"رد الشيخ إلى ضعف الإدراك بعد قوته، فيرى الإنسان أن قدرته وعلمه عارية قابلة للسلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص248–275.","url":""}]},{"id":"s22-10","number":10,"surah":22,"verses":[5],"verseLabel":"الحج: 5","question":"ما سرّ وصف الأرض قبل المطر بأنها ﴿هَامِدَةً﴾؟","answer":"شبهها بجسد ساكن لا أثر للحياة فيه، ثم اهتزازه بعد الماء صورة للبعث.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص248–275.","url":""}]},{"id":"s22-11","number":11,"surah":22,"verses":[5],"verseLabel":"الحج: 5","question":"ما سرّ التعبير بـ﴿اهْتَزَّتْ وَرَبَتْ وَأَنْبَتَتْ﴾؟","answer":"رتب حركة الأرض وانتفاخها ثم خروج النبات؛ مشهد حياة يتصاعد أمام العين.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص248–275.","url":""}]},{"id":"s22-12","number":12,"surah":22,"verses":[6],"verseLabel":"الحج: 6","question":"لماذا تكررت ﴿وَأَنَّ﴾ في نتائج الدليل؟","answer":"لتفصل الحقائق الكبرى وتثبت كل واحدة: حقية الله والبعث والقدرة والساعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص276–295.","url":""}]},{"id":"s22-13","number":13,"surah":22,"verses":[7],"verseLabel":"الحج: 7","question":"ما سرّ التعبير بـ﴿لَا رَيْبَ فِيهَا﴾ بعد ﴿آتِيَةٌ﴾؟","answer":"أثبت وقوعها ثم نفى كل موجب للشك فيها، فجمع الإيجاب وسلب التردد.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص276–295.","url":""}]},{"id":"s22-14","number":14,"surah":22,"verses":[8],"verseLabel":"الحج: 8","question":"لماذا جمع ﴿بِغَيْرِ عِلْمٍ وَلَا هُدًى وَلَا كِتَابٍ مُنِيرٍ﴾؟","answer":"نُفيت عنه مصادر الحجة: علم يدركه، وهدى يتبعه، وكتاب منير يستند إليه؛ فجداله عارٍ من العقل والنقل.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص296–313.","url":""}]},{"id":"s22-15","number":15,"surah":22,"verses":[9],"verseLabel":"الحج: 9","question":"ما سرّ التعبير بـ﴿ثَانِيَ عِطْفِهِ﴾؟","answer":"صورة لمن يلوي جانبه ورقبته كبرًا، فيظهر الإعراض على جسده.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص296–313.","url":""}]},{"id":"s22-16","number":16,"surah":22,"verses":[10],"verseLabel":"الحج: 10","question":"ما سرّ التعبير بـ﴿ذَلِكَ بِمَا قَدَّمَتْ يَدَاكَ﴾؟","answer":"نسب العمل لليدين لأنهما آلة معظم الفعل، وأفرد الخطاب ليواجه كل مجرم بمسؤوليته.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص314–323.","url":""}]},{"id":"s22-17","number":17,"surah":22,"verses":[11],"verseLabel":"الحج: 11","question":"ما سرّ التعبير بـ﴿يَعْبُدُ اللَّهَ عَلَى حَرْفٍ﴾؟","answer":"شبهه بمن يقف على طرف غير ثابت؛ أقل فتنة تسقطه خارج العبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص324–338.","url":""}]},{"id":"s22-18","number":18,"surah":22,"verses":[11],"verseLabel":"الحج: 11","question":"ما سرّ تسمية الارتداد ﴿انْقَلَبَ عَلَى وَجْهِهِ﴾؟","answer":"صورة سقوط كامل على أشرف موضع، بعد أن كان ينبغي أن يتجه به إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص324–338.","url":""}]},{"id":"s22-19","number":19,"surah":22,"verses":[12],"verseLabel":"الحج: 12","question":"ما سرّ وصف الصنم بـ﴿مَا لَا يَضُرُّهُ وَمَا لَا يَنْفَعُهُ﴾؟","answer":"نفى طرفي القدرة؛ لا يخشى منه ضر ولا يرجى منه نفع.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص339–352.","url":""}]},{"id":"s22-20","number":20,"surah":22,"verses":[13],"verseLabel":"الحج: 13","question":"كيف يكون ضر المعبود ﴿أَقْرَبُ مِنْ نَفْعِهِ﴾ مع نفي نفعه قبل ذلك؟","answer":"نفع المعبود المزعوم معدوم، أما الضر الناشئ من عبادته فواقع؛ فجاءت المقارنة على حسب زعم العابد أو للتهكم بوهم النفع.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص339–352.","url":""}]},{"id":"s22-21","number":21,"surah":22,"verses":[15],"verseLabel":"الحج: 15","question":"ما دلالة الأمر بأن يمد الشاك سببًا إلى السماء ثم يقطع؟","answer":"في الآية تفسيران مشهوران: أن يختنق بحبل إلى سقف بيته، أو أن يطلب بلوغ السماء لقطع الوحي؛ وكلاهما تمثيل لعجز الساخط عن منع نصر الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص362–373.","url":""}]},{"id":"s22-22","number":22,"surah":22,"verses":[16],"verseLabel":"الحج: 16","question":"ما سرّ التعبير بـ﴿أَنْزَلْنَاهُ آيَاتٍ بَيِّنَاتٍ﴾؟","answer":"جعل الوحي آيات متعددة واضحة، والهداية بعد البيان لمن يفتح الله قلبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص374–382.","url":""}]},{"id":"s22-23","number":23,"surah":22,"verses":[17],"verseLabel":"الحج: 17","question":"لماذا عُدّدت الطوائف ثم قيل ﴿اللَّهُ يَفْصِلُ بَيْنَهُمْ﴾؟","answer":"تعدد الملل في الدنيا ينتهي إلى حكم واحد يكشف الحق يوم القيامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص383–400.","url":""}]},{"id":"s22-24","number":24,"surah":22,"verses":[18],"verseLabel":"الحج: 18","question":"لماذا نسب السجود إلى الشمس والقمر والجبال والشجر والدواب؟","answer":"سجود يناسب خلقها بانقيادها لنظام الله، فيقابل خضوع الكون امتناع بعض البشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص401–425.","url":""}]},{"id":"s22-25","number":25,"surah":22,"verses":[18],"verseLabel":"الحج: 18","question":"ما سرّ التعبير بـ﴿وَكَثِيرٌ مِنَ النَّاسِ وَكَثِيرٌ حَقَّ عَلَيْهِ الْعَذَابُ﴾؟","answer":"عم سجود الانقياد مخلوقات الكون، ثم انقسم الناس إلى كثير يسجد اختيارًا وكثير استحق العذاب بإبائه؛ فليس التقدير أن جميع الناس في قسم واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص401–425.","url":""}]},{"id":"s22-26","number":26,"surah":22,"verses":[19],"verseLabel":"الحج: 19","question":"ما سرّ الجمع في ﴿هَذَانِ خَصْمَانِ اخْتَصَمُوا فِي رَبِّهِمْ﴾ بعد التثنية؟","answer":"ثُنّي ﴿خصمان﴾ باعتبار الفريقين، ثم جمع ﴿اختصموا﴾ باعتبار أفراد كل فريق؛ ولفظ الخصم يطلق على الواحد والجمع.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص426–453.","url":""}]},{"id":"s22-27","number":27,"surah":22,"verses":[19,20,21,22],"verseLabel":"الحج: 19-22","question":"لماذا فُصل عذاب النار بالثياب والحميم والمقامع؟","answer":"لينتقل الوعيد من لفظ عام إلى صور تحيط بالجسد ظاهره وباطنه وتمنع الهرب.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص426–453.","url":""}]},{"id":"s22-28","number":28,"surah":22,"verses":[20],"verseLabel":"الحج: 20","question":"ما سرّ التعبير بـ﴿يُصْهَرُ بِهِ مَا فِي بُطُونِهِمْ وَالْجُلُودُ﴾؟","answer":"استوعب أثر الحميم الداخل والخارج؛ لا يبقى موضع بعيد عن العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص426–453.","url":""}]},{"id":"s22-29","number":29,"surah":22,"verses":[22],"verseLabel":"الحج: 22","question":"لماذا أُعيدوا إلى النار كلما أرادوا الخروج؟","answer":"الإرادة نفسها لا تبلغ فعلًا؛ كل محاولة تقابلها الإعادة وذوق الحريق.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص426–453.","url":""}]},{"id":"s22-30","number":30,"surah":22,"verses":[23],"verseLabel":"الحج: 23","question":"لماذا جمع نعيم الجنة بين الأساور واللؤلؤ والحرير؟","answer":"استوعب زينة اليد والجسد واللباس في مقابلة ثياب النار ومقامع الحديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص454–467.","url":""}]},{"id":"s22-31","number":31,"surah":22,"verses":[24],"verseLabel":"الحج: 24","question":"ما سرّ التعبير بـ﴿هُدُوا إِلَى الطَّيِّبِ مِنَ الْقَوْلِ وَهُدُوا إِلَى صِرَاطِ الْحَمِيدِ﴾؟","answer":"جمع طيب اللسان واستقامة الطريق، وكرر الهداية لأن كل نعمة منهما مستقلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص468–476.","url":""}]},{"id":"s22-32","number":32,"surah":22,"verses":[25],"verseLabel":"الحج: 25","question":"لماذا ساوى في المسجد الحرام بين ﴿الْعَاكِفِ فِيهِ وَالْبَادِ﴾؟","answer":"حرم الله حق للعبادة لا يحتكره المقيم دون القادم.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص477–490.","url":""}]},{"id":"s22-33","number":33,"surah":22,"verses":[25],"verseLabel":"الحج: 25","question":"ما سرّ التعبير بـ﴿بِإِلْحَادٍ بِظُلْمٍ﴾؟","answer":"الباء الأولى للمصاحبة أو الملابسة، والثانية للسببية أو البيان عند المفسرين؛ والمعنى تهديد من يرد في الحرم ميلًا عن الحق متلبسًا بظلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص477–490.","url":""}]},{"id":"s22-34","number":34,"surah":22,"verses":[26],"verseLabel":"الحج: 26","question":"ما سرّ تقديم قوله لإبراهيم ﴿لَا تُشْرِكْ بِي شَيْئًا﴾ قبل تطهير البيت؟","answer":"طهارة العقيدة أصل طهارة المكان، فلا معنى لبيت مقدس مع عبادة غير صاحبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص491–502.","url":""}]},{"id":"s22-35","number":35,"surah":22,"verses":[26],"verseLabel":"الحج: 26","question":"لماذا رتب ﴿الطَّائِفِينَ وَالْقَائِمِينَ وَالرُّكَّعِ السُّجُودِ﴾؟","answer":"جمع عبادات الحركة والثبات وأركان الصلاة، وانتقل من القيام إلى الركوع والسجود.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص491–502.","url":""}]},{"id":"s22-36","number":36,"surah":22,"verses":[27],"verseLabel":"الحج: 27","question":"ما سرّ التعبير بـ﴿وَأَذِّنْ فِي النَّاسِ بِالْحَجِّ﴾؟","answer":"النداء من عبد واحد، والتبليغ إلى الناس على الله؛ فبلغ عبر الأجيال.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص503–512.","url":""}]},{"id":"s22-37","number":37,"surah":22,"verses":[27],"verseLabel":"الحج: 27","question":"ما سرّ التعبير بـ﴿يَأْتِينَ مِنْ كُلِّ فَجٍّ عَمِيقٍ﴾؟","answer":"وصف الفج بـ﴿عميق﴾ لأن البعد يرى في امتداد الطريق وانخفاضه، وهو من التعبير عن البعد بالعمق؛ فاستحضر مشقة المجيء من الآفاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص503–512.","url":""}]},{"id":"s22-38","number":38,"surah":22,"verses":[28],"verseLabel":"الحج: 28","question":"ما سرّ التعبير بـ﴿لِيَشْهَدُوا مَنَافِعَ لَهُمْ﴾ ولم يحددها؟","answer":"لتعم منافع الدين والدنيا والاجتماع والذكر والتجارة، فلا يحصر الحج في وجه واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص513–523.","url":""}]},{"id":"s22-39","number":39,"surah":22,"verses":[29],"verseLabel":"الحج: 29","question":"ما سرّ التعبير بـ﴿ثُمَّ لْيَقْضُوا تَفَثَهُمْ﴾؟","answer":"«ثم» للانتقال بعد النحر إلى إزالة آثار الإحرام وإتمام النسك.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص524–529.","url":""}]},{"id":"s22-40","number":40,"surah":22,"verses":[30],"verseLabel":"الحج: 30","question":"لماذا قرن تعظيم الحرمات باجتناب ﴿قَوْلَ الزُّورِ﴾؟","answer":"طهارة النسك لا تتم مع تدنيس اللسان؛ والزور يشمل الشرك والكذب.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص530–540.","url":""}]},{"id":"s22-41","number":41,"surah":22,"verses":[31],"verseLabel":"الحج: 31","question":"لماذا شبه المشرك بمن خر من السماء فتخطفه الطير أو تهوي به الريح؟","answer":"شبه حال المشرك بمن سقط من السماء فتخطفته الطير أو ألقت به الريح في مكان بعيد؛ صورة تمثيلية للتشتت والهلاك بعد مفارقة التوحيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص541–558.","url":""}]},{"id":"s22-42","number":42,"surah":22,"verses":[32],"verseLabel":"الحج: 32","question":"لماذا جعل تعظيم الشعائر ﴿مِنْ تَقْوَى الْقُلُوبِ﴾؟","answer":"التعظيم الظاهر الصادق أثر لهيبة الله في الداخل؛ القلب أصل قيمة الشعيرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص559–573.","url":""}]},{"id":"s22-43","number":43,"surah":22,"verses":[34],"verseLabel":"الحج: 34","question":"ما سرّ التعبير بـ﴿وَلِكُلِّ أُمَّةٍ جَعَلْنَا مَنْسَكًا﴾؟","answer":"تنوع صور الشرائع لا يغير غايتها الواحدة: ذكر اسم الله والخضوع له.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص574–599.","url":""}]},{"id":"s22-44","number":44,"surah":22,"verses":[35],"verseLabel":"الحج: 35","question":"ما سرّ وصف المخبتين بوجل القلب والصبر وإقامة الصلاة والإنفاق؟","answer":"جمع انفعال القلب عند الذكر وثباته عند البلاء وعمل البدن والمال.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص574–599.","url":""}]},{"id":"s22-45","number":45,"surah":22,"verses":[36],"verseLabel":"الحج: 36","question":"ما سرّ تسمية البدن ﴿مِنْ شَعَائِرِ اللَّهِ﴾؟","answer":"جُعلت البدن من شعائر الله لأنها أعلام ظاهرة للنسك والطاعة، لا لمجرد الانتفاع بلحومها؛ فتعظيمها متصل بتعظيم أمر الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص600–614.","url":""}]},{"id":"s22-46","number":46,"surah":22,"verses":[36],"verseLabel":"الحج: 36","question":"ما سرّ التعبير بـ﴿فَإِذَا وَجَبَتْ جُنُوبُهَا﴾؟","answer":"كنّى بوقوع جنوبها عن تمام نحرها، فاختار صورة رفيقة لا لفظًا خشنًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص600–614.","url":""}]},{"id":"s22-47","number":47,"surah":22,"verses":[37],"verseLabel":"الحج: 37","question":"ما سرّ التعبير بـ﴿لَنْ يَنَالَ اللَّهَ لُحُومُهَا وَلَا دِمَاؤُهَا﴾؟","answer":"أبطل تصور القربان المادي؛ المقبول قصد التقوى والطاعة لا المادة الصاعدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص615–626.","url":""}]},{"id":"s22-48","number":48,"surah":22,"verses":[38],"verseLabel":"الحج: 38","question":"ما سرّ التعبير بـ﴿إِنَّ اللَّهَ يُدَافِعُ عَنِ الَّذِينَ آمَنُوا﴾؟","answer":"صيغة المفاعلة تصور تجدد دفع العدوان عنهم كلما تجدد.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص627–636.","url":""}]},{"id":"s22-49","number":49,"surah":22,"verses":[39],"verseLabel":"الحج: 39","question":"لماذا كانت أول علة لإذن القتال ﴿بِأَنَّهُمْ ظُلِمُوا﴾؟","answer":"ربط القوة بدفع الظلم لا بحب السيطرة، فشرع القتال حماية للحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص637–649.","url":""}]},{"id":"s22-50","number":50,"surah":22,"verses":[40],"verseLabel":"الحج: 40","question":"لماذا ذكرت الصوامع والبيع والصلوات والمساجد؟","answer":"لأن دفع العدوان يحمي أصل حرية عبادة الله، لا جماعة المسلمين وحدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص650–679.","url":""}]},{"id":"s22-51","number":51,"surah":22,"verses":[40],"verseLabel":"الحج: 40","question":"ما سرّ التعبير بـ﴿يُذْكَرُ فِيهَا اسْمُ اللَّهِ كَثِيرًا﴾؟","answer":"الضمير في ﴿فيها﴾ يعود إلى دور العبادة المذكورة، والمعنى كثرة ذكر الله فيها؛ وهو تعليل لحمايتها من الهدم، مع اختلاف شرائع أهلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص650–679.","url":""}]},{"id":"s22-52","number":52,"surah":22,"verses":[41],"verseLabel":"الحج: 41","question":"ما سرّ تقديم الصلاة والزكاة على الأمر والنهي؟","answer":"إصلاح النفس والمال أساس القدرة على إصلاح المجتمع بالمعروف.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص680–697.","url":""}]},{"id":"s22-53","number":53,"surah":22,"verses":[42,43,44],"verseLabel":"الحج: 42-44","question":"لماذا سُلّي النبي بسلسلة الأمم المكذبة؟","answer":"ليعلم أن التكذيب سنة قديمة وأن الإمهال يعقبه الأخذ مهما طال.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص698–717.","url":""}]},{"id":"s22-54","number":54,"surah":22,"verses":[45],"verseLabel":"الحج: 45","question":"ما سرّ التعبير بـ﴿فَهِيَ خَاوِيَةٌ عَلَى عُرُوشِهَا﴾؟","answer":"انهارت السقوف أولًا ثم الجدران فوقها؛ صورة خراب يقلب العمران على أصحابه.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص718–732.","url":""}]},{"id":"s22-55","number":55,"surah":22,"verses":[46],"verseLabel":"الحج: 46","question":"ما سرّ التعبير بـ﴿فَإِنَّهَا لَا تَعْمَى الْأَبْصَارُ وَلَكِنْ تَعْمَى الْقُلُوبُ﴾؟","answer":"أسند العمى إلى القلوب لأن الأبصار قد ترى الآثار، لكن العبرة والفهم محلهما القلب؛ فالمذموم عمى البصيرة لا فقد البصر الحسي.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص733–752.","url":""}]},{"id":"s22-56","number":56,"surah":22,"verses":[47],"verseLabel":"الحج: 47","question":"لماذا كان اليوم عند الله كألف سنة مما يعدون؟","answer":"المقصود أن اختلاف تقدير الأيام لا يوجب استعجال وعد الله؛ وفسر اليوم بيوم العذاب أو من أيام الآخرة، فلا يحمل على معادلة زمنية دنيوية مجردة.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص753–769.","url":""}]},{"id":"s22-57","number":57,"surah":22,"verses":[48],"verseLabel":"الحج: 48","question":"ما سرّ التعبير بـ﴿أَمْلَيْتُ لَهَا وَهِيَ ظَالِمَةٌ ثُمَّ أَخَذْتُهَا﴾؟","answer":"ذكر الظلم حال الإمهال لئلا يفهم التأخير رضا، ثم جاءت «ثم» لعاقبة لا تفلت.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص770–780.","url":""}]},{"id":"s22-58","number":58,"surah":22,"verses":[50,51],"verseLabel":"الحج: 50-51","question":"لماذا قابل المؤمنين بـ﴿رِزْقٌ كَرِيمٌ﴾ والمعاجزين بـ﴿عَذَابُ جَحِيمٍ﴾؟","answer":"الرزق نفسه مكرم دائم، والجحيم نار متأججة؛ مقابلة تجمع الجزاء ووصفه.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص788–796.","url":""}]},{"id":"s22-59","number":59,"surah":22,"verses":[52],"verseLabel":"الحج: 52","question":"لماذا يلقي الشيطان في أمنية الرسول؟","answer":"ذكرت الآية إلقاء الشيطان في أمنية الرسول ثم نسخ الله ما يلقي وإحكام آياته؛ فلا يثبت للباطل قرار في الوحي، وفي تفسير الأمنية والإلقاء أقوال يجب عدم حصرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص21–34.","url":""}]},{"id":"s22-60","number":60,"surah":22,"verses":[53],"verseLabel":"الحج: 53","question":"لماذا تصبح فتنة الشيطان مرضًا للقلب القاسي؟","answer":"المريض يتلقف الشبهة لضعفه، والقاسي يرفض الحق لجموده؛ كلاهما يبتعد بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص35–45.","url":""}]},{"id":"s22-61","number":61,"surah":22,"verses":[54],"verseLabel":"الحج: 54","question":"ما سرّ التعبير بـأهل العلم ﴿فَتُخْبِتَ لَهُ قُلُوبُهُمْ﴾؟","answer":"العلم الصحيح لا ينتهي إلى الجدل بل إلى سكون القلب وخضوعه للحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص46–56.","url":""}]},{"id":"s22-62","number":62,"surah":22,"verses":[55],"verseLabel":"الحج: 55","question":"ما سرّ التعبير بـ﴿حَتَّى تَأْتِيَهُمُ السَّاعَةُ بَغْتَةً أَوْ يَأْتِيَهُمْ عَذَابُ يَوْمٍ عَقِيمٍ﴾؟","answer":"حصر نهاية المرية في القيامة المفاجئة أو يوم لا خير بعده، فلا يولد فرصة جديدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص57–65.","url":""}]},{"id":"s22-63","number":63,"surah":22,"verses":[58],"verseLabel":"الحج: 58","question":"لماذا جمع للمهاجر المقتول والميت ﴿لَيَرْزُقَنَّهُمُ اللَّهُ رِزْقًا حَسَنًا﴾؟","answer":"سوّى من مات بسبب الجهاد ومن مات في طريقه في حسن الوعد والقبول.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص89–108.","url":""}]},{"id":"s22-64","number":64,"surah":22,"verses":[59],"verseLabel":"الحج: 59","question":"ما سرّ التعبير بـ﴿مُدْخَلًا يَرْضَوْنَهُ﴾؟","answer":"أبهم ﴿مدخلًا يرضونه﴾ لتذهب النفس في حسنه كل مذهب، وهو الجنة أو موضع كريم فيها؛ فوعدهم بدخول محقق جامع للرضا.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص89–108.","url":""}]},{"id":"s22-65","number":65,"surah":22,"verses":[60],"verseLabel":"الحج: 60","question":"لماذا قرن العفو بالغفور بعد الإذن بالمماثلة؟","answer":"من عاقب بقدر ظلمه لا يلام، ومع ذلك فتح الخاتمة باب العفو والمغفرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص109–127.","url":""}]},{"id":"s22-66","number":66,"surah":22,"verses":[61],"verseLabel":"الحج: 61","question":"ما سرّ التعبير بـ﴿يُولِجُ اللَّيْلَ فِي النَّهَارِ وَيُولِجُ النَّهَارَ فِي اللَّيْلِ﴾؟","answer":"الإيلاج إدخال تدريجي؛ صورة لزيادة أحدهما في الآخر تحت تدبير مستمر.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص128–141.","url":""}]},{"id":"s22-67","number":67,"surah":22,"verses":[63],"verseLabel":"الحج: 63","question":"لماذا تصبح الأرض بعد الماء ﴿مُخْضَرَّةً﴾ بالمضارع الوصفي؟","answer":"يستحضر التحول حيًا أمام العين بعد نزول المطر، دليل لطف يصل إلى دقائق النبات.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص160–179.","url":""}]},{"id":"s22-68","number":68,"surah":22,"verses":[65],"verseLabel":"الحج: 65","question":"ما سرّ التعبير بـ﴿وَيُمْسِكُ السَّمَاءَ أَنْ تَقَعَ عَلَى الْأَرْضِ﴾؟","answer":"بقاء النظام ليس عادة مستقلة؛ إمساك متجدد من الله يستحق الملاحظة والشكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص190–217.","url":""}]},{"id":"s22-69","number":69,"surah":22,"verses":[66],"verseLabel":"الحج: 66","question":"ما سرّ التعبير بـ﴿ثُمَّ يُحْيِيكُمْ إِنَّ الْإِنْسَانَ لَكَفُورٌ﴾؟","answer":"ذكر الإحياء بعد الإماتة ثم عجب من كفر الإنسان رغم إحاطته بهذه النعم.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص218–228.","url":""}]},{"id":"s22-70","number":70,"surah":22,"verses":[67],"verseLabel":"الحج: 67","question":"لماذا نهى النبي أن ينازعوه في ﴿الْأَمْرِ﴾؟","answer":"لكل أمة شريعة تعبدها الله بها، فلا يحول اختلاف المناسك إلى طعن في أصل الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص229–247.","url":""}]},{"id":"s22-71","number":71,"surah":22,"verses":[68,69],"verseLabel":"الحج: 68-69","question":"ما سرّ التعبير بقوله تعالى: ﴿وَإِنْ جَادَلُوكَ فَقُلِ اللَّهُ أَعْلَمُ بِمَا تَعْمَلُونَ﴾؟","answer":"حين يصير الجدل عنادًا ينتهي النقاش إلى علم الله وحكمه يوم الفصل.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص248–264.","url":""}]},{"id":"s22-72","number":72,"surah":22,"verses":[70],"verseLabel":"الحج: 70","question":"ما سرّ التعبير بـ﴿إِنَّ ذَلِكَ فِي كِتَابٍ﴾؟","answer":"علم الله ليس تخمينًا؛ كل شيء مثبت محفوظ، وكتابته هينة عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص265–280.","url":""}]},{"id":"s22-73","number":73,"surah":22,"verses":[71],"verseLabel":"الحج: 71","question":"ما سرّ وصف حجتهم بأنها ﴿مَا لَيْسَ لَهُمْ بِهِ عِلْمٌ﴾ بعد نفي السلطان؟","answer":"لا وحي لديهم ولا علم، فاجتمع فقد الدليل الخارجي واليقين الداخلي.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص281–293.","url":""}]},{"id":"s22-74","number":74,"surah":22,"verses":[72],"verseLabel":"الحج: 72","question":"لماذا يكاد الكافرون يسطون بالذين يتلون الآيات؟","answer":"عجزوا عن مقابلة البيان ببيان، فتحول اضطراب الوجوه إلى تهديد جسدي.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص294–315.","url":""}]},{"id":"s22-75","number":75,"surah":22,"verses":[73],"verseLabel":"الحج: 73","question":"لماذا ضُرب مثل الذباب للمعبودات؟","answer":"أضعف مخلوق يتحداهم: لا يخلقونه مجتمعين ولا يستردون ما يسلبه؛ فعجز الطالب والمطلوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص316–337.","url":""}]},{"id":"s22-76","number":76,"surah":22,"verses":[74],"verseLabel":"الحج: 74","question":"ما سرّ التعبير بـ﴿مَا قَدَرُوا اللَّهَ حَقَّ قَدْرِهِ﴾؟","answer":"من سوّى العاجز بالخالق لم يعرف عظمة الله ولا أنزله منزلته.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص338–342.","url":""}]},{"id":"s22-77","number":77,"surah":22,"verses":[75],"verseLabel":"الحج: 75","question":"ما سرّ التعبير بـ﴿اللَّهُ يَصْطَفِي مِنَ الْمَلَائِكَةِ رُسُلًا وَمِنَ النَّاسِ﴾؟","answer":"اختيار الرسل حق للخالق العالم، لا للمقترحين الذين يستبعدون بشرية الرسول.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص343–350.","url":""}]},{"id":"s22-78","number":78,"surah":22,"verses":[77],"verseLabel":"الحج: 77","question":"لماذا جمع ﴿ارْكَعُوا وَاسْجُدُوا وَاعْبُدُوا... وَافْعَلُوا الْخَيْرَ﴾؟","answer":"انتقل من أبرز أركان الصلاة إلى عموم العبادة ثم عموم الإحسان، فاستوعب طريق الفلاح.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص360–368.","url":""}]},{"id":"s22-79","number":79,"surah":22,"verses":[78],"verseLabel":"الحج: 78","question":"ما سرّ التعبير بـ﴿وَجَاهِدُوا فِي اللَّهِ حَقَّ جِهَادِهِ﴾؟","answer":"«في الله» تجعل الجهاد خالصًا لمرضاته، وحقه بذل الوسع في كل ما يقرب إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص369–398.","url":""}]},{"id":"s22-80","number":80,"surah":22,"verses":[78],"verseLabel":"الحج: 78","question":"ما سرّ التعبير بـ﴿هُوَ اجْتَبَاكُمْ وَمَا جَعَلَ عَلَيْكُمْ فِي الدِّينِ مِنْ حَرَجٍ﴾؟","answer":"الاصطفاء تكليف ميسر لا عنت فيه؛ المشقة العارضة غير الحرج الملازم.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص369–398.","url":""}]},{"id":"s22-81","number":81,"surah":22,"verses":[78],"verseLabel":"الحج: 78","question":"ما سرّ تسميتهم ﴿الْمُسْلِمِينَ مِنْ قَبْلُ وَفِي هَذَا﴾؟","answer":"الاستسلام لله هو الهوية الممتدة من ملة إبراهيم إلى القرآن، لا اسمًا حادثًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص369–398.","url":""}]},{"id":"s22-82","number":82,"surah":22,"verses":[78],"verseLabel":"الحج: 78","question":"لماذا ختم بـ﴿فَنِعْمَ الْمَوْلَى وَنِعْمَ النَّصِيرُ﴾؟","answer":"بعد أوامر العبادة والجهاد ذكّر أن الولاية والنصر منه، فلا يعتمد المجاهد على نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص369–398.","url":""}]},{"id":"s22-83","number":83,"surah":22,"verses":[19],"verseLabel":"الحج: 19","question":"ما سرّ الجمع في ﴿هَذَانِ خَصْمَانِ اخْتَصَمُوا فِي رَبِّهِمْ﴾ بعد اسم الإشارة للمثنى؟","answer":"ثُنّي ﴿خصمان﴾ باعتبار الفريقين، ثم جمع ﴿اختصموا﴾ باعتبار الأفراد الذين يضمهم كل فريق؛ فاختلاف العدد مقصود لا اضطراب فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص426–453.","url":""}]},{"id":"s23-1","number":1,"surah":23,"verses":[1],"verseLabel":"المؤمنون: 1","question":"لماذا افتتحت السورة بـ﴿قَدْ أَفْلَحَ الْمُؤْمِنُونَ﴾؟","answer":"جاءت ﴿قد﴾ لتحقيق الفلاح وتثبيته للمؤمنين قبل تفصيل صفاتهم؛ فيتشوف السامع إلى الأعمال التي استحقوا بها هذا الحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص414–445.","url":""}]},{"id":"s23-2","number":2,"surah":23,"verses":[2],"verseLabel":"المؤمنون: 2","question":"لماذا بدأت صفات المؤمنين بالخشوع في الصلاة؟","answer":"بدأ بالخشوع لأنه روح الصلاة وأظهر أثر حضور القلب بين يدي الله، ثم بنيت عليه بقية الصفات العملية.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص414–445.","url":""}]},{"id":"s23-3","number":3,"surah":23,"verses":[2],"verseLabel":"المؤمنون: 2","question":"ما سرّ التعبير بـ﴿فِي صَلَاتِهِمْ خَاشِعُونَ﴾ وقدم الظرف؟","answer":"قُدم ﴿في صلاتهم﴾ للاهتمام بموضع الخشوع، ويدل التركيب على ثبات وصفهم حال الصلاة لا على دعوى خشوع مطلقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص414–445.","url":""}]},{"id":"s23-4","number":4,"surah":23,"verses":[3],"verseLabel":"المؤمنون: 3","question":"ما سرّ وصفهم بالإعراض عن اللغو لا مجرد تركه؟","answer":"الإعراض ترك مع نفور وصرف للوجه، فلا يشغلهم الباطل ولا يستهويهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص414–445.","url":""}]},{"id":"s23-5","number":5,"surah":23,"verses":[4],"verseLabel":"المؤمنون: 4","question":"ما سرّ التعبير بـ﴿لِلزَّكَاةِ فَاعِلُونَ﴾ لا «مؤتون»؟","answer":"﴿فاعلون﴾ أوسع من ﴿مؤتون﴾ عند من حمل الزكاة على تطهير النفس والمال، وقيل المراد أداء الزكاة؛ واختيار الفعل يدل على مباشرتهم لها وعنايتهم بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص414–445.","url":""}]},{"id":"s23-6","number":6,"surah":23,"verses":[5,6,7],"verseLabel":"المؤمنون: 5-7","question":"ما سرّ التعبير بـ﴿لِفُرُوجِهِمْ حَافِظُونَ﴾؟","answer":"جعل العفة حراسة دائمة لحدود لا تُترك بلا مراقبة، ثم استثنى الطريق المشروع.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص414–445.","url":""}]},{"id":"s23-7","number":7,"surah":23,"verses":[8],"verseLabel":"المؤمنون: 8","question":"لماذا جُمعت ﴿أَمَانَاتِهِمْ وَعَهْدِهِمْ﴾؟","answer":"الأمانة ما اؤتمنوا عليه، والعهد ما التزموه؛ فاستوعب حقوق التسليم والالتزام.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص446–466.","url":""}]},{"id":"s23-8","number":8,"surah":23,"verses":[9],"verseLabel":"المؤمنون: 9","question":"لماذا ختم الصفات بالمحافظة على الصلوات بعد أن بدأ بالخشوع؟","answer":"بدأ بجوهر الصلاة وختم بدوامها وأوقاتها، فحاط العبادة قلبًا ونظامًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص446–466.","url":""}]},{"id":"s23-9","number":9,"surah":23,"verses":[10,11],"verseLabel":"المؤمنون: 10-11","question":"ما سرّ تسميتهم ﴿الْوَارِثُونَ﴾ ثم قال ﴿يَرِثُونَ الْفِرْدَوْسَ﴾؟","answer":"سموا وارثين لأن الفردوس يصير إليهم ملكًا ثابتًا، وقيل يرثون منازل غيرهم؛ وتكرار مادة الإرث يقرر اختصاصهم ودوام ملكهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص446–466.","url":""}]},{"id":"s23-10","number":10,"surah":23,"verses":[12],"verseLabel":"المؤمنون: 12","question":"ما سرّ التعبير بـ﴿مِنْ سُلَالَةٍ مِنْ طِينٍ﴾؟","answer":"السلالة ما يُستخرج برفق من الشيء؛ والمراد أصل الإنسان المستخرج من الطين في خلق آدم، أو ما يتولد من الغذاء الأرضي، فجمع اللفظ الأصل البعيد ومسار التكوين.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص467–491.","url":""}]},{"id":"s23-11","number":11,"surah":23,"verses":[13],"verseLabel":"المؤمنون: 13","question":"ما سرّ التعبير بـ﴿فِي قَرَارٍ مَكِينٍ﴾؟","answer":"الرحم موضع استقرار محكم يحفظ النطفة الضعيفة حتى يكتمل خلقها.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص467–491.","url":""}]},{"id":"s23-12","number":12,"surah":23,"verses":[14],"verseLabel":"المؤمنون: 14","question":"لماذا كرر ﴿فَخَلَقْنَا﴾ بين أطوار الجنين؟","answer":"تكرر ﴿فخلقنا﴾ لأن كل طور انتقال مقدر إلى هيئة جديدة، ودلت الفاء على التعاقب والاتصال بين المراحل.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص467–491.","url":""}]},{"id":"s23-13","number":13,"surah":23,"verses":[14],"verseLabel":"المؤمنون: 14","question":"ما سرّ التعبير بـ﴿ثُمَّ أَنْشَأْنَاهُ خَلْقًا آخَرَ﴾؟","answer":"جاءت ﴿ثم﴾ للانتقال إلى طور مغاير، وفسر ﴿خلقًا آخر﴾ بنفخ الروح وما ينشأ معه من خصائص الإنسان؛ فلا يحصر في مجرد اكتمال الأعضاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص467–491.","url":""}]},{"id":"s23-14","number":14,"surah":23,"verses":[14],"verseLabel":"المؤمنون: 14","question":"لماذا ختم بـ﴿فَتَبَارَكَ اللَّهُ أَحْسَنُ الْخَالِقِينَ﴾؟","answer":"تفصيل الخلق يورث التعظيم؛ صنعه بلغ الغاية مقارنة بكل تصوير وصنعة بشرية.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص467–491.","url":""}]},{"id":"s23-15","number":15,"surah":23,"verses":[15,16],"verseLabel":"المؤمنون: 15-16","question":"ما سرّ التعبير بـ﴿ثُمَّ إِنَّكُمْ بَعْدَ ذَلِكَ لَمَيِّتُونَ ثُمَّ... تُبْعَثُونَ﴾؟","answer":"المؤكدات تقرر مرحلتي الموت والبعث بعد مشهد الخلق، و«ثم» تفصل الانتقالين العظيمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص492–504.","url":""}]},{"id":"s23-16","number":16,"surah":23,"verses":[17],"verseLabel":"المؤمنون: 17","question":"ما سرّ التعبير بـ﴿سَبْعَ طَرَائِقَ﴾ عن السماوات؟","answer":"الطرائق طبقات بعضها فوق بعض، تستحضر نظام العلو ومساراته.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص492–504.","url":""}]},{"id":"s23-17","number":17,"surah":23,"verses":[18],"verseLabel":"المؤمنون: 18","question":"ما سرّ التعبير بـ﴿فَأَسْكَنَّاهُ فِي الْأَرْضِ﴾ عن الماء؟","answer":"نزوله لا يكفي؛ حفظه في العيون والآبار والتربة نعمة أخرى مستقلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص505–534.","url":""}]},{"id":"s23-18","number":18,"surah":23,"verses":[18],"verseLabel":"المؤمنون: 18","question":"ما سرّ التعبير بـ﴿وَإِنَّا عَلَى ذَهَابٍ بِهِ لَقَادِرُونَ﴾؟","answer":"هدد بسلب النعمة ليوقظ الشكر؛ من أسكن الماء قادر أن يغوره أو يفسده.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص505–534.","url":""}]},{"id":"s23-19","number":19,"surah":23,"verses":[19],"verseLabel":"المؤمنون: 19","question":"ما سرّ التعبير هنا بـ﴿فَوَاكِهُ كَثِيرَةٌ وَمِنْهَا تَأْكُلُونَ﴾، وفي الزخرف بـ﴿فَاكِهَةٌ... مِنْهَا تَأْكُلُونَ﴾؟","answer":"راعى الجمع هنا ذكر الجنات وكثرة الثمر، وجاءت الواو في ﴿ومنها تأكلون﴾ لأن منافع الفواكه لا تنحصر في الأكل؛ أما سياق الزخرف فوصف نعيم الجنة على نظم آخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص505–534.","url":""}]},{"id":"s23-20","number":20,"surah":23,"verses":[20],"verseLabel":"المؤمنون: 20","question":"لماذا خُصت شجرة طور سيناء بأنها ﴿تَنْبُتُ بِالدُّهْنِ وَصِبْغٍ لِلْآكِلِينَ﴾؟","answer":"جمعت الزيت الذي ينتفع به والإدام الذي يحسن الطعام، مع قداسة منشئها.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص505–534.","url":""}]},{"id":"s23-21","number":21,"surah":23,"verses":[21],"verseLabel":"المؤمنون: 21","question":"ما سرّ التعبير عن الأنعام بـ﴿نُسْقِيكُمْ مِمَّا فِي بُطُونِهَا﴾؟","answer":"لفت إلى خروج اللبن الخالص من داخل الحيوان، نعمة متجددة قريبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص535–553.","url":""}]},{"id":"s23-22","number":22,"surah":23,"verses":[22],"verseLabel":"المؤمنون: 22","question":"لماذا جمع الحمل على الأنعام والفلك؟","answer":"استوعب وسيلتي السفر في البر والبحر، وكلتاهما تسخير من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص535–553.","url":""}]},{"id":"s23-23","number":23,"surah":23,"verses":[23],"verseLabel":"المؤمنون: 23","question":"ما سرّ التعبير في قول نوح ﴿اعْبُدُوا اللَّهَ مَا لَكُمْ مِنْ إِلَهٍ غَيْرُهُ﴾؟","answer":"جمع الأمر بالتوحيد ونفي كل بديل، ثم حرّك الفطرة بسؤال التقوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص554–577.","url":""}]},{"id":"s23-24","number":24,"surah":23,"verses":[24,33],"verseLabel":"المؤمنون: 24، 33","question":"ما سرّ تقديم ﴿الَّذِينَ كَفَرُوا﴾ على ﴿مِنْ قَوْمِهِ﴾ في الآية 24، وتأخيره عنه في الآية 33؟","answer":"في الموضع الأول قصرت الصلة فجيء بـ﴿الذين كفروا من قومه﴾، وفي الثاني طالت الصلة بذكر التكذيب والترف، فقدم ﴿من قومه﴾ دفعًا للالتباس ومراعاة لسلامة النظم.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص554–577، و630–641.","url":""}]},{"id":"s23-25","number":25,"surah":23,"verses":[24],"verseLabel":"المؤمنون: 24","question":"ما سرّ التعبير في قولهم ﴿بَشَرٌ مِثْلُكُمْ يُرِيدُ أَنْ يَتَفَضَّلَ عَلَيْكُمْ﴾؟","answer":"حوّلوا الرسالة إلى طموح شخصي ليستنفروا حسد الناس ويصرفوهم عن الدليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص554–577.","url":""}]},{"id":"s23-26","number":26,"surah":23,"verses":[24],"verseLabel":"المؤمنون: 24","question":"ما سرّ التعبير بـ﴿وَلَوْ شَاءَ اللَّهُ﴾ هنا، وبـ﴿لَوْ شَاءَ رَبُّنَا﴾ في فصلت؟","answer":"سبق اسم الله في السياق الأول فناسب إظهاره، أما فصلت فسياقها حكى قولهم ﴿لو شاء ربنا﴾؛ فاختيار الاسمين تابع لمقام كل آية، لا ترادفًا مهملًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص554–577.","url":""}]},{"id":"s23-27","number":27,"surah":23,"verses":[25],"verseLabel":"المؤمنون: 25","question":"ما سرّ وصفهم نوحًا بأنه ﴿رَجُلٌ بِهِ جِنَّةٌ﴾؟","answer":"حين عجزوا عن حجته فسّروا مخالفته للجماعة بالجنون، ثم طلبوا انتظار موته.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص554–577.","url":""}]},{"id":"s23-28","number":28,"surah":23,"verses":[26],"verseLabel":"المؤمنون: 26","question":"لماذا اكتفى نوح بقوله ﴿رَبِّ انْصُرْنِي بِمَا كَذَّبُونِ﴾؟","answer":"فوّض صورة النصر إلى الله وذكر سببه: تكذيب الرسالة بعد البيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص578–597.","url":""}]},{"id":"s23-29","number":29,"surah":23,"verses":[27],"verseLabel":"المؤمنون: 27","question":"لماذا كان فوران التنور علامة الطوفان؟","answer":"جعل فوران التنور علامة معلومة لبدء الطوفان؛ وذُكرت في تعيين التنور أقوال متعددة، فلا يجزم بأنه موضع النار وحده وإن كان أشهرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص578–597.","url":""}]},{"id":"s23-30","number":30,"surah":23,"verses":[27],"verseLabel":"المؤمنون: 27","question":"ما سرّ التعبير بـ﴿مِنْ كُلٍّ زَوْجَيْنِ اثْنَيْنِ﴾؟","answer":"﴿زوجين﴾ يدل على الصنفين المقترنين، وجاء ﴿اثنين﴾ توكيدًا لكون المحمول من كل نوع فردين: ذكرًا وأنثى، ودفعًا لاحتمال إرادة الزوج بمعنى الواحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص578–597.","url":""}]},{"id":"s23-31","number":31,"surah":23,"verses":[28],"verseLabel":"المؤمنون: 28","question":"لماذا لقن نوحًا الحمد بعد النجاة؟","answer":"النجاة ليست مهارة السفينة وحدها؛ أول وصول آمن اعتراف بالمنعم.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص598–607.","url":""}]},{"id":"s23-32","number":32,"surah":23,"verses":[29],"verseLabel":"المؤمنون: 29","question":"لماذا دعا ﴿رَبِّ أَنْزِلْنِي مُنْزَلًا مُبَارَكًا﴾؟","answer":"لم يطلب مجرد اليابسة، بل مكانًا تحل فيه البركة بعد خراب العالم القديم.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص608–621.","url":""}]},{"id":"s23-33","number":33,"surah":23,"verses":[30],"verseLabel":"المؤمنون: 30","question":"ما سرّ التعبير بـ﴿وَإِنْ كُنَّا لَمُبْتَلِينَ﴾ بعد الطوفان؟","answer":"القصة كلها اختبار يميز المؤمن من المكذب، لا حدثًا طبيعيًا بلا غاية.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص608–621.","url":""}]},{"id":"s23-34","number":34,"surah":23,"verses":[31],"verseLabel":"المؤمنون: 31","question":"ما سرّ التعبير بـ﴿ثُمَّ أَنْشَأْنَا مِنْ بَعْدِهِمْ قَرْنًا آخَرِينَ﴾؟","answer":"تعاقب الأمم بعد الهلاك يثبت أن القدرة لا تعجز عن الإعادة وأن السنن تتكرر.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص622–629.","url":""}]},{"id":"s23-35","number":35,"surah":23,"verses":[33],"verseLabel":"المؤمنون: 33","question":"لماذا جمع الملأ بين الكفر والتكذيب بالآخرة والترف؟","answer":"العقيدة الفاسدة غذّاها الترف؛ خافوا أن تهدد الرسالة امتيازهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص630–641.","url":""}]},{"id":"s23-36","number":36,"surah":23,"verses":[34],"verseLabel":"المؤمنون: 34","question":"ما سرّ التعبير في قولهم ﴿وَلَئِنْ أَطَعْتُمْ بَشَرًا مِثْلَكُمْ إِنَّكُمْ إِذًا لَخَاسِرُونَ﴾؟","answer":"قلبوا الطاعة للحق خسارة لأنهم قاسوا القيادة بالطبقة لا بالوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص642–647.","url":""}]},{"id":"s23-37","number":37,"surah":23,"verses":[35,36],"verseLabel":"المؤمنون: 35-36","question":"لماذا كرروا استبعاد البعث ثم قالوا ﴿هَيْهَاتَ هَيْهَاتَ﴾؟","answer":"كرروا الاستبعاد ثم أكدوه بـ﴿هيهات هيهات﴾؛ وهي اسم فعل للبعد، وتكرارها للمبالغة في زعمهم بعد البعث، لا لإقامة حجة عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص648–654.","url":""}]},{"id":"s23-38","number":38,"surah":23,"verses":[37],"verseLabel":"المؤمنون: 37","question":"لماذا حصروا الحياة في ﴿حَيَاتُنَا الدُّنْيَا نَمُوتُ وَنَحْيَا﴾؟","answer":"جعلوا الموت والحياة تعاقب أجيال بلا بعث، فاختزلوا الوجود في المشهود.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص655–664.","url":""}]},{"id":"s23-39","number":39,"surah":23,"verses":[38],"verseLabel":"المؤمنون: 38","question":"لماذا اتهموه بأنه ﴿افْتَرَى عَلَى اللَّهِ كَذِبًا﴾؟","answer":"لم يستطيعوا إنكار اسم الله، فزعموا أن الرسول نسب إليه ما لم يقل.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص655–664.","url":""}]},{"id":"s23-40","number":40,"surah":23,"verses":[40],"verseLabel":"المؤمنون: 40","question":"ما سرّ التعبير بـ﴿عَمَّا قَلِيلٍ لَيُصْبِحُنَّ نَادِمِينَ﴾؟","answer":"قلل الزمن إلى العذاب، لكن الندم يأتي بعد انقطاع إمكان الرجوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص665–671.","url":""}]},{"id":"s23-41","number":41,"surah":23,"verses":[41],"verseLabel":"المؤمنون: 41","question":"ما سرّ التعبير بـ﴿فَجَعَلْنَاهُمْ غُثَاءً﴾؟","answer":"شبه قوتهم بزبد وحطام يحمله السيل؛ لا وزن له بعد الأخذ.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص672–680.","url":""}]},{"id":"s23-42","number":42,"surah":23,"verses":[42],"verseLabel":"المؤمنون: 42","question":"ما سرّ التعبير بـ﴿ثُمَّ أَنْشَأْنَا مِنْ بَعْدِهِمْ قُرُونًا آخَرِينَ﴾؟","answer":"كثرة القرون تؤكد تكرر الخلق والرسل والهلاك، وإن لم تفصل القصص كلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص672–680.","url":""}]},{"id":"s23-43","number":43,"surah":23,"verses":[43],"verseLabel":"المؤمنون: 43","question":"ما سرّ التعبير بـ﴿مَا تَسْبِقُ مِنْ أُمَّةٍ أَجَلَهَا وَمَا يَسْتَأْخِرُونَ﴾؟","answer":"نفى القدرة على التقديم والتأخير، فتحكم الله بالمواقيت كامل.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص681–687.","url":""}]},{"id":"s23-44","number":44,"surah":23,"verses":[44],"verseLabel":"المؤمنون: 44","question":"ما سرّ التعبير بـ﴿تَتْرَا﴾ عن إرسال الرسل؟","answer":"﴿تترى﴾ أي متتابعين يتبع بعضهم بعضًا مع فترات بينهم؛ فدل اللفظ على استمرار إرسال الحجة إلى الأمم.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص688–696.","url":""}]},{"id":"s23-45","number":45,"surah":23,"verses":[44],"verseLabel":"المؤمنون: 44","question":"لماذا جعل الأمم بعد التكذيب ﴿أَحَادِيثَ﴾؟","answer":"تحول وجودهم المادي إلى أخبار يتناقلها اللاحقون؛ غاية الزوال.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص688–696.","url":""}]},{"id":"s23-46","number":46,"surah":23,"verses":[46],"verseLabel":"المؤمنون: 46","question":"ما سرّ وصف فرعون وملئه بـ﴿فَاسْتَكْبَرُوا وَكَانُوا قَوْمًا عَالِينَ﴾؟","answer":"الاستكبار فعلهم في مواجهة موسى، والعلو صفة اجتماعية راسخة مهدت له.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص697–703.","url":""}]},{"id":"s23-47","number":47,"surah":23,"verses":[47],"verseLabel":"المؤمنون: 47","question":"ما سرّ التعبير في قولهم ﴿وَقَوْمُهُمَا لَنَا عَابِدُونَ﴾؟","answer":"استعملوا استعباد بني إسرائيل حجة لرفض رسوليهم؛ خلطوا السيادة السياسية بالحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص704–710.","url":""}]},{"id":"s23-48","number":48,"surah":23,"verses":[49],"verseLabel":"المؤمنون: 49","question":"ما سرّ التعبير بـ﴿لَعَلَّهُمْ يَهْتَدُونَ﴾ بعد إيتاء موسى الكتاب؟","answer":"الكتاب سبب هداية لا يجبر القلوب؛ تبقى الاستجابة اختيارًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص711–714.","url":""}]},{"id":"s23-49","number":49,"surah":23,"verses":[50],"verseLabel":"المؤمنون: 50","question":"لماذا جعل عيسى وأمه ﴿آيَةً﴾ بالإفراد؟","answer":"ميلادهما قصة آية واحدة مشتركة: أم تلد بلا أب.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص715–722.","url":""}]},{"id":"s23-50","number":50,"surah":23,"verses":[50],"verseLabel":"المؤمنون: 50","question":"لماذا آواهما إلى ﴿رَبْوَةٍ ذَاتِ قَرَارٍ وَمَعِينٍ﴾؟","answer":"جمع ارتفاع المكان واستقراره ومائه الجاري؛ حماية تتوافر فيها أسباب الحياة.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص715–722.","url":""}]},{"id":"s23-51","number":51,"surah":23,"verses":[51],"verseLabel":"المؤمنون: 51","question":"ما سرّ الخطاب للرسل جميعًا بـ﴿كُلُوا مِنَ الطَّيِّبَاتِ وَاعْمَلُوا صَالِحًا﴾؟","answer":"طيب المطعم يعين على صلاح العمل، ويبين وحدة منهج الرسل رغم تفرق أزمانهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص723–727.","url":""}]},{"id":"s23-52","number":52,"surah":23,"verses":[51],"verseLabel":"المؤمنون: 51","question":"ما سرّ ختام الآية هنا بـ﴿إِنِّي بِمَا تَعْمَلُونَ عَلِيمٌ﴾، وفي سبأ بـ﴿بَصِيرٌ﴾؟","answer":"اختير ﴿عليم﴾ هنا لمناسبة العلم بجميع أعمال الرسل وتنوعها، و﴿بصير﴾ في سبأ لمناسبة مراقبة عمل آل داود؛ مع اشتراك الاسمين في إحاطة الله بالأعمال.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص723–727.","url":""}]},{"id":"s23-53","number":53,"surah":23,"verses":[52],"verseLabel":"المؤمنون: 52","question":"ما سرّ التعبير بـ﴿وَأَنَا رَبُّكُمْ فَاتَّقُونِ﴾؟","answer":"وحدة الرب تقتضي وحدة الأمة وتقواه، لا تمزيق الدين إلى أحزاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص728–738.","url":""}]},{"id":"s23-54","number":54,"surah":23,"verses":[53],"verseLabel":"المؤمنون: 53","question":"ما سرّ التعبير بـ﴿فَتَقَطَّعُوا أَمْرَهُمْ بَيْنَهُمْ زُبُرًا﴾؟","answer":"شبه الدين الواحد بقطع وفرَق، كل جماعة أمسكت جزءًا وفرحت به.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص728–738.","url":""}]},{"id":"s23-55","number":55,"surah":23,"verses":[55,56],"verseLabel":"المؤمنون: 55-56","question":"لماذا سأل ﴿أَيَحْسَبُونَ أَنَّمَا نُمِدُّهُمْ بِهِ... نُسَارِعُ لَهُمْ فِي الْخَيْرَاتِ﴾؟","answer":"أبطل قياس الرضا بكثرة المال والولد؛ الإمداد قد يكون استدراجًا لا تكريمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص744–750.","url":""}]},{"id":"s23-56","number":56,"surah":23,"verses":[57],"verseLabel":"المؤمنون: 57","question":"ما سرّ التعبير بـ﴿مِنْ خَشْيَةِ رَبِّهِمْ مُشْفِقُونَ﴾؟","answer":"الإشفاق خوف مع عناية وحذر، ناشئ من معرفة الرب لا يأس من رحمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص751–758.","url":""}]},{"id":"s23-57","number":57,"surah":23,"verses":[60],"verseLabel":"المؤمنون: 60","question":"لماذا يؤتون ما آتوا وقلوبهم وجلة؟","answer":"ثبت في السنة أن الآية في المؤمنين الذين يعملون الطاعات ويخافون ألا تقبل منهم؛ فالوجل مع الإحسان ناشئ من الرجوع إلى الله، لا من اقتراف المعاصي وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص759–778.","url":""}]},{"id":"s23-58","number":58,"surah":23,"verses":[61],"verseLabel":"المؤمنون: 61","question":"ما سرّ التعبير بـ﴿يُسَارِعُونَ فِي الْخَيْرَاتِ وَهُمْ لَهَا سَابِقُونَ﴾؟","answer":"جمع المبادرة داخل ميادين الخير والسبق إلى ثمرتها وقبولها.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص759–778.","url":""}]},{"id":"s23-59","number":59,"surah":23,"verses":[62],"verseLabel":"المؤمنون: 62","question":"ما سرّ التعبير بـ﴿وَلَدَيْنَا كِتَابٌ يَنْطِقُ بِالْحَقِّ﴾؟","answer":"استعير النطق للكتاب لأن بيانه للحق وظهور ما سجل فيه بمنزلة كلام الناطق، وفيه تأكيد عدل الحساب وعدم ظلم أحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص779–790.","url":""}]},{"id":"s23-60","number":60,"surah":23,"verses":[63],"verseLabel":"المؤمنون: 63","question":"ما سرّ التعبير بـ﴿بَلْ قُلُوبُهُمْ فِي غَمْرَةٍ مِنْ هَذَا﴾؟","answer":"الغمرة ماء يغمر؛ صور قلوبهم محاطة بالغفلة عن الكتاب والحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص791–802.","url":""}]},{"id":"s23-61","number":61,"surah":23,"verses":[64],"verseLabel":"المؤمنون: 64","question":"لماذا يَجْأر المترفون عند العذاب؟","answer":"الجؤار رفع الصوت بالاستغاثة، وخص المترفين لأن النعمة أطغتهم ثم فوجئوا بالعذاب؛ لكن المصدر لا يجعل الترف وحده علة شدة الصوت حصرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص10–32.","url":""}]},{"id":"s23-62","number":62,"surah":23,"verses":[66],"verseLabel":"المؤمنون: 66","question":"ما سرّ التعبير بـ﴿عَلَى أَعْقَابِكُمْ تَنْكِصُونَ﴾؟","answer":"النكوص رجوع إلى الخلف بلا بصيرة؛ يسمعون الآيات ثم يرتدون عن التقدم.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص10–32.","url":""}]},{"id":"s23-63","number":63,"surah":23,"verses":[67],"verseLabel":"المؤمنون: 67","question":"ما سرّ وصف سمرهم بأنهم ﴿تَهْجُرُونَ﴾؟","answer":"في ﴿تهجرون﴾ قراءات ومعانٍ: من الهجر وترك الحق، أو الهُجر وهو الفحش في القول؛ فكان سمرهم متصلًا بالإعراض والطعن في القرآن.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص10–32.","url":""}]},{"id":"s23-64","number":64,"surah":23,"verses":[68],"verseLabel":"المؤمنون: 68","question":"لماذا سأل ﴿أَفَلَمْ يَدَّبَّرُوا الْقَوْلَ﴾؟","answer":"المطلوب تجاوز سماع الألفاظ إلى النظر في ترابطها ودلالتها التي تكشف صدقها.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص33–52.","url":""}]},{"id":"s23-65","number":65,"surah":23,"verses":[69],"verseLabel":"المؤمنون: 69","question":"ما سرّ التعبير بـ﴿أَمْ لَمْ يَعْرِفُوا رَسُولَهُمْ﴾؟","answer":"معرفتهم الطويلة بصدقه وأمانته حجة داخلية تبطل اتهامهم له.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص33–52.","url":""}]},{"id":"s23-66","number":66,"surah":23,"verses":[70],"verseLabel":"المؤمنون: 70","question":"ما سرّ التعبير بـ﴿وَلَوِ اتَّبَعَ الْحَقُّ أَهْوَاءَهُمْ لَفَسَدَتِ السَّمَاوَاتُ وَالْأَرْضُ﴾؟","answer":"الأهواء متناقضة، ولو صارت معيارًا للحق انهار نظام العالم والدين.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص33–52.","url":""}]},{"id":"s23-67","number":67,"surah":23,"verses":[72],"verseLabel":"المؤمنون: 72","question":"ما سرّ التعبير بـ﴿أَمْ تَسْأَلُهُمْ خَرْجًا فَخَرَاجُ رَبِّكَ خَيْرٌ﴾؟","answer":"الخَرْج ما يؤخذ من مال أو أجر، والخراج ما يتكرر أو ما يخرجه الله من رزق؛ والمعنى نفي طلب الأجر منهم، فما عند الله خير وهو خير الرازقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص64–71.","url":""}]},{"id":"s23-68","number":68,"surah":23,"verses":[73],"verseLabel":"المؤمنون: 73","question":"ما سرّ التعبير بـ﴿وَإِنَّكَ لَتَدْعُوهُمْ إِلَى صِرَاطٍ مُسْتَقِيمٍ﴾؟","answer":"أكد استقامة الدعوة بعد سرد أعذارهم، فالاعوجاج في استجابتهم لا في الطريق.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص72–82.","url":""}]},{"id":"s23-69","number":69,"surah":23,"verses":[74],"verseLabel":"المؤمنون: 74","question":"ما سرّ وصف المعرضين عن الآخرة بأنهم ﴿عَنِ الصِّرَاطِ لَنَاكِبُونَ﴾؟","answer":"النكوب ميل متعمد عن الطريق الواضح، لا ضياع عارض.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص72–82.","url":""}]},{"id":"s23-70","number":70,"surah":23,"verses":[75],"verseLabel":"المؤمنون: 75","question":"ما سرّ التعبير بـ﴿وَلَوْ رَحِمْنَاهُمْ وَكَشَفْنَا مَا بِهِمْ مِنْ ضُرٍّ لَلَجُّوا﴾؟","answer":"يكشف أن المشكلة ليست الألم؛ حتى زواله لا يصلح قلبًا اختار العناد.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص83–91.","url":""}]},{"id":"s23-71","number":71,"surah":23,"verses":[76],"verseLabel":"المؤمنون: 76","question":"ما سرّ التعبير بـ﴿فَمَا اسْتَكَانُوا لِرَبِّهِمْ وَمَا يَتَضَرَّعُونَ﴾؟","answer":"نفى الخضوع الباطن وإظهاره بالدعاء، فلم يؤد العذاب وظيفته فيهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص92–99.","url":""}]},{"id":"s23-72","number":72,"surah":23,"verses":[77],"verseLabel":"المؤمنون: 77","question":"ما سرّ التعبير بـ﴿إِذَا هُمْ فِيهِ مُبْلِسُونَ﴾؟","answer":"«إذا» تفاجئ بانقطاع رجائهم عند فتح باب عذاب شديد لا حيلة فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص100–107.","url":""}]},{"id":"s23-73","number":73,"surah":23,"verses":[78],"verseLabel":"المؤمنون: 78","question":"لماذا جمع السمع والأبصار والأفئدة؟","answer":"منافذ التلقي والحكم كلها نعم، لكن قلة الشكر عطلتها عن الهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص108–116.","url":""}]},{"id":"s23-74","number":74,"surah":23,"verses":[79],"verseLabel":"المؤمنون: 79","question":"ما سرّ التعبير بـ﴿ذَرَأَكُمْ فِي الْأَرْضِ﴾؟","answer":"الذرء بث وتكثير؛ من نشرهم في أقطارها قادر أن يجمعهم للحساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص117–122.","url":""}]},{"id":"s23-75","number":75,"surah":23,"verses":[80],"verseLabel":"المؤمنون: 80","question":"ما سرّ التعبير بـ﴿وَلَهُ اخْتِلَافُ اللَّيْلِ وَالنَّهَارِ﴾؟","answer":"اختصاصه بتعاقبهما وتفاوت أحوالهما دليل الملك والتدبير.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص123–132.","url":""}]},{"id":"s23-76","number":76,"surah":23,"verses":[82],"verseLabel":"المؤمنون: 82","question":"لماذا كرروا مقالة الأولين في استبعاد البعث؟","answer":"تشابه الاعتراض عبر القرون دليل تقليد لا اكتشاف؛ لم يأتوا بحجة جديدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص133–144.","url":""}]},{"id":"s23-77","number":77,"surah":23,"verses":[84,85,86,87,88,89],"verseLabel":"المؤمنون: 84-89","question":"لماذا تكرر سؤال ﴿لِمَنِ الْأَرْضُ﴾ و﴿مَنْ رَبُّ السَّمَاوَاتِ﴾ و﴿مَنْ بِيَدِهِ مَلَكُوتُ كُلِّ شَيْءٍ﴾؟","answer":"تدرجت الأسئلة من ملك الأرض ومن فيها، إلى ربوبية السماوات والعرش، إلى ملكوت كل شيء؛ وإقرارهم في كل مرة لله يلزمهم بالتوحيد والبعث.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص153–163.","url":""}]},{"id":"s23-78","number":78,"surah":23,"verses":[89],"verseLabel":"المؤمنون: 89","question":"لماذا ختم المحاجة بـ﴿فَأَنَّى تُسْحَرُونَ﴾؟","answer":"من يقر بهذه الحقائق ثم يشرك كأن عقله صُرف بالسحر عن لازم إقراره.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص172–182.","url":""}]},{"id":"s23-79","number":79,"surah":23,"verses":[91],"verseLabel":"المؤمنون: 91","question":"ما سرّ التعبير بـ﴿مَا اتَّخَذَ اللَّهُ مِنْ وَلَدٍ وَمَا كَانَ مَعَهُ مِنْ إِلَهٍ﴾؟","answer":"«من» تستغرق أي ولد أو إله، ثم برهن أن التعدد يفضي إلى الانفصال والتغالب.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص188–201.","url":""}]},{"id":"s23-80","number":80,"surah":23,"verses":[92],"verseLabel":"المؤمنون: 92","question":"لماذا جمع ﴿عَالِمِ الْغَيْبِ وَالشَّهَادَةِ﴾؟","answer":"جمع الغيب والشهادة لاستيعاب كل معلوم: ما غاب عن الخلق وما شهدوه؛ فالعلم المحيط من دلائل تنزهه عن شركهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص202–208.","url":""}]},{"id":"s23-81","number":81,"surah":23,"verses":[93,94],"verseLabel":"المؤمنون: 93-94","question":"لماذا دُعي النبي أن يقول ﴿رَبِّ إِمَّا تُرِيَنِّي مَا يُوعَدُونَ فَلَا تَجْعَلْنِي فِي الْقَوْمِ الظَّالِمِينَ﴾؟","answer":"تعليم باللجوء إلى الله عند نزول الفتن، فالقرابة المكانية لا تعصم بلا رحمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص209–215.","url":""}]},{"id":"s23-82","number":82,"surah":23,"verses":[96],"verseLabel":"المؤمنون: 96","question":"ما سرّ التعبير بـ﴿ادْفَعْ بِالَّتِي هِيَ أَحْسَنُ السَّيِّئَةَ﴾؟","answer":"لم يطلب مجرد المماثلة أو الترك، بل اختيار أجمل وسيلة تقطع الشر وتفتح باب الإصلاح.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص222–230.","url":""}]},{"id":"s23-83","number":83,"surah":23,"verses":[97,98],"verseLabel":"المؤمنون: 97-98","question":"لماذا استعاذ من همزات الشياطين ومن أن يحضروا؟","answer":"استعاذ من دوافع الشر ومن قرب أصحابها؛ السبب والبيئة معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص231–239.","url":""}]},{"id":"s23-84","number":84,"surah":23,"verses":[99,100],"verseLabel":"المؤمنون: 99-100","question":"ما سرّ مجيء طلب الرجوع بصيغة الجمع ﴿رَبِّ ارْجِعُونِ﴾؟","answer":"جاء ﴿ارجعون﴾ بالجمع مع نداء الرب المفرد، ووجه بالتعظيم أو بتكرير الطلب، وقيل الخطاب للملائكة؛ لذلك لا يحصر في تعليل واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج36، ص240–259.","url":""}]}]);
